QT_ISI(6,{"641":["(Allah tidak menyukai perkataan buruk yang diucapkan secara terus terang) dari siapa pun juga, artinya Dia pastilah akan memberinya hukuman (kecuali dari orang yang dianiaya) sehingga apabila dia mengucapkannya secara terus terang misalnya tentang keaniayaan yang dideritanya sehingga ia mendoakan si pelakunya, maka tidaklah dia akan menerima hukuman dari Allah. (Dan Allah Maha Mendengar) apa-apa yang diucapkan (lagi Maha Mengetahui) apa-apa yang diperbuat.",[["۞ لَّا","(Tidak) tidak"],["يُحِبُّ","cinta"],["ٱللَّهُ","Allah"],["ٱلْجَهْرَ","sebutan umum"],["بِٱلسُّوٓءِ","daripada kejahatan"],["مِنَ","[daripada]"],["ٱلْقَوْلِ","[the] perkataan"],["إِلَّا","kecuali"],["مَن","(oleh yang satu) siapa"],["ظُلِمَ ۚ","telah dizalimi"],["وَكَانَ","Dan adakah"],["ٱللَّهُ","Allah"],["سَمِيعًا","Maha Mendengar"],["عَلِيمًا","Maha Mengetahui"]]],"642":["(Jika kamu melahirkan) atau memperlihatkan (suatu kebaikan) di antara perbuatan-perbuatan baik (atau menyembunyikannya) artinya melakukannya secara sembunyi-sembunyi (atau memaafkan sesuatu kesalahan) atau keaniayaan orang lain (maka sesungguhnya Allah Maha Pemaaf lagi Maha Kuasa).",[["إِن","Jika"],["تُبْدُوا۟","kamu dedahkan"],["خَيْرًا","yang baik"],["أَوْ","atau"],["تُخْفُوهُ","kamu menyembunyikannya"],["أَوْ","atau"],["تَعْفُوا۟","maafkan"],["عَن","[daripada]"],["سُوٓءٍۢ","satu kejahatan"],["فَإِنَّ","maka sesungguhnya"],["ٱللَّهَ","Allah"],["كَانَ","ialah"],["عَفُوًّۭا","Selalu-Mengampuni"],["قَدِيرًا","Maha Berkuasa"]]],"643":["(Sesungguhnya orang-orang yang kafir kepada Allah dan rasul-rasul-Nya dan bermaksud akan membeda-bedakan di antara Allah dengan rasul-rasul-Nya) yakni dengan beriman kepada-Nya serta kafir terhadap mereka (serta mengatakan, \"Kami beriman kepada sebagian) di antara rasul-rasul itu (dan kami kafir terhadap yang lain\") dari mereka (serta bermaksud hendak mengambil di antara demikian) maksudnya di antara kufur dan iman (jalan) yang akan mereka tempuh.",[["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","orang yang"],["يَكْفُرُونَ","kufur"],["بِٱللَّهِ","kepada Allah"],["وَرُسُلِهِۦ","dan Rasul-rasulNya"],["وَيُرِيدُونَ","dan mereka mahu"],["أَن","bahawa"],["يُفَرِّقُوا۟","mereka membezakan"],["بَيْنَ","antara"],["ٱللَّهِ","Allah"],["وَرُسُلِهِۦ","dan Rasul-rasulNya"],["وَيَقُولُونَ","dan mereka berkata"],["نُؤْمِنُ","Kami beriman"],["بِبَعْضٍۢ","dalam beberapa"],["وَنَكْفُرُ","dan kami kufur"],["بِبَعْضٍۢ","pada orang lain"],["وَيُرِيدُونَ","Dan mereka mahu"],["أَن","bahawa"],["يَتَّخِذُوا۟","mereka ambil"],["بَيْنَ","antara"],["ذَٰلِكَ","bahawa"],["سَبِيلًا","satu cara"]]],"644":["(Merekalah orang-orang yang kafir sebenar-benarnya) haqqan adalah mashdar yang memperkuat isi kalimat sebelumnya (dan telah Kami sediakan bagi orang-orang yang kafir itu siksaan yang menghinakan) artinya azab neraka.",[["أُو۟لَـٰٓئِكَ","Itu"],["هُمُ","mereka"],["ٱلْكَـٰفِرُونَ","(ialah) orang-orang yang kafir"],["حَقًّۭا ۚ","sungguh"],["وَأَعْتَدْنَا","Dan telah Kami sediakan"],["لِلْكَـٰفِرِينَ","bagi orang-orang kafir"],["عَذَابًۭا","azab"],["مُّهِينًۭا","memalukan"]]],"645":["(Orang-orang yang beriman kepada Allah dan para rasul-Nya) artinya semua mereka (dan tidak membeda-bedakan seorang pun di antara mereka kelak Allah akan memberikan kepada mereka) dengan memakai nun atau ya (pahala mereka) artinya pahala amal perbuatan mereka (dan Allah Maha Pengampun) bagi kekasih-kekasih-Nya (lagi Maha Penyayang) kepada ahli taat-Nya.",[["وَٱلَّذِينَ","Dan orang yang"],["ءَامَنُوا۟","beriman"],["بِٱللَّهِ","kepada Allah"],["وَرُسُلِهِۦ","dan Rasul-rasulNya"],["وَلَمْ","dan bukan"],["يُفَرِّقُوا۟","mereka membezakan"],["بَيْنَ","antara"],["أَحَدٍۢ","(mana-mana) satu"],["مِّنْهُمْ","daripada mereka"],["أُو۟لَـٰٓئِكَ","mereka"],["سَوْفَ","tidak lama lagi"],["يُؤْتِيهِمْ","Dia akan memberi mereka"],["أُجُورَهُمْ ۗ","ganjaran mereka"],["وَكَانَ","Dan adakah"],["ٱللَّهُ","Allah"],["غَفُورًۭا","Selalu Memaafkan"],["رَّحِيمًۭا","Maha Mengasihani"]]],"646":["(Ahli Kitab meminta kepadamu) hai Muhammad; maksudnya orang-orang Yahudi (agar kamu menurunkan kepada mereka sebuah kitab dari langit) maksudnya sekaligus seperti pernah diturunkan-Nya kepada Musa guna mempersulit permintaan itu. Dan sekiranya menurut kamu itu berat (maka sesungguhnya mereka telah pernah meminta) maksudnya nenek moyang mereka (kepada Musa yang lebih besar dari itu, kata mereka, \"Perlihatkanlah Allah kepada kami dengan jelas.\") atau nyata. (Maka mereka disambar oleh petir) artinya maut sebagai hukuman bagi mereka (disebabkan keaniayaan mereka) yakni meminta barang yang sulit. (Kemudian mereka mengambil anak sapi) sebagai tuhan (setelah datang kepada mereka bukti-bukti yang nyata) artinya mukjizat-mukjizat atas kekuasaan Allah (maka Kami maafkan mereka dari hal yang demikian) dan tidak Kami basmi mereka secara tuntas (dan telah Kami berikan kepada Musa kekuasaan yang nyata) artinya keunggulan yang menakjubkan bagi mereka hingga sewaktu mereka disuruh membunuh diri mereka guna bertobat mereka pun menurutinya dengan patuh.",[["يَسْـَٔلُكَ","Tanya kamu"],["أَهْلُ","(the) Rakyat"],["ٱلْكِتَـٰبِ","Kitab"],["أَن","bahawa"],["تُنَزِّلَ","kamu turunkan"],["عَلَيْهِمْ","kepada mereka"],["كِتَـٰبًۭا","sebuah buku"],["مِّنَ","daripada"],["ٱلسَّمَآءِ ۚ","syurga itu"],["فَقَدْ","Maka sesungguhnya"],["سَأَلُوا۟","mereka (telah) bertanya"],["مُوسَىٰٓ","Musa"],["أَكْبَرَ","lebih besar"],["مِن","daripada"],["ذَٰلِكَ","bahawa"],["فَقَالُوٓا۟","kerana mereka berkata"],["أَرِنَا","Tunjukkan kepada kami"],["ٱللَّهَ","Allah"],["جَهْرَةًۭ","secara nyata"],["فَأَخَذَتْهُمُ","begitu melanda mereka"],["ٱلصَّـٰعِقَةُ","petir"],["بِظُلْمِهِمْ ۚ","kerana kesalahan mereka"],["ثُمَّ","Kemudian"],["ٱتَّخَذُوا۟","mereka ambil"],["ٱلْعِجْلَ","anak lembu (untuk disembah)"],["مِنۢ","daripada"],["بَعْدِ","selepas"],["مَا","[apa]"],["جَآءَتْهُمُ","datang kepada mereka"],["ٱلْبَيِّنَـٰتُ","bukti-bukti yang jelas"],["فَعَفَوْنَا","kemudian Kami ampunkan mereka"],["عَن","bagi"],["ذَٰلِكَ ۚ","bahawa"],["وَءَاتَيْنَا","Dan Kami berikan"],["مُوسَىٰ","Musa"],["سُلْطَـٰنًۭا","sebuah pihak berkuasa"],["مُّبِينًۭا","yang nyata"]]],"647":["(Dan Kami angkat ke atas kepada mereka Thur) nama sebuah bukit (disebabkan perjanjian dengan mereka) maksudnya hendak mengadakan perjanjian agar mereka takut dan bersedia menerimanya (dan kata Kami kepada mereka) sementara bukit itu dinaungkan kepada mereka (\"Masukilah pintu gerbang itu) maksudnya pintu gerbang kampung atau negeri (sambil bersujud\") yang menunjukkan ketundukkan (dan Kami wahyukan kepada mereka, \"Janganlah kamu melanggar perintah) menurut suatu qiraat dibaca ta`adduu dengan diidgamkan ta aslinya pada dal yang menjadi ta`taduu; artinya melanggar perintah (pada hari Sabtu\") dengan menangkap ikan padanya (dan Kami telah menerima perjanjian erat dari mereka) mengenai hal itu tetapi mereka melanggarnya.",[["وَرَفَعْنَا","Dan Kami bangkitkan"],["فَوْقَهُمُ","atas mereka"],["ٱلطُّورَ","gunung itu"],["بِمِيثَـٰقِهِمْ","untuk perjanjian mereka"],["وَقُلْنَا","dan Kami berfirman"],["لَهُمُ","kepada mereka"],["ٱدْخُلُوا۟","Masuk"],["ٱلْبَابَ","pintu pagar"],["سُجَّدًۭا","sujud"],["وَقُلْنَا","Dan Kami berfirman"],["لَهُمْ","kepada mereka"],["لَا","Jangan"],["تَعْدُوا۟","langgar"],["فِى","dalam"],["ٱلسَّبْتِ","hari Sabat"],["وَأَخَذْنَا","Dan Kami ambil"],["مِنْهُم","daripada mereka"],["مِّيثَـٰقًا","sebuah perjanjian"],["غَلِيظًۭا","sungguh-sungguh"]]],"648":["(Maka disebabkan mereka melanggar) ma merupakan tambahan; ba sababiyah berkaitan dengan yang dibuang, yang maksudnya: Kami kutuk mereka disebabkan mereka melanggar (perjanjian mereka dan karena kekafiran mereka terhadap ayat-ayat Allah dan pembunuhan yang mereka lakukan kepada nabi-nabi tanpa alasan yang benar dan kata mereka) kepada Nabi saw. (\"Hati kami tertutup\") tak dapat mendengar apa yang kamu katakan (bahkan Allah telah mengunci hati mereka itu disebabkan kekafiran mereka) hingga tak dapat mendengarkan nasihat dan pelajaran (oleh karena itu mereka tidak beriman kecuali sebagian kecil) dari mereka seperti Abdullah bin Salam dan kawan-kawannya.",[["فَبِمَا","Kemudian kerana"],["نَقْضِهِم","pecah mereka"],["مِّيثَـٰقَهُمْ","(dari) perjanjian mereka"],["وَكُفْرِهِم","dan kekufuran mereka"],["بِـَٔايَـٰتِ","dalam (the) Tanda-tanda"],["ٱللَّهِ","(milik) Allah"],["وَقَتْلِهِمُ","dan pembunuhan mereka"],["ٱلْأَنۢبِيَآءَ","(dari) para Nabi"],["بِغَيْرِ","tanpa"],["حَقٍّۢ","apa-apa hak"],["وَقَوْلِهِمْ","dan ucapan mereka"],["قُلُوبُنَا","hati kita"],["غُلْفٌۢ ۚ","(adalah) dibungkus"],["بَلْ","Bahkan"],["طَبَعَ","(telah) menetapkan meterai"],["ٱللَّهُ","Allah"],["عَلَيْهَا","pada (hati) mereka"],["بِكُفْرِهِمْ","kerana kekufuran mereka"],["فَلَا","jadi tidak"],["يُؤْمِنُونَ","mereka beriman"],["إِلَّا","kecuali"],["قَلِيلًۭا","beberapa"]]],"649":["(Dan karena kekafiran mereka) buat kedua kalinya yakni terhadap Isa, dan ba diulang-ulang menyebutkannya untuk memisah di antaranya dengan tempat mengathafkannya (dan tuduhan mereka terhadap Maryam berupa kedustaan besar) di mana mereka menuduhnya berbuat zina.",[["وَبِكُفْرِهِمْ","Dan kerana kekufuran mereka"],["وَقَوْلِهِمْ","dan ucapan mereka"],["عَلَىٰ","terhadap"],["مَرْيَمَ","Maryam"],["بُهْتَـٰنًا","satu fitnah"],["عَظِيمًۭا","yang besar"]]],"650":["(Serta karena ucapan mereka) dengan membanggakan diri (\"Sesungguhnya kami telah membunuh Almasih Isa putra Maryam utusan Allah\") yakni menurut dugaan dan pengakuan mereka. Artinya disebabkan semua itu Kami siksa mereka. Dan Allah berfirman menolak pengakuan mereka telah membunuhnya itu (padahal mereka tidak membunuhnya dan tidak pula menyalibnya tetapi diserupakan bagi mereka dengan Isa) maksudnya yang mereka bunuh dan mereka salib itu ialah sahabat mereka sendiri yang diserupakan Allah dengan Isa hingga mereka kira Nabi Isa sendiri. (Sesungguhnya orang-orang yang berselisih paham padanya) maksudnya pada Isa (sesungguhnya dalam keragu-raguan terhadapnya) maksudnya terhadap pembunuhan itu. Agar terlihat orang yang dibunuh itu, sebagian mereka berkata, \"Mukanya seperti muka Isa, tetapi tubuhnya lain, jadi sebenarnya bukan dia!\" Dan kata sebagian pula, \"Memang dia itu Isa!\" (mereka tidak mempunyai terhadapnya) maksudnya pembunuhan itu (keyakinan kecuali mengikuti persangkaan belaka) disebut sebagai istitsna munqathi'; artinya mereka hanya mengikuti dugaan-dugaan hasil khayal atau lamunan belaka (mereka tidak yakin telah membunuh Isa) menjadi hal yang menyangkal pembunuhan Isa itu.",[["وَقَوْلِهِمْ","Dan untuk ucapan mereka"],["إِنَّا","Sesungguhnya kami"],["قَتَلْنَا","dibunuh"],["ٱلْمَسِيحَ","Mesias"],["عِيسَى","Isa"],["ٱبْنَ","nak"],["مَرْيَمَ","(dari) Maryam"],["رَسُولَ","(the) Rasul"],["ٱللَّهِ","(milik) Allah"],["وَمَا","Dan tidak"],["قَتَلُوهُ","mereka membunuhnya"],["وَمَا","dan bukan"],["صَلَبُوهُ","mereka menyalibkan Dia"],["وَلَـٰكِن","tetapi"],["شُبِّهَ","ia dibuat untuk kelihatan (begitu)"],["لَهُمْ ۚ","kepada mereka"],["وَإِنَّ","Dan sesungguhnya"],["ٱلَّذِينَ","orang yang"],["ٱخْتَلَفُوا۟","berbeza"],["فِيهِ","di dalamnya"],["لَفِى","(ada) pasti dalam"],["شَكٍّۢ","keraguan"],["مِّنْهُ ۚ","mengenainya"],["مَا","Tidak"],["لَهُم","bagi mereka"],["بِهِۦ","mengenainya"],["مِنْ","[daripada]"],["عِلْمٍ","(sebarang) pengetahuan"],["إِلَّا","kecuali"],["ٱتِّبَاعَ","(yang) berikut"],["ٱلظَّنِّ ۚ","(dari) andaian"],["وَمَا","Dan tidak"],["قَتَلُوهُ","mereka membunuhnya"],["يَقِينًۢا","sudah tentu"]]],"651":["(Tetapi Allah telah mengangkatnya kepada-Nya dan Allah Maha Tangguh) dalam kerajaan-Nya (lagi Maha Bijaksana) dalam perbuatan-Nya.",[["بَل","Bahkan"],["رَّفَعَهُ","dia dibesarkan"],["ٱللَّهُ","(oleh) Allah"],["إِلَيْهِ ۚ","terhadapNya"],["وَكَانَ","Dan adakah"],["ٱللَّهُ","Allah"],["عَزِيزًا","Maha Perkasa"],["حَكِيمًۭا","Maha Bijaksana"]]],"652":["(Dan tidak ada di antara Ahli Kitab) seorang pun juga (kecuali akan beriman kepadanya) yakin kepada Isa (sebelum meninggalnya) artinya sebelum ahli Kitab itu meninggal di waktu ia melihat malaikat maut, tetapi keimanannya itu sudah tidak berguna lagi. Atau sebelum wafatnya Isa, yakni ketika dia turun dekat datangnya hari kiamat sebagaimana tercantum dalam sebuah hadis (Dan pada hari kiamat itu, ia) yakni Isa (akan menjadi saksi terhadap mereka) mengenai apa yang mereka lakukan sewaktu ia diutus kepada mereka dahulu.",[["وَإِن","Dan (ada) tidak"],["مِّنْ","daripada"],["أَهْلِ","(the) Rakyat"],["ٱلْكِتَـٰبِ","Kitab"],["إِلَّا","tetapi"],["لَيُؤْمِنَنَّ","pasti dia beriman"],["بِهِۦ","dalam dirinya"],["قَبْلَ","sebelum"],["مَوْتِهِۦ ۖ","kematiannya"],["وَيَوْمَ","Dan (pada) hari"],["ٱلْقِيَـٰمَةِ","Kiamat"],["يَكُونُ","dia akan jadi"],["عَلَيْهِمْ","terhadap mereka"],["شَهِيدًۭا","seorang saksi"]]],"653":["(Maka karena keaniayaan) artinya disebabkan keaniayaan (dari orang-orang Yahudi Kami haramkan atas mereka makanan yang baik-baik yang dihalalkan bagi mereka dulu) yakni yang tersebut dalam firman-Nya, \"Kami haramkan setiap yang berkuku...\" sampai akhir ayat (juga karena mereka menghalangi) manusia (dari jalan Allah) maksudnya agama-Nya (banyak).",[["فَبِظُلْمٍۢ","Kemudian untuk (kejahatan) itu"],["مِّنَ","daripada"],["ٱلَّذِينَ","orang yang"],["هَادُوا۟","adalah orang Yahudi"],["حَرَّمْنَا","Kami buat haram"],["عَلَيْهِمْ","bagi mereka"],["طَيِّبَـٰتٍ","perkara yang baik"],["أُحِلَّتْ","yang telah dihalalkan"],["لَهُمْ","bagi mereka"],["وَبِصَدِّهِمْ","dan untuk menghalang mereka"],["عَن","daripada"],["سَبِيلِ","jalan"],["ٱللَّهِ","(dari) Allah"],["كَثِيرًۭا","ramai"]]],"654":["(Dan karena memakan riba padahal telah dilarang daripadanya) dalam Taurat (dan memakan harta orang dengan jalan batil) dengan memberi suap dalam pengadilan (dan telah Kami sediakan untuk orang-orang kafir itu siksa yang pedih) atau menyakitkan.",[["وَأَخْذِهِمُ","Dan untuk pengambilan mereka"],["ٱلرِّبَوٰا۟","(dari) riba"],["وَقَدْ","sedangkan pastinya"],["نُهُوا۟","mereka dilarang"],["عَنْهُ","daripadanya"],["وَأَكْلِهِمْ","dan (untuk) memakannya"],["أَمْوَٰلَ","kekayaan"],["ٱلنَّاسِ","(daripada) rakyat"],["بِٱلْبَـٰطِلِ ۚ","secara salah"],["وَأَعْتَدْنَا","Dan telah Kami sediakan"],["لِلْكَـٰفِرِينَ","bagi orang-orang kafir"],["مِنْهُمْ","antara mereka"],["عَذَابًا","azab"],["أَلِيمًۭا","yang pedih"]]],"655":["(Tetapi orang-orang yang mendalam) artinya kukuh dan mantap (ilmunya di antara mereka) seperti Abdullah bin Salam (dan orang-orang mukmin) dari golongan Muhajirin dan Ansar (mereka beriman pada apa yang diturunkan kepadamu dan apa-apa yang diturunkan sebelummu) di antara kitab-kitab (sedangkan orang-orang yang mendirikan salat) manshub karena pujian, dan ada pula yang membacanya dengan marfu` (dan membayar zakat serta orang-orang yang beriman kepada Allah dan hari akhir, mereka itulah yang akan Kami beri) fi'ilnya dibaca dengan nun atau dengan ya (pahala yang besar) yakni surga.",[["لَّـٰكِنِ","Tetapi"],["ٱلرَّٰسِخُونَ","mereka yang tegas"],["فِى","dalam"],["ٱلْعِلْمِ","pengetahuan itu"],["مِنْهُمْ","antara mereka"],["وَٱلْمُؤْمِنُونَ","dan orang-orang yang beriman"],["يُؤْمِنُونَ","beriman"],["بِمَآ","pada apa"],["أُنزِلَ","(adalah) didedahkan"],["إِلَيْكَ","kepada kamu"],["وَمَآ","dan apa"],["أُنزِلَ","telah didedahkan"],["مِن","daripada"],["قَبْلِكَ ۚ","sebelum kamu"],["وَٱلْمُقِيمِينَ","Dan orang-orang yang mendirikan"],["ٱلصَّلَوٰةَ ۚ","solat"],["وَٱلْمُؤْتُونَ","dan orang yang memberi"],["ٱلزَّكَوٰةَ","zakat tersebut"],["وَٱلْمُؤْمِنُونَ","dan orang-orang yang beriman"],["بِٱللَّهِ","kepada Allah"],["وَٱلْيَوْمِ","dan Hari"],["ٱلْـَٔاخِرِ","yang Terakhir"],["أُو۟لَـٰٓئِكَ","mereka"],["سَنُؤْتِيهِمْ","Kami akan memberi mereka"],["أَجْرًا","ganjaran"],["عَظِيمًا","yang besar"]]],"656":["(Sesungguhnya Kami telah menurunkan wahyu kepadamu sebagaimana Kami telah menurunkannya kepada Nuh dan nabi-nabi sesudahnya dan) seperti (telah Kami turunkan kepada Ibrahim, Ismail, Ishak) yakni kedua putranya (serta Yakub) bin Ishak (dan anak-anaknya) yakni anak-anak Yakub (serta Isa, Ayub, Yunus, Harun, Sulaiman dan Kami datangkan kepada) bapaknya, yakni bapak dari Sulaiman (Daud Zabur) dibaca dengan fathah hingga artinya ialah nama kitab yang diturunkan, dan ada pula yang membaca dengan marfu` yaitu mashdar yang berarti mazbuura artinya yang tertulis.",[["۞ إِنَّآ","Sesungguhnya Kami"],["أَوْحَيْنَآ","telah mendedahkan"],["إِلَيْكَ","kepada kamu"],["كَمَآ","seperti"],["أَوْحَيْنَآ","Kami mendedahkan"],["إِلَىٰ","kepada"],["نُوحٍۢ","Nuh"],["وَٱلنَّبِيِّـۧنَ","dan para Nabi"],["مِنۢ","daripada"],["بَعْدِهِۦ ۚ","selepas dia"],["وَأَوْحَيْنَآ","dan Kami wahyukan"],["إِلَىٰٓ","kepada"],["إِبْرَٰهِيمَ","Ibrahim"],["وَإِسْمَـٰعِيلَ","dan Ismail"],["وَإِسْحَـٰقَ","dan Ishak"],["وَيَعْقُوبَ","dan Yaqub"],["وَٱلْأَسْبَاطِ","dan suku kaum"],["وَعِيسَىٰ","dan Isa"],["وَأَيُّوبَ","dan Ayyub"],["وَيُونُسَ","dan Yunus"],["وَهَـٰرُونَ","dan Harun"],["وَسُلَيْمَـٰنَ ۚ","dan Sulaiman"],["وَءَاتَيْنَا","dan Kami beri"],["دَاوُۥدَ","(kepada) Dawud"],["زَبُورًۭا","Zabor"]]],"657":["(Dan) telah Kami utus (rasul-rasul yang telah Kami kisahkan tentang mereka kepadamu dulu, dan rasul-rasul yang belum Kami kisahkan). Diriwayatkan bahwa Allah swt. mengirim delapan ribu orang nabi, empat ribu dari kalangan Bani Israel dan empat ribu lagi dari kalangan manusia lainnya ini dikatakan oleh Syekh dalam surah Ghafir. (Dan Allah telah berbicara dengan Musa sebenar berbicara) artinya secara langsung.",[["وَرُسُلًۭا","Dan Rasul-rasul"],["قَدْ","pasti"],["قَصَصْنَـٰهُمْ","Kami (telah) menyebut mereka"],["عَلَيْكَ","kepada kamu"],["مِن","daripada"],["قَبْلُ","sebelum"],["وَرُسُلًۭا","dan Rasul"],["لَّمْ","tidak"],["نَقْصُصْهُمْ","Kami (telah) menyebut mereka"],["عَلَيْكَ ۚ","kepada kamu"],["وَكَلَّمَ","Dan bercakap"],["ٱللَّهُ","Allah"],["مُوسَىٰ","(kepada) Musa"],["تَكْلِيمًۭا","(dalam a) perbualan"]]],"658":["(Yaitu rasul-rasul) menjadi badal bagi rasul-rasul yang sebelumnya (selalu pembawa berita gembira) dengan diberinya pahala kepada orang yang beriman (dan penyampaian peringatan) dengan adanya siksa kepada orang yang ingkar. Mereka Kami utus itu ialah (agar tidak ada lagi bagi manusia terhadap Allah alasan) yang dapat dikemukakan (setelah) pengiriman (rasul-rasul itu) kepada mereka, misalnya dengan mengatakan, \"Wahai Tuhan kami! Kenapa tidak Tuhan kirim kepada kami seorang rasul agar kami dapat mengikuti ayat-ayat-Mu dan menjadi orang-orang beriman!\" Maka Tuhan pun telah lebih dulu mengirimkan mereka untuk mematahkan alasan mereka tadi (Dan Allah Maha Tangguh) dalam kerajaan-Nya (lagi Maha Bijaksana) dalam perbuatan-Nya. Ayat berikut diturunkan tatkala orang-orang Yahudi ditanyai orang mengenai kenabian Muhammad saw. lalu mereka ingkari:",[["رُّسُلًۭا","Utusan"],["مُّبَشِّرِينَ","pembawa berita gembira"],["وَمُنذِرِينَ","dan pemberi amaran"],["لِئَلَّا","supaya tidak"],["يَكُونَ","ada"],["لِلنَّاسِ","untuk manusia"],["عَلَى","terhadap"],["ٱللَّهِ","Allah"],["حُجَّةٌۢ","sebarang hujah"],["بَعْدَ","selepas"],["ٱلرُّسُلِ ۚ","para Rasul"],["وَكَانَ","Dan adakah"],["ٱللَّهُ","Allah"],["عَزِيزًا","Maha Perkasa"],["حَكِيمًۭا","Maha Bijaksana"]]],"659":["(Tetapi Allah menyaksikan) artinya tentang kenabianmu (dengan apa yang diturunkan-Nya kepadamu) berupa Alquran yang menjadi mukjizat itu (diturunkan-Nya) sebagai hasil (dari ilmu-Nya) atau memuat ilmu-Nya (dan malaikat-malaikat pun menjadi saksi) pula atas kenabianmu itu. (Dan cukuplah Allah sebagai saksi)-nya.",[["لَّـٰكِنِ","Tetapi"],["ٱللَّهُ","Allah"],["يَشْهَدُ","menjadi saksi"],["بِمَآ","ke apa"],["أَنزَلَ","Dia (telah) mendedahkan"],["إِلَيْكَ ۖ","kepada kamu"],["أَنزَلَهُۥ","Dia telah menurunkannya"],["بِعِلْمِهِۦ ۖ","dengan IlmuNya"],["وَٱلْمَلَـٰٓئِكَةُ","dan para Malaikat"],["يَشْهَدُونَ ۚ","menjadi saksi"],["وَكَفَىٰ","Dan sudah memadai"],["بِٱللَّهِ","Allah"],["شَهِيدًا","(sebagai) seorang Saksi"]]],"660":["(Sesungguhnya orang-orang yang kafir) kepada Allah (dan menghalang-halangi) manusia (dari jalan Allah) artinya dari agama Islam dengan menyembunyikan ciri-ciri Nabi Muhammad saw.; maksudnya ialah orang-orang Yahudi (maka sesungguhnya mereka telah sesat sejauh-jauhnya) dari kebenaran.",[["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["وَصَدُّوا۟","dan menghalang"],["عَن","daripada"],["سَبِيلِ","jalan"],["ٱللَّهِ","(milik) Allah"],["قَدْ","pasti"],["ضَلُّوا۟","mereka telah sesat"],["ضَلَـٰلًۢا","sesat"],["بَعِيدًا","jauh sekali"]]],"661":["(Sesungguhnya orang-orang yang kafir) kepada Allah (dan berlaku aniaya) kepada nabi-Nya dengan menyembunyikan ciri-cirinya itu (maka Allah sekali-kali tidak akan mengampuni mereka dan tidak pula akan menunjukkan kepada mereka suatu jalan) di antara jalan-jalan yang banyak ini.",[["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["وَظَلَمُوا۟","dan melakukan kesalahan"],["لَمْ","tidak"],["يَكُنِ","kehendak"],["ٱللَّهُ","Allah"],["لِيَغْفِرَ","[untuk] memaafkan"],["لَهُمْ","mereka"],["وَلَا","dan bukan"],["لِيَهْدِيَهُمْ","Dia akan membimbing mereka"],["طَرِيقًا","(ke) jalan"]]],"662":["(Kecuali jalan neraka Jahanam) maksudnya jalan menuju ke sana (kekal mereka) artinya ditakdirkan kekal (di dalamnya) jika mereka telah memasukinya (buat selama-lamanya. Dan yang demikian itu bagi Allah mudah) artinya gampang dan tidak sulit adanya.",[["إِلَّا","Kecuali"],["طَرِيقَ","jalan"],["جَهَنَّمَ","(ke) Neraka"],["خَـٰلِدِينَ","berkekalan"],["فِيهَآ","di dalamnya"],["أَبَدًۭا ۚ","selama-lamanya"],["وَكَانَ","Dan adakah"],["ذَٰلِكَ","bahawa"],["عَلَى","bagi"],["ٱللَّهِ","Allah"],["يَسِيرًۭا","mudah"]]],"663":["(Hai manusia) maksudnya warga Mekah (sesungguhnya telah datang kepadamu rasul) yakni Muhammad saw. (membawa kebenaran dari Tuhanmu, maka berimanlah kamu) kepadanya (dan usahakanlah yang terbaik bagi kamu) dari apa yang melingkungimu (Dan jika kamu kafir) kepadanya (maka bagi-Nya apa yang di langit dan yang di bumi) baik sebagai milik maupun sebagai makhluk dan hamba hingga tidaklah merugikan kepada-Nya kekafiranmu itu (Dan Allah Maha Mengetahui) terhadap makhluk-Nya (lagi Maha Bijaksana) mengenai perbuatan-Nya terhadap mereka.",[["يَـٰٓأَيُّهَا","Wahai"],["ٱلنَّاسُ","manusia"],["قَدْ","pastinya"],["جَآءَكُمُ","telah datang kepada kamu"],["ٱلرَّسُولُ","Rasul"],["بِٱلْحَقِّ","dengan kebenaran"],["مِن","daripada"],["رَّبِّكُمْ","Tuhanmu"],["فَـَٔامِنُوا۟","jadi percayalah"],["خَيْرًۭا","(ia adalah) lebih baik"],["لَّكُمْ ۚ","bagi kamu"],["وَإِن","Tetapi jika"],["تَكْفُرُوا۟","kamu tidak beriman"],["فَإِنَّ","maka sesungguhnya"],["لِلَّهِ","kepada Allah (milik)"],["مَا","apa sahaja"],["فِى","(berada) dalam"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ ۚ","dan bumi"],["وَكَانَ","Dan adakah"],["ٱللَّهُ","Allah"],["عَلِيمًا","Maha Mengetahui"],["حَكِيمًۭا","Maha Bijaksana"]]],"664":["(Hai Ahli kitab) maksudnya kitab Injil (janganlah kamu melampaui batas dalam agamamu dan janganlah kamu katakan terhadap Allah kecuali) ucapan (yang benar) yaitu menyucikan-Nya dari kemusyrikan dan mempunyai anak. (Sesungguhnya Almasih Isa putra Maryam itu adalah utusan Allah dan kalimat-Nya yang diucapkan-Nya) atau disampaikan-Nya (kepada Maryam dan roh) artinya yang mempunyai roh (daripada-Nya) diidhafatkan kepada Allah swt. demi untuk memuliakan-Nya dan bukanlah sebagai dugaan kamu bahwa dia adalah anak Allah atau Tuhan bersama-Nya atau salah satu dari oknum yang tiga. Karena sesuatu yang mempunyai roh itu tersusun sedangkan Tuhan Maha Suci dari tersusun dan dari dinisbatkannya tersusun itu kepada-Nya (Maka berimanlah kamu kepada Allah dan kepada rasul-rasul-Nya dan janganlah kamu katakan) bahwa Tuhan itu (tiga) yakni Allah, Isa dan ibunya (hentikanlah) demikian itu (dan perbuatlah yang lebih baik bagi kamu) yakni bertauhid (Sesungguhnya Allah Tuhan Yang Maha Esa Maha Suci Dia) artinya bersih dan terhindar (dari mempunyai anak. Bagi-Nya apa yang terdapat di langit dan yang di bumi) baik sebagai makhluk maupun sebagai milik dan hamba sedangkan pemiliknya itu bertentangan dengan mempunyai anak (Dan cukuplah Allah sebagai wakil) atau saksi atas demikian itu.",[["يَـٰٓأَهْلَ","Wahai Rakyat"],["ٱلْكِتَـٰبِ","Kitab"],["لَا","Jangan"],["تَغْلُوا۟","melakukan lebihan"],["فِى","dalam"],["دِينِكُمْ","agama kamu"],["وَلَا","dan jangan"],["تَقُولُوا۟","berkata"],["عَلَى","tentang"],["ٱللَّهِ","Allah"],["إِلَّا","kecuali"],["ٱلْحَقَّ ۚ","kebenaran"],["إِنَّمَا","Hanya"],["ٱلْمَسِيحُ","Mesias"],["عِيسَى","Isa"],["ٱبْنُ","nak"],["مَرْيَمَ","(dari) Maryam"],["رَسُولُ","(adalah) seorang Rasul"],["ٱللَّهِ","(milik) Allah"],["وَكَلِمَتُهُۥٓ","dan firman-Nya"],["أَلْقَىٰهَآ","yang Dia sampaikan"],["إِلَىٰ","kepada"],["مَرْيَمَ","Maryam"],["وَرُوحٌۭ","dan semangat"],["مِّنْهُ ۖ","daripadaNya"],["فَـَٔامِنُوا۟","Jadi percayalah"],["بِٱللَّهِ","kepada Allah"],["وَرُسُلِهِۦ ۖ","dan Rasul-rasulNya"],["وَلَا","Dan jangan"],["تَقُولُوا۟","berkata"],["ثَلَـٰثَةٌ ۚ","Tiga"],["ٱنتَهُوا۟","berhenti"],["خَيْرًۭا","(ia adalah) lebih baik"],["لَّكُمْ ۚ","bagi kamu"],["إِنَّمَا","Hanya"],["ٱللَّهُ","Allah"],["إِلَـٰهٌۭ","(ialah) Tuhan"],["وَٰحِدٌۭ ۖ","satu"],["سُبْحَـٰنَهُۥٓ","Maha Suci Dia"],["أَن","Itu"],["يَكُونَ","Dia (sepatutnya) ada"],["لَهُۥ","untuk Dia"],["وَلَدٌۭ ۘ","seorang anak lelaki"],["لَّهُۥ","KepunyaanNya (milik)"],["مَا","apa sahaja"],["فِى","(berada) dalam"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَمَا","dan apa sahaja"],["فِى","(berada) dalam"],["ٱلْأَرْضِ ۗ","bumi"],["وَكَفَىٰ","Dan sudah memadai"],["بِٱللَّهِ","Allah"],["وَكِيلًۭا","(sebagai) Pelupus urusan"]]],"665":["(Almasih tidak merasa malu) maksudnya Almasih yang kamu katakan sebagai Tuhan itu tidak merasa enggan dan takabur (menjadi hamba bagi Allah dan tidak pula enggan malaikat-malaikat yang terdekat) kepada Allah mereka juga tidak malu untuk menjadi hamba-Nya. Ini suatu kalimat selang yang terbaik yang dikemukakan untuk menolak anggapan sementara orang bahwa mereka adalah Tuhan atau putri-putri Allah sebagaimana kalimat yang sebelumnya digunakan untuk menolak anggapan kaum Nasrani bahwa Isa adalah putra-Nya. (Siapa yang enggan untuk menyembah-Nya dan menyombongkan diri maka kelak Allah akan mengumpulkan mereka semua kepada-Nya) yakni di akhirat.",[["لَّن","tidak pernah"],["يَسْتَنكِفَ","akan menghina"],["ٱلْمَسِيحُ","Mesias"],["أَن","kepada"],["يَكُونَ","jadilah"],["عَبْدًۭا","seorang hamba"],["لِّلَّهِ","daripada Allah"],["وَلَا","dan bukan"],["ٱلْمَلَـٰٓئِكَةُ","para Malaikat"],["ٱلْمُقَرَّبُونَ ۚ","orang-orang yang dekat (kepada Allah)"],["وَمَن","Dan sesiapa"],["يَسْتَنكِفْ","penghinaan"],["عَنْ","daripada"],["عِبَادَتِهِۦ","ibadatnya"],["وَيَسْتَكْبِرْ","dan sombong"],["فَسَيَحْشُرُهُمْ","kemudian Dia akan mengumpulkan mereka"],["إِلَيْهِ","terhadapNya"],["جَمِيعًۭا","semua bersama"]]],"666":["(Adapun orang-orang yang beriman dan beramal saleh maka Allah akan menyempurnakan ganjaran mereka) artinya pahala dari amal perbuatan mereka itu (dan menambah untuk mereka dari karunia-Nya) yakni yang belum pernah dilihat oleh mata, tidak didengar telinga dan tidak pula terdetik dalam hati manusia. (Adapun orang-orang yang malu dan menyombongkan diri) dari mengabdikan diri kepada-Nya (maka akan disiksa-Nya mereka dengan siksaan yang pedih) atau menyakitkan yaitu siksa neraka (dan mereka tidak akan memperoleh bagian bagi diri mereka selain daripada Allah, pelindung) yang akan melindungi diri mereka (dan tidak pula pembela) yang akan menolong mereka.",[["فَأَمَّا","Kemudian untuk"],["ٱلَّذِينَ","orang yang"],["ءَامَنُوا۟","beriman"],["وَعَمِلُوا۟","dan lakukan"],["ٱلصَّـٰلِحَـٰتِ","perbuatan yang soleh"],["فَيُوَفِّيهِمْ","maka Dia akan memberi mereka sepenuhnya"],["أُجُورَهُمْ","ganjaran mereka"],["وَيَزِيدُهُم","dan berikan mereka lebih"],["مِّن","daripada"],["فَضْلِهِۦ ۖ","Bounty-Nya"],["وَأَمَّا","Dan untuk"],["ٱلَّذِينَ","orang yang"],["ٱسْتَنكَفُوا۟","dihina"],["وَٱسْتَكْبَرُوا۟","dan bersikap sombong"],["فَيُعَذِّبُهُمْ","maka Dia akan mengazab mereka"],["عَذَابًا","(dengan) hukuman"],["أَلِيمًۭا","yang pedih"],["وَلَا","dan bukan"],["يَجِدُونَ","adakah mereka akan dapati"],["لَهُم","untuk diri mereka sendiri"],["مِّن","daripada"],["دُونِ","selain"],["ٱللَّهِ","Allah"],["وَلِيًّۭا","mana-mana pelindung"],["وَلَا","dan bukan"],["نَصِيرًۭا","mana-mana pembantu"]]],"667":["(Hai manusia, sesungguhnya telah datang kepadamu keterangan) bukti kebenaran (dari Tuhanmu) yaitu Nabi saw. (dan telah Kami turunkan kepadamu cahaya yang terang) benderang yakni Alquran.",[["يَـٰٓأَيُّهَا","Wahai"],["ٱلنَّاسُ","manusia"],["قَدْ","pastinya"],["جَآءَكُم","telah datang kepada kamu"],["بُرْهَـٰنٌۭ","satu bukti yang meyakinkan"],["مِّن","daripada"],["رَّبِّكُمْ","Tuhanmu"],["وَأَنزَلْنَآ","dan Kami (telah) menurunkannya"],["إِلَيْكُمْ","kepada kamu"],["نُورًۭا","sebuah cahaya"],["مُّبِينًۭا","yang nyata"]]],"668":["(Adapun orang-orang yang beriman kepada Allah dan berpegang teguh kepada-Nya, maka Allah akan memasukkan mereka ke dalam rahmat dan limpahan karunia-Nya dan membimbing mereka ke jalan yang lurus menuju kepada-Nya) yakni agama Islam.",[["فَأَمَّا","Jadi untuk"],["ٱلَّذِينَ","orang yang"],["ءَامَنُوا۟","beriman"],["بِٱللَّهِ","kepada Allah"],["وَٱعْتَصَمُوا۟","dan berpegang teguh"],["بِهِۦ","kepada-Nya"],["فَسَيُدْخِلُهُمْ","kemudian Dia akan memasukkan mereka"],["فِى","dalam"],["رَحْمَةٍۢ","belas kasihan"],["مِّنْهُ","daripada diriNya sendiri"],["وَفَضْلٍۢ","dan Bounty"],["وَيَهْدِيهِمْ","dan akan membimbing mereka"],["إِلَيْهِ","kepada diriNya"],["صِرَٰطًۭا","(dalam) jalan"],["مُّسْتَقِيمًۭا","lurus"]]],"669":["(Mereka meminta fatwa kepadamu) mengenai kalalah, yaitu jika seseorang meninggal dunia tanpa meninggalkan bapak dan anak (Katakanlah, \"Allah memberi fatwa kepadamu tentang kalalah; jika seseorang) umru-un menjadi marfu' dengan fi'il yang menafsirkannya (celaka) maksudnya meninggal dunia (dan dia tidak mempunyai anak) dan tidak pula bapak yakni yang dimaksud dengan kalalah tadi (tetapi mempunyai seorang saudara perempuan) baik sekandung maupun sebapak (maka bagi saudaranya yang perempuan itu seperdua dari harta yang ditinggalkannya, dan dia) maksudnya saudaranya yang laki-laki (mewarisi saudaranya yang perempuan) pada seluruh harta peninggalannya (yakni jika ia tidak mempunyai anak). Sekiranya ia mempunyai seorang anak laki-laki, maka tidak satu pun diperolehnya, tetapi jika anaknya itu perempuan, maka saudaranya itu masih memperoleh kelebihan dari bagian anaknya. Dan sekiranya saudara laki-laki atau saudara perempuan itu seibu, maka bagiannya ialah seperenam sebagaimana telah diterangkan di awal surah. (Jika mereka itu) maksudnya saudara perempuan (dua orang) atau lebih, karena ayat ini turun mengenai Jabir; ia meninggal dunia dengan meninggalkan beberapa orang saudara perempuan (maka bagi keduanya dua pertiga dari harta peninggalan) saudara laki-laki mereka. (Dan jika mereka) yakni ahli waris itu terdiri dari (saudara laki-laki dan perempuan, maka bagian seorang laki-laki) di antara mereka (sebanyak bagian dua orang perempuan.\" Allah menerangkan kepadamu syariat-syariat agama-Nya (agar kamu) tidak (sesat. Dan Allah Maha Mengetahui segala sesuatu) di antaranya tentang pembagian harta warisan. Diriwayatkan oleh Bukhari dan Muslim dari Barra bahwa ia merupakan ayat yang terakhir diturunkan, maksudnya mengenai faraid.",[["يَسْتَفْتُونَكَ","Mereka mencari keputusan kamu"],["قُلِ","Katakanlah"],["ٱللَّهُ","Allah"],["يُفْتِيكُمْ","memberi kamu ketetapan"],["فِى","tentang"],["ٱلْكَلَـٰلَةِ ۚ","Kalala"],["إِنِ","jika"],["ٱمْرُؤٌا۟","seorang lelaki"],["هَلَكَ","meninggal dunia"],["لَيْسَ","(dan) tidak"],["لَهُۥ","dia ada"],["وَلَدٌۭ","seorang kanak-kanak"],["وَلَهُۥٓ","dan dia ada"],["أُخْتٌۭ","seorang kakak"],["فَلَهَا","kemudian untuk dia"],["نِصْفُ","(adalah) setengah"],["مَا","apa"],["تَرَكَ ۚ","dia pergi"],["وَهُوَ","Dan dia"],["يَرِثُهَآ","akan mewarisi daripadanya"],["إِن","jika"],["لَّمْ","tidak"],["يَكُن","ialah"],["لَّهَا","untuk dia"],["وَلَدٌۭ ۚ","seorang kanak-kanak"],["فَإِن","Tetapi jika"],["كَانَتَا","ada"],["ٱثْنَتَيْنِ","dua perempuan"],["فَلَهُمَا","kemudian untuk mereka"],["ٱلثُّلُثَانِ","dua pertiga"],["مِمَّا","tentang apa"],["تَرَكَ ۚ","dia pergi"],["وَإِن","Tetapi jika"],["كَانُوٓا۟","mereka adalah"],["إِخْوَةًۭ","adik beradik"],["رِّجَالًۭا","lelaki"],["وَنِسَآءًۭ","dan wanita"],["فَلِلذَّكَرِ","maka jantan akan mempunyai"],["مِثْلُ","suka"],["حَظِّ","kongsi"],["ٱلْأُنثَيَيْنِ ۗ","(dari) dua perempuan itu"],["يُبَيِّنُ","membuat jelas"],["ٱللَّهُ","Allah"],["لَكُمْ","kepada kamu"],["أَن","jangan-jangan"],["تَضِلُّوا۟ ۗ","kamu sesat"],["وَٱللَّهُ","Dan Allah"],["بِكُلِّ","daripada setiap"],["شَىْءٍ","perkara"],["عَلِيمٌۢ","Maha Mengetahui"]]],"670":["(Hai orang-orang yang beriman, penuhilah olehmu perjanjian itu) baik perjanjian yang terpatri di antara kamu dengan Allah maupun dengan sesama manusia. (Dihalalkan bagi kamu binatang ternak) artinya halal memakan unta, sapi dan kambing setelah hewan itu disembelih (kecuali apa yang dibacakan padamu) tentang pengharamannya dalam ayat, \"Hurrimat `alaikumul maitatu...\" Istitsna` atau pengecualian di sini munqathi` atau terputus tetapi dapat pula muttashil, misalnya yang diharamkan karena mati dan sebagainya (tanpa menghalalkan berburu ketika kamu mengerjakan haji) atau berihram; ghaira dijadikan manshub karena menjadi hal bagi dhamir yang terdapat pada lakum. (Sesungguhnya Allah menetapkan hukum menurut yang dikehendaki-Nya) baik menghalalkan maupun mengharamkannya tanpa seorang pun yang dapat menghalangi-Nya.",[["يَـٰٓأَيُّهَا","Wahai"],["ٱلَّذِينَ","kamu (siapa)"],["ءَامَنُوٓا۟","beriman"],["أَوْفُوا۟","penuhi"],["بِٱلْعُقُودِ ۚ","kontrak-kontrak tersebut"],["أُحِلَّتْ","Dihalalkan"],["لَكُم","bagi kamu"],["بَهِيمَةُ","yang berkaki empat"],["ٱلْأَنْعَـٰمِ","(dari) ternakan ragut"],["إِلَّا","kecuali"],["مَا","apa"],["يُتْلَىٰ","dibacakan"],["عَلَيْكُمْ","pada kamu"],["غَيْرَ","tidak"],["مُحِلِّى","sedang dibenarkan"],["ٱلصَّيْدِ","(untuk) memburu"],["وَأَنتُمْ","sedangkan kamu"],["حُرُمٌ ۗ","(berada dalam) Ihram"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["يَحْكُمُ","dekri"],["مَا","apa"],["يُرِيدُ","Dia kehendaki"]]],"671":["(Hai orang-orang yang beriman, janganlah kamu melanggar syiar-syiar Allah) jamak sya`iiratun; artinya upacara-upacara agama-Nya. Melanggar yaitu dengan berburu di waktu ihram (dan jangan pula melanggar bulan haram) dengan melakukan peperangan padanya (dan jangan mengganggu binatang-binatang hadya) yakni hewan yang dihadiahkan buat tanah suci (serta binatang-binatang berkalung) jamak dari qilaadatun; artinya binatang yang diberi kalung dengan kayu-kayuan yang terdapat di tanah suci sebagai tanda agar ia aman, maka janganlah ada yang mengganggu baik hewan-hewan itu sendiri maupun para pemiliknya (jangan pula) kamu halalkan atau kamu ganggu (orang-orang yang berkunjung) atau menuju (Baitulharam) dengan memerangi mereka (sedangkan mereka mencari karunia) artinya rezeki (dari Tuhan mereka) dengan berniaga (dan keridaan) daripada-Nya di samping berkunjung ke Baitullah tidak seperti pengertian mereka yang salah itu. Ayat ini dimansukh oleh ayat Bara`ah. (Dan apabila kamu telah selesai) dari ihram (maka perintahlah berburu) perintah di sini berarti ibahah atau memperbolehkan (dan sekali-kali janganlah kamu terdorong oleh kebencian) dibaca syana-aanu atau syan-aanu berarti kebencian atau kemarahan (kepada suatu kaum disebabkan mereka telah menghalangi kamu dari Masjidilharam untuk berbuat aniaya) kepada mereka dengan pembunuhan dan sebagainya. (Bertolong-tolonglah kamu dalam kebaikan) dalam mengerjakan yang dititahkan (dan ketakwaan) dengan meninggalkan apa-apa yang dilarang (dan janganlah kamu bertolong-tolongan) pada ta`aawanu dibuang salah satu di antara dua ta pada asalnya (dalam berbuat dosa) atau maksiat (dan pelanggaran) artinya melampaui batas-batas ajaran Allah. (Dan bertakwalah kamu kepada Allah) takutlah kamu kepada azab siksa-Nya dengan menaati-Nya (sesungguhnya Allah amat berat siksa-Nya) bagi orang yang menentang-Nya.",[["يَـٰٓأَيُّهَا","Wahai"],["ٱلَّذِينَ","kamu (siapa)"],["ءَامَنُوا۟","beriman"],["لَا","Jangan"],["تُحِلُّوا۟","melanggar"],["شَعَـٰٓئِرَ","(the) upacara"],["ٱللَّهِ","(milik) Allah"],["وَلَا","dan bukan"],["ٱلشَّهْرَ","bulan tersebut"],["ٱلْحَرَامَ","yang suci"],["وَلَا","dan bukan"],["ٱلْهَدْىَ","binatang korban"],["وَلَا","dan bukan"],["ٱلْقَلَـٰٓئِدَ","kalungan bunga"],["وَلَآ","dan bukan"],["ءَآمِّينَ","(yang) datang"],["ٱلْبَيْتَ","(ke) Dewan"],["ٱلْحَرَامَ","yang Suci"],["يَبْتَغُونَ","mencari"],["فَضْلًۭا","Bounty"],["مِّن","daripada"],["رَّبِّهِمْ","Tuhan mereka"],["وَرِضْوَٰنًۭا ۚ","dan senang hati"],["وَإِذَا","Dan apabila"],["حَلَلْتُمْ","kamu keluar dari Ihram"],["فَٱصْطَادُوا۟ ۚ","kemudian (kamu boleh) memburu"],["وَلَا","Dan jangan biarkan"],["يَجْرِمَنَّكُمْ","menghasut kamu"],["شَنَـَٔانُ","(the) kebencian"],["قَوْمٍ","(untuk) suatu kaum"],["أَن","seperti"],["صَدُّوكُمْ","mereka menghalang kamu"],["عَنِ","daripada"],["ٱلْمَسْجِدِ","Al-Masjid"],["ٱلْحَرَامِ","Al-Haraam"],["أَن","bahawa"],["تَعْتَدُوا۟ ۘ","kamu melakukan pelanggaran"],["وَتَعَاوَنُوا۟","Dan tolong menolong antara satu sama lain"],["عَلَى","dalam"],["ٱلْبِرِّ","[the] kebenaran"],["وَٱلتَّقْوَىٰ ۖ","dan ketakwaan"],["وَلَا","tetapi (buat) tidak"],["تَعَاوَنُوا۟","tolong menolong antara satu sama lain"],["عَلَى","dalam"],["ٱلْإِثْمِ","dosa itu"],["وَٱلْعُدْوَٰنِ ۚ","dan pelanggaran"],["وَٱتَّقُوا۟","Dan ketakutan"],["ٱللَّهَ ۖ","Allah"],["إِنَّ","sesungguhnya"],["ٱللَّهَ","Allah"],["شَدِيدُ","(adalah) teruk"],["ٱلْعِقَابِ","(dalam) hukuman"]]],"672":["(Diharamkan bagimu bangkai) yakni memakannya (darah) yang mengalir seperti pada binatang ternak (daging babi, hewan yang disembelih karena selain Allah) misalnya disembelih atas nama lain-Nya (yang tercekik) yang mati karena tercekik (yang dipukul) yang dibunuh dengan jalan memukulnya (yang jatuh) dari atas ke bawah lalu mati (yang ditanduk) yang mati karena tandukan lainnya (yang diterkam oleh binatang buas kecuali yang sempat kamu sembelih) maksudnya yang kamu dapati masih bernyawa dari macam-macam yang disebutkan itu lalu kamu sembelih (dan yang disembelih atas) nama (berhala) jamak dari nishab; artinya patung (dan mengundi nasib) artinya menentukan bagian dan keputusan (dengan anak panah) azlaam jamak dari zalam atau zulam; artinya anak panah yang belum diberi bulu dan ujungnya tidak bermata. Anak panah itu ada tujuh buah disimpan oleh pengurus Kakbah dan padanya terdapat tanda-tanda. Maka tanda-tanda itulah yang mereka ambil sebagai pedoman, jika disuruh mereka lakukan dan jika dilarang mereka hentikan. (Demikian itu adalah kefasikan) artinya menyimpang dari ketaatan. Ayat ini turun pada hari Arafah masa haji wadak, yaitu haji terakhir yang dilakukan oleh Nabi Muhammad saw. (Pada hari ini orang-orang kafir telah putus-asa terhadap agamamu) untuk mengembalikan kamu menjadi murtad setelah mereka melihat kamu telah kuat (maka janganlah kamu takut kepada mereka dan takutlah pada-Ku. Pada hari ini telah Kusempurnakan untukmu agamamu) yakni hukum-hukum halal maupun haram yang tidak diturunkan lagi setelahnya hukum-hukum dan kewajiban-kewajibannya (dan telah Kucukupkan padamu nikmat karunia-Ku) yakni dengan menyempurnakannya dan ada pula yang mengatakan dengan memasuki kota Mekah dalam keadaan aman (dan telah Kuridai) artinya telah Kupilih (Islam itu sebagai agama kalian. Maka siapa terpaksa karena kelaparan) untuk memakan sesuatu yang haram lalu dimakannya (tanpa cenderung) atau sengaja (berbuat dosa) atau maksiat (maka sesungguhnya Allah Maha Pengampun) terhadapnya atas perbuatan memakannya itu (lagi Maha Pengasih) kepadanya dalam memperbolehkannya. Berbeda halnya dengan orang yang cenderung atau sengaja berbuat dosa, misalnya penyamun atau pemberontak, maka tidak halal baginya memakan itu.",[["حُرِّمَتْ","Dijadikan haram"],["عَلَيْكُمُ","pada kamu"],["ٱلْمَيْتَةُ","haiwan yang mati"],["وَٱلدَّمُ","dan darah"],["وَلَحْمُ","dan daging"],["ٱلْخِنزِيرِ","(dari) babi"],["وَمَآ","dan apa"],["أُهِلَّ","telah didedikasikan"],["لِغَيْرِ","kepada selain daripada"],["ٱللَّهِ","Allah"],["بِهِۦ","[di atasnya]"],["وَٱلْمُنْخَنِقَةُ","dan yang dicekik (sampai mati)"],["وَٱلْمَوْقُوذَةُ","dan yang terkena maut"],["وَٱلْمُتَرَدِّيَةُ","dan yang mempunyai kejatuhan maut"],["وَٱلنَّطِيحَةُ","dan yang ditanduk oleh tanduk"],["وَمَآ","dan yang"],["أَكَلَ","makan (ia)"],["ٱلسَّبُعُ","haiwan liar itu"],["إِلَّا","kecuali"],["مَا","apa"],["ذَكَّيْتُمْ","kamu sembelih"],["وَمَا","dan apa"],["ذُبِحَ","dikorbankan"],["عَلَى","pada"],["ٱلنُّصُبِ","mezbah-mezbah batu"],["وَأَن","dan bahawa"],["تَسْتَقْسِمُوا۟","kamu mencari perpecahan"],["بِٱلْأَزْلَـٰمِ ۚ","dengan meramal anak panah"],["ذَٰلِكُمْ","bahawa"],["فِسْقٌ ۗ","(adalah) kemaksiatan yang besar"],["ٱلْيَوْمَ","hari ni"],["يَئِسَ","(telah) putus asa"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["مِن","daripada"],["دِينِكُمْ","agama kamu"],["فَلَا","jadi (jangan)"],["تَخْشَوْهُمْ","takutkan mereka"],["وَٱخْشَوْنِ ۚ","tetapi takutlah kepada-Ku"],["ٱلْيَوْمَ","hari ni"],["أَكْمَلْتُ","Aku telah menyempurnakan"],["لَكُمْ","bagi kamu"],["دِينَكُمْ","agama kamu"],["وَأَتْمَمْتُ","dan aku telah selesaikan"],["عَلَيْكُمْ","ke atas kamu"],["نِعْمَتِى","Nikmat Aku"],["وَرَضِيتُ","dan aku telah meluluskan"],["لَكُمُ","bagi kamu"],["ٱلْإِسْلَـٰمَ","[the] Islam"],["دِينًۭا ۚ","(sebagai) agama"],["فَمَنِ","Tetapi siapa pun"],["ٱضْطُرَّ","(adalah) dipaksa"],["فِى","oleh"],["مَخْمَصَةٍ","kelaparan"],["غَيْرَ","(dan) tidak"],["مُتَجَانِفٍۢ","condong"],["لِّإِثْمٍۢ ۙ","untuk berbuat dosa"],["فَإِنَّ","maka sesungguhnya"],["ٱللَّهَ","Allah"],["غَفُورٌۭ","Maha Pengampun"],["رَّحِيمٌۭ","Maha Mengasihani"]]],"673":["(Mereka menanyakan kepadamu) hai Muhammad (Apakah yang dihalalkan bagi mereka) di antara makanan. (Katakanlah, \"Dihalalkan bagimu yang baik-baik) yang enak-enak atau yang halal (dan) hasil buruan (dari binatang-binatang buas yang telah kamu ajar) seperti anjing, serigala dan burung (dengan melatihnya berburu) hal dari kallabtal kalba pakai tasydid pada lam; artinya biasa kamu lepas berburu (kamu ajar mereka itu) hal dari dhamir mukallibiina; artinya kamu latih mereka itu (menurut apa yang diajarkan Allah kepadamu) tentang cara berburu (maka makanlah apa-apa yang ditangkapnya untukmu) mereka membunuh buruan tanpa memakannya. Berbeda halnya dengan yang tidak terlatih, maka tangkapannya itu tidak halal. Sebagai ciri-cirinya bila dilepas ia berangkat dan bila dicegah ia berhenti serta ditahannya buruan itu dan tidak dimakannya. Sekurang-kurangnya untuk mengetahui hal itu dibutuhkan pengamatan sebanyak tiga kali. Jika buruan itu dimakannya, berarti tidak ditangkapnya untuk tuannya, maka tidak halal dimakan sebagaimana tercantum dalam kedua hadis sahih Bukhari dan Muslim. Dalam hadis itu juga disebutkan bahwa hasil panahan jika dilepas dengan menyebut nama Allah, maka sama dengan hasil buruan dari binatang pemburu yang telah dilatih. (Dan sebutlah nama Allah atasnya) ketika melepasnya (serta bertakwalah kepada Allah; sesungguhnya Allah amat cepat perhitungan-Nya.\")",[["يَسْـَٔلُونَكَ","Mereka bertanya kepada kamu"],["مَاذَآ","apa"],["أُحِلَّ","(adalah) dihalalkan"],["لَهُمْ ۖ","bagi mereka"],["قُلْ","Katakanlah"],["أُحِلَّ","Dihalalkan"],["لَكُمُ","bagi kamu"],["ٱلطَّيِّبَـٰتُ ۙ","perkara yang baik"],["وَمَا","dan apa"],["عَلَّمْتُم","kamu telah mengajar"],["مِّنَ","daripada"],["ٱلْجَوَارِحِ","haiwan pemburuan (kamu)."],["مُكَلِّبِينَ","orang yang melatih haiwan untuk memburu"],["تُعَلِّمُونَهُنَّ","kamu mengajar mereka"],["مِمَّا","tentang apa"],["عَلَّمَكُمُ","telah mengajar kamu"],["ٱللَّهُ ۖ","Allah"],["فَكُلُوا۟","Jadi makan"],["مِمَّآ","tentang apa"],["أَمْسَكْنَ","mereka tangkap"],["عَلَيْكُمْ","bagi kamu"],["وَٱذْكُرُوا۟","tetapi menyebut"],["ٱسْمَ","(nama)"],["ٱللَّهِ","(milik) Allah"],["عَلَيْهِ ۖ","di atasnya"],["وَٱتَّقُوا۟","dan ketakutan"],["ٱللَّهَ ۚ","Allah"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["سَرِيعُ","adalah pantas"],["ٱلْحِسَابِ","(dalam mengambil) akaun"]]],"674":["(Pada hari ini dihalalkan bagimu yang baik-baik) artinya yang enak-enak (Dan makanan-makanan orang-orang yang diberi kitab) maksudnya sembelihan orang-orang Yahudi dan Nasrani (halal bagi kamu dan makananmu) yang kamu sajikan kepada mereka (halal pula bagi mereka. Dan wanita-wanita yang merdeka di antara wanita-wanita mukmin serta wanita-wanita merdeka dari kalangan orang-orang yang diberi kitab sebelum kamu) halal pula kamu kawini (apabila kamu telah membayar maskawin mereka) atau mahar (dengan maksud mengawini mereka) sehingga terpelihara kehormatan (bukan dengan maksud berzina) dengan mereka secara terang-terangan (dan bukan pula untuk mengambil mereka sebagai gundik) atau melakukan perzinaan dengan mereka secara sembunyi-sembunyi. (Dan siapa yang kafir terhadap iman) artinya murtad (maka sungguh telah hapuslah amalnya) amal saleh sebelum itu hingga tidak dianggap diberi pahala (dan ia di akhirat termasuk orang-orang yang merugi) yakni jika ia meninggal dalam keadaan demikian itu.",[["ٱلْيَوْمَ","hari ni"],["أُحِلَّ","dihalalkan"],["لَكُمُ","bagi kamu"],["ٱلطَّيِّبَـٰتُ ۖ","perkara yang baik"],["وَطَعَامُ","dan (yang) makanan"],["ٱلَّذِينَ","orang yang"],["أُوتُوا۟","telah diberikan"],["ٱلْكِتَـٰبَ","Kitab"],["حِلٌّۭ","(adalah) halal"],["لَّكُمْ","bagi kamu"],["وَطَعَامُكُمْ","dan makanan kamu"],["حِلٌّۭ","(adalah) halal"],["لَّهُمْ ۖ","bagi mereka"],["وَٱلْمُحْصَنَـٰتُ","Dan wanita-wanita yang suci"],["مِنَ","daripada"],["ٱلْمُؤْمِنَـٰتِ","orang yang beriman"],["وَٱلْمُحْصَنَـٰتُ","dan perempuan-perempuan yang suci"],["مِنَ","daripada"],["ٱلَّذِينَ","orang yang"],["أُوتُوا۟","telah diberikan"],["ٱلْكِتَـٰبَ","Kitab"],["مِن","daripada"],["قَبْلِكُمْ","sebelum kamu"],["إِذَآ","apabila"],["ءَاتَيْتُمُوهُنَّ","kamu telah memberi mereka"],["أُجُورَهُنَّ","sepatutnya pengantin mereka"],["مُحْصِنِينَ","menjadi suci"],["غَيْرَ","tidak"],["مُسَـٰفِحِينَ","menjadi lucah"],["وَلَا","dan bukan"],["مُتَّخِذِىٓ","mereka (yang) mengambil"],["أَخْدَانٍۢ ۗ","pencinta rahsia"],["وَمَن","Dan sesiapa"],["يَكْفُرْ","menafikan"],["بِٱلْإِيمَـٰنِ","iman"],["فَقَدْ","maka pasti"],["حَبِطَ","(adalah) sia-sia"],["عَمَلُهُۥ","perbuatannya"],["وَهُوَ","dan dia"],["فِى","dalam"],["ٱلْـَٔاخِرَةِ","akhirat"],["مِنَ","(akan) antara"],["ٱلْخَـٰسِرِينَ","yang rugi"]]],"675":["(Hai orang-orang yang beriman, jika kamu berdiri) maksudnya hendak berdiri (mengerjakan salat) dan kamu sedang berhadas (maka basuhlah muka dan tanganmu sampai ke siku) artinya termasuk siku itu sebagaimana diterangkan dalam sunah (dan sapulah kepalamu) ba berarti melengketkan, jadi lengketkanlah sapuanmu itu kepadanya tanpa mengalirkan air. Dan ini merupakan isim jenis, sehingga dianggap cukup bila telah tercapai sapuan walaupun secara minimal, yaitu dengan disapunya sebagian rambut. Pendapat ini juga dianut oleh Imam Syafii (dan kakimu) dibaca manshub karena diathafkan kepada aidiyakum; jadi basuhlah tetapi ada pula yang membaca dengan baris di bawah/kasrah dengan diathafkan kepada yang terdekat (sampai dengan kedua mata kaki) artinya termasuk kedua mata kaki itu, sebagaimana diterangkan dalam hadis. Dua mata kaki ialah dua tulang yang tersembul pada setiap pergelangan kaki yang memisah betis dengan tumit. Dan pemisahan di antara tangan dan kaki yang dibasuh dengan rambut yang disapu menunjukkan diharuskannya/wajib berurutan dalam membersihkan anggota wudu itu. Ini juga merupakan pendapat Syafii. Dari sunah diperoleh keterangan tentang wajibnya berniat seperti halnya ibadah-ibadah lainnya. (Dan jika kamu dalam keadaan junub, maka bersucilah) maksudnya mandilah (dan apabila sakit) yang akan bertambah parah dengan menyentuh air (atau dalam perjalanan) musafir (atau kamu kembali dari tempat buang air) artinya berhadas (atau menyentuh wanita) hal ini telah dibicarakan dulu pada surah An-Nisa (lalu kamu tidak memperoleh air) yakni setelah mencarinya (maka bertayamumlah) dengan mencari (tanah yang baik) tanah yang bersih (sapulah muka dan tanganmu) beserta kedua siku (dengan tanah itu) dengan dua kali pukulan. Ba menunjukkan lengket sementara sunah menjelaskan bahwa yang dimaksud ialah hendaklah sapuan itu meliputi kedua anggota secara keseluruhan (Allah tidaklah hendak menyulitkan kamu) dengan kewajiban-kewajiban berwudu, mandi atau tayamum itu (tetapi Dia hendak menyucikan kamu) dari hadas dan dosa (dan hendak menyempurnakan nikmat-Nya kepadamu) yakni dengan Islam dengan menerangkan syariat-syariat agama (semoga kamu bersyukur) atas nikmat-Nya itu.",[["يَـٰٓأَيُّهَا","Wahai"],["ٱلَّذِينَ","yang"],["ءَامَنُوٓا۟","beriman"],["إِذَا","Apabila"],["قُمْتُمْ","kamu berdiri"],["إِلَى","bagi"],["ٱلصَّلَوٰةِ","solat"],["فَٱغْسِلُوا۟","kemudian basuh"],["وُجُوهَكُمْ","muka kamu"],["وَأَيْدِيَكُمْ","dan tangan kamu"],["إِلَى","sehingga"],["ٱلْمَرَافِقِ","bahagian siku"],["وَٱمْسَحُوا۟","dan lap"],["بِرُءُوسِكُمْ","kepala kamu"],["وَأَرْجُلَكُمْ","dan kaki kamu"],["إِلَى","sehingga"],["ٱلْكَعْبَيْنِ ۚ","buku lali"],["وَإِن","Tetapi jika"],["كُنتُمْ","kamu"],["جُنُبًۭا","(dalam) keadaan najis upacara"],["فَٱطَّهَّرُوا۟ ۚ","maka sucikanlah dirimu"],["وَإِن","Tetapi jika"],["كُنتُم","kamu"],["مَّرْضَىٰٓ","sakit"],["أَوْ","atau"],["عَلَىٰ","pada"],["سَفَرٍ","sebuah perjalanan"],["أَوْ","atau"],["جَآءَ","telah datang"],["أَحَدٌۭ","sesiapa sahaja"],["مِّنكُم","daripada kamu"],["مِّنَ","daripada"],["ٱلْغَآئِطِ","tandas"],["أَوْ","atau"],["لَـٰمَسْتُمُ","telah (mempunyai) hubungan"],["ٱلنِّسَآءَ","(dengan) wanita"],["فَلَمْ","dan bukan"],["تَجِدُوا۟","kamu dapati"],["مَآءًۭ","air"],["فَتَيَمَّمُوا۟","kemudian lakukan tayyammum"],["صَعِيدًۭا","(dengan) bumi"],["طَيِّبًۭا","bersih"],["فَٱمْسَحُوا۟","kemudian lap"],["بِوُجُوهِكُمْ","muka kamu"],["وَأَيْدِيكُم","dan tangan kamu"],["مِّنْهُ ۚ","dengannya"],["مَا","tidak"],["يُرِيدُ","berniat"],["ٱللَّهُ","Allah"],["لِيَجْعَلَ","untuk membuat"],["عَلَيْكُم","bagi kamu"],["مِّنْ","sebarang"],["حَرَجٍۢ","kesukaran"],["وَلَـٰكِن","tetapi"],["يُرِيدُ","Dia berniat"],["لِيُطَهِّرَكُمْ","untuk menyucikan kamu"],["وَلِيُتِمَّ","dan untuk melengkapkan"],["نِعْمَتَهُۥ","NikmatNya"],["عَلَيْكُمْ","ke atas kamu"],["لَعَلَّكُمْ","supaya kamu"],["تَشْكُرُونَ","(bersyukur)."]]],"676":["(Dan ingatlah olehmu karunia Allah kepadamu) maksudnya agama Islam (dan perjanjian-Nya yang telah diikat erat-Nya denganmu) artinya yang telah diperbuat-Nya denganmu (ketika kamu mengatakan) kepada Nabi saw. sewaktu baiat kepadanya (Kami dengar dan kami taati) mengenai apa juga yang engkau suruh atau pun larang, baik yang kami sukai maupun yang kami benci (dan bertakwalah kamu kepada Allah) jangan sampai melanggar perjanjian itu (Sesungguhnya Allah Maha Mengetahui isi hati) yakni apa yang terdapat di dalamnya apa lagi yang terdapat di luarnya.",[["وَٱذْكُرُوا۟","Dan ingat"],["نِعْمَةَ","(yang) nikmat"],["ٱللَّهِ","(milik) Allah"],["عَلَيْكُمْ","ke atas kamu"],["وَمِيثَـٰقَهُ","dan perjanjian-Nya"],["ٱلَّذِى","yang"],["وَاثَقَكُم","Dia mengikat kamu"],["بِهِۦٓ","dengan [ia]"],["إِذْ","apabila"],["قُلْتُمْ","kamu kata"],["سَمِعْنَا","Kami dengar"],["وَأَطَعْنَا ۖ","dan kami patuh"],["وَٱتَّقُوا۟","dan ketakutan"],["ٱللَّهَ ۚ","Allah"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["عَلِيمٌۢ","Maha Mengetahui"],["بِذَاتِ","tentang apa"],["ٱلصُّدُورِ","(ada dalam) buah dada"]]],"677":["(Hai orang-orang yang beriman, hendaklah kamu selalu berdiri karena Allah) menegakkan kebenaran-kebenaran-Nya (menjadi saksi dengan adil) (dan janganlah kamu terdorong oleh kebencian kepada sesuatu kaum) yakni kepada orang-orang kafir (untuk berlaku tidak adil) hingga kamu menganiaya mereka karena permusuhan mereka itu. (Berlaku adillah kamu) baik terhadap lawan maupun terhadap kawan (karena hal itu) artinya keadilan itu (lebih dekat kepada ketakwaan. Dan bertakwalah kepada Allah, sesungguhnya Allah Maha Mengetahui apa yang kamu kerjakan) sehingga kamu akan menerima pembalasan daripadanya.",[["يَـٰٓأَيُّهَا","Wahai"],["ٱلَّذِينَ","yang"],["ءَامَنُوا۟","beriman"],["كُونُوا۟","Jadilah"],["قَوَّٰمِينَ","tabah"],["لِلَّهِ","kerana Allah"],["شُهَدَآءَ","(sebagai) saksi"],["بِٱلْقِسْطِ ۖ","dalam keadilan"],["وَلَا","dan jangan biarkan"],["يَجْرِمَنَّكُمْ","menghalang kamu"],["شَنَـَٔانُ","kebencian"],["قَوْمٍ","(dari) suatu kaum"],["عَلَىٰٓ","[atas]"],["أَلَّا","itu tidak"],["تَعْدِلُوا۟ ۚ","kamu melakukan keadilan"],["ٱعْدِلُوا۟","Berlaku adil"],["هُوَ","ia"],["أَقْرَبُ","(adalah) lebih dekat"],["لِلتَّقْوَىٰ ۖ","kepada [ketakwaan]."],["وَٱتَّقُوا۟","Dan ketakutan"],["ٱللَّهَ ۚ","Allah"],["إِنَّ","sesungguhnya"],["ٱللَّهَ","Allah"],["خَبِيرٌۢ","(adalah) Maha Mengetahui"],["بِمَا","tentang apa"],["تَعْمَلُونَ","kamu lakukan"]]],"678":["(Allah telah menjanjikan kepada orang-orang yang beriman dan yang beramal saleh) suatu janji yang baik (bahwa untuk mereka keampunan dan pahala yang besar) yakni surga.",[["وَعَدَ","Telah berjanji"],["ٱللَّهُ","Allah"],["ٱلَّذِينَ","orang yang"],["ءَامَنُوا۟","beriman"],["وَعَمِلُوا۟","dan melakukan"],["ٱلصَّـٰلِحَـٰتِ ۙ","perbuatan yang soleh"],["لَهُم","bagi mereka"],["مَّغْفِرَةٌۭ","(ialah) pengampunan"],["وَأَجْرٌ","dan ganjaran"],["عَظِيمٌۭ","yang besar"]]],"679":["(Sebaliknya orang-orang yang kafir dan mendustakan ayat-ayat Kami mereka itu adalah penduduk neraka.)",[["وَٱلَّذِينَ","Dan orang yang"],["كَفَرُوا۟","kufur"],["وَكَذَّبُوا۟","dan menafikan"],["بِـَٔايَـٰتِنَآ","Tanda-Tanda Kami"],["أُو۟لَـٰٓئِكَ","mereka"],["أَصْحَـٰبُ","(adalah) para sahabat"],["ٱلْجَحِيمِ","(dari) api Neraka"]]],"680":["(Hai orang-orang yang beriman, ingatlah nikmat Allah kepadamu ketika suatu kaum bermaksud) yakni orang-orang Quraisy (hendak memanjangkan tangan mereka kepadamu) buat mencelakakanmu (maka ditahan-Nya tangan mereka daripadamu) dan dilindungi-Nya kamu dari maksud jahat mereka itu (dan bertakwalah kamu kepada Allah dan hendaklah kepada Allah orang-orang mukmin itu bertawakal.)",[["يَـٰٓأَيُّهَا","Wahai"],["ٱلَّذِينَ","yang"],["ءَامَنُوا۟","beriman"],["ٱذْكُرُوا۟","Ingat"],["نِعْمَتَ","(yang) nikmat"],["ٱللَّهِ","(milik) Allah"],["عَلَيْكُمْ","ke atas kamu"],["إِذْ","apabila"],["هَمَّ","ditentukan"],["قَوْمٌ","suatu kaum"],["أَن","bahawa"],["يَبْسُطُوٓا۟","mereka menghulurkan"],["إِلَيْكُمْ","terhadap kamu"],["أَيْدِيَهُمْ","tangan mereka"],["فَكَفَّ","tetapi Dia menghalang"],["أَيْدِيَهُمْ","tangan mereka"],["عَنكُمْ ۖ","daripada kamu"],["وَٱتَّقُوا۟","Dan ketakutan"],["ٱللَّهَ ۚ","Allah"],["وَعَلَى","Dan selepas"],["ٱللَّهِ","Allah"],["فَلْيَتَوَكَّلِ","jadi letak amanah"],["ٱلْمُؤْمِنُونَ","orang yang beriman"]]],"681":["(Dan sesungguhnya Allah telah mengambil perjanjian dari Bani Israel) mengenai apa yang akan disebutkan di belakang nanti (dan telah Kami angkat) terdapat peralihan dari dhamir gaib kepada orang pertama (di antara mereka 12 orang pemimpin) dari setiap suku seorang pemimpin yang akan menjamin dipenuhinya perjanjian itu oleh semua warga, dan kepada mereka (Allah berfirman, \"Sesungguhnya Aku beserta kamu) siap dengan pertolongan dan bantuan. (Demi jika) lam menunjukkan sumpah (kamu mendirikan salat, menunaikan zakat, beriman kepada rasul-rasul-Ku dan memberikan bantuan kepada mereka serta kamu berikan kepada Allah suatu pinjaman yang baik) dengan mengeluarkan nafkah di jalan-Nya (maka akan Kututupi kesalahan-kesalahan kamu dan akan Kumasukkan kamu ke dalam surga yang di bawahnya mengalir sungai-sungai. Maka siapa yang kafir sesudah itu) maksudnya sesudah perjanjian (di antara kamu, sesungguhnya ia telah sesat dari jalan yang lurus.\") dari jalan yang benar. Sawaa` pada asalnya ialah yang pertengahan. Maka mereka langgar perjanjian itu hingga Allah pun berfirman:",[["۞ وَلَقَدْ","Dan sungguh"],["أَخَذَ","mengambil"],["ٱللَّهُ","Allah"],["مِيثَـٰقَ","sebuah Perjanjian"],["بَنِىٓ","(daripada) Kanak-kanak"],["إِسْرَٰٓءِيلَ","(dari) Israel"],["وَبَعَثْنَا","dan Kami tetapkan"],["مِنْهُمُ","antara mereka"],["ٱثْنَىْ","dua"],["عَشَرَ","(dan) sepuluh"],["نَقِيبًۭا ۖ","pemimpin"],["وَقَالَ","Dan berkata"],["ٱللَّهُ","Allah"],["إِنِّى","Sesungguhnya aku (adalah)"],["مَعَكُمْ ۖ","bersama kamu"],["لَئِنْ","jika"],["أَقَمْتُمُ","kamu menubuhkan"],["ٱلصَّلَوٰةَ","solat"],["وَءَاتَيْتُمُ","dan memberi"],["ٱلزَّكَوٰةَ","zakat tersebut"],["وَءَامَنتُم","dan kamu beriman"],["بِرُسُلِى","dalam Rasul-rasul-Ku"],["وَعَزَّرْتُمُوهُمْ","dan kamu membantu mereka"],["وَأَقْرَضْتُمُ","dan kamu pinjaman"],["ٱللَّهَ","(kepada) Allah"],["قَرْضًا","pinjaman"],["حَسَنًۭا","dengan baik"],["لَّأُكَفِّرَنَّ","nescaya aku akan hapuskan"],["عَنكُمْ","daripada kamu"],["سَيِّـَٔاتِكُمْ","perbuatan jahat kamu"],["وَلَأُدْخِلَنَّكُمْ","dan aku pasti akan mengakui kamu"],["جَنَّـٰتٍۢ","(ke) taman-taman"],["تَجْرِى","aliran"],["مِن","daripada"],["تَحْتِهَا","di bawah mereka"],["ٱلْأَنْهَـٰرُ ۚ","sungai-sungai"],["فَمَن","Tetapi siapa pun"],["كَفَرَ","kufur"],["بَعْدَ","selepas"],["ذَٰلِكَ","bahawa"],["مِنكُمْ","antara kamu"],["فَقَدْ","maka sudah tentu"],["ضَلَّ","dia sesat"],["سَوَآءَ","(dari) jalan"],["ٱلسَّبِيلِ","yang betul"]]],"682":["(Maka disebabkan mereka melanggar) maa merupakan tambahan (janji itu, Kami kutuk mereka) artinya Kami jauhkan dari rahmat Kami (dan Kami jadikan hati mereka keras) tak hendak lunak untuk menerima keimanan. (Mereka ubah perkataan-perkataan)yang terdapat dalam Taurat berupa sifat-sifat dan ciri-ciri Muhammad (dari tempat-tempatnya) semula yang ditaruh oleh Allah (dan mereka lupakan) tinggalkan (sebagian dari peringatan-peringatan yang telah disampaikan kepada mereka) dalam Taurat mengenai ketaatan kepada Muhammad. (Dan selalulah kamu) perkataan ditujukan kepada Nabi saw. (melihat) secara jelas (pengkhianatan dari mereka) dengan mengingkari janji dan lain-lain (kecuali sedikit di antara mereka) yang masuk Islam. (Maka maafkanlah mereka itu dan biarkanlah, sesungguhnya Allah menyukai orang-orang yang berbuat baik) ini dimansukh oleh ayat perang.",[["فَبِمَا","Jadi untuk"],["نَقْضِهِم","pecah mereka"],["مِّيثَـٰقَهُمْ","(dari) perjanjian mereka"],["لَعَنَّـٰهُمْ","Kami mengutuk mereka"],["وَجَعَلْنَا","dan Kami jadikan"],["قُلُوبَهُمْ","hati mereka"],["قَـٰسِيَةًۭ ۖ","keras"],["يُحَرِّفُونَ","Mereka memutarbelitkan"],["ٱلْكَلِمَ","kata-kata"],["عَن","daripada"],["مَّوَاضِعِهِۦ ۙ","tempat mereka"],["وَنَسُوا۟","dan terlupa"],["حَظًّۭا","bahagian"],["مِّمَّا","tentang apa"],["ذُكِّرُوا۟","mereka diingatkan"],["بِهِۦ ۚ","daripada [itu]"],["وَلَا","Dan tidak"],["تَزَالُ","adakah kamu akan berhenti"],["تَطَّلِعُ","untuk menemui"],["عَلَىٰ","daripada"],["خَآئِنَةٍۢ","khianat"],["مِّنْهُمْ","daripada mereka"],["إِلَّا","kecuali"],["قَلِيلًۭا","beberapa"],["مِّنْهُمْ ۖ","daripada mereka"],["فَٱعْفُ","Tetapi maafkan"],["عَنْهُمْ","mereka"],["وَٱصْفَحْ ۚ","dan terlepas pandang"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["يُحِبُّ","suka"],["ٱلْمُحْسِنِينَ","orang yang berbuat baik"]]],"683":["(Dan di antara orang-orang yang mengatakan, \"Sesungguhnya kami ini orang-orang Nasrani,\") berkaitan dengan firman-Nya (ada yang telah Kami ambil pula janji mereka) sebagaimana halnya orang-orang Yahudi dari kalangan Bani Israel (maka mereka lupakan sebagian dari peringatan yang telah disampaikan kepada mereka) yakni dalam Injil berupa keimanan dan lain-lain hingga mereka ingkari perjanjian itu (maka Kami bangkitkan di antara mereka permusuhan dan kebencian sampai hari kiamat) dengan pertikaian dan perbedaan keinginan mereka, hingga setiap golongan mengafirkan yang lain (dan Allah akan memberitakan kepada mereka kelak) yakni di akhirat (apa-apa yang mereka perbuat) lalu mendapat pembalasan daripada-Nya.",[["وَمِنَ","Dan daripada"],["ٱلَّذِينَ","orang yang"],["قَالُوٓا۟","berkata"],["إِنَّا","Sesungguhnya kita"],["نَصَـٰرَىٰٓ","(adalah) orang Kristian"],["أَخَذْنَا","Kami ambil"],["مِيثَـٰقَهُمْ","perjanjian mereka"],["فَنَسُوا۟","tetapi mereka lupa"],["حَظًّۭا","bahagian"],["مِّمَّا","tentang apa"],["ذُكِّرُوا۟","mereka diingatkan"],["بِهِۦ","daripada [itu]"],["فَأَغْرَيْنَا","Maka Kami bangkitkan"],["بَيْنَهُمُ","antara mereka"],["ٱلْعَدَاوَةَ","[the] permusuhan"],["وَٱلْبَغْضَآءَ","dan kebencian"],["إِلَىٰ","sehingga"],["يَوْمِ","(the) Hari"],["ٱلْقِيَـٰمَةِ ۚ","Kiamat"],["وَسَوْفَ","Dan tidak lama lagi"],["يُنَبِّئُهُمُ","akan memberitahu mereka"],["ٱللَّهُ","Allah"],["بِمَا","tentang apa"],["كَانُوا۟","mereka dahulu"],["يَصْنَعُونَ","lakukan"]]],"684":["(Hai Ahli kitab! Sesungguhnya telah datang kepada kamu utusan kami) Muhammad (mengungkapkan kepadamu banyak hal dari apa yang kamu sembunyikan dari Alkitab) yakni kitab Taurat dan Injil seperti ayat tentang rajam dan sifat-sifat Nabi saw. (dan banyak pula yang dibiarkannya) di antara demikian sehingga tidak diungkapkannya jika tidak ada kepentingannya selain dari membukakan rahasia kamu belaka. (Sesungguhnya telah datang kepadamu cahaya dari Allah) itulah dia Nabi saw. (dan kitab) yakni Alquran (yang jelas) nyata.",[["يَـٰٓأَهْلَ","Wahai Rakyat"],["ٱلْكِتَـٰبِ","Kitab"],["قَدْ","pastinya"],["جَآءَكُمْ","telah datang kepada kamu"],["رَسُولُنَا","Rasul kami"],["يُبَيِّنُ","membuat jelas"],["لَكُمْ","kepada kamu"],["كَثِيرًۭا","banyak"],["مِّمَّا","tentang apa"],["كُنتُمْ","kamu pernah"],["تُخْفُونَ","menyembunyikan"],["مِنَ","daripada"],["ٱلْكِتَـٰبِ","Kitab Suci"],["وَيَعْفُوا۟","dan menghadap"],["عَن","daripada"],["كَثِيرٍۢ ۚ","banyak"],["قَدْ","pastinya"],["جَآءَكُم","telah datang kepada kamu"],["مِّنَ","daripada"],["ٱللَّهِ","Allah"],["نُورٌۭ","sebuah cahaya"],["وَكِتَـٰبٌۭ","dan sebuah Buku"],["مُّبِينٌۭ","yang nyata"]]],"685":["(Dengan kitab itu Allah menunjuki orang-orang yang mengikuti keridaan-Nya) maksudnya dengan Alquran dan dengan jalan beriman (ke jalan-jalan keselamatan) jalan yang menyelamatkan mereka (dan mengeluarkan mereka dari kegelapan) yakni kekafiran (kepada cahaya) yakni keimanan (dengan izin-Nya) dengan iradat-Nya (serta membimbing mereka ke jalan yang lurus) yakni agama Islam.",[["يَهْدِى","Pemandu"],["بِهِ","dengannya"],["ٱللَّهُ","Allah"],["مَنِ","(mereka) yang"],["ٱتَّبَعَ","mencari"],["رِضْوَٰنَهُۥ","Keredhaannya"],["سُبُلَ","(kepada) cara"],["ٱلسَّلَـٰمِ","(dari) kedamaian"],["وَيُخْرِجُهُم","dan membawa mereka keluar"],["مِّنَ","daripada"],["ٱلظُّلُمَـٰتِ","kegelapan itu"],["إِلَى","kepada"],["ٱلنُّورِ","cahaya itu"],["بِإِذْنِهِۦ","dengan izinNya"],["وَيَهْدِيهِمْ","dan membimbing mereka"],["إِلَىٰ","kepada"],["صِرَٰطٍۢ","jalan"],["مُّسْتَقِيمٍۢ","(yang) lurus"]]],"686":["(Sungguh, telah kafirlah orang-orang yang mengatakan, \"Sesungguhnya Allah itu ialah Almasih putra Maryam.\") yang mereka memandangnya sebagai Tuhan. Mereka ini ialah kaum Yakobin suatu sekte dari agama Nasrani (Katakanlah, \"Siapakah yang dapat menolak) menghalangi (akan) siksa (Allah walau sedikit pun, jika Dia hendak membinasakan Almasih putra Maryam itu beserta ibunya dan orang-orang yang ada di bumi keseluruhannya?) Maksudnya tak seorang pun yang mampu menolak kehendak-Nya. Dan sekiranya Almasih itu benar-benar Tuhan tentulah ia akan mampu melakukannya. (Dan milik Allahlah kerajaan langit dan bumi dan apa yang terdapat di antara keduanya. Diciptakan-Nya apa yang disukai-Nya, dan Allah atas segala sesuatu) yang dikehendaki-Nya (Maha Kuasa\").",[["لَّقَدْ","Sungguh"],["كَفَرَ","tidak beriman"],["ٱلَّذِينَ","orang yang"],["قَالُوٓا۟","berkata"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["هُوَ","Dia"],["ٱلْمَسِيحُ","(ialah) Mesias"],["ٱبْنُ","nak"],["مَرْيَمَ ۚ","(dari) Maryam"],["قُلْ","Katakanlah"],["فَمَن","Kemudian siapa"],["يَمْلِكُ","mempunyai kuasa"],["مِنَ","terhadap"],["ٱللَّهِ","Allah"],["شَيْـًٔا","(dalam) apa-apa"],["إِنْ","jika"],["أَرَادَ","Dia berniat"],["أَن","kepada"],["يُهْلِكَ","memusnahkan"],["ٱلْمَسِيحَ","Mesias"],["ٱبْنَ","nak"],["مَرْيَمَ","(dari) Maryam"],["وَأُمَّهُۥ","dan ibunya"],["وَمَن","dan sesiapa"],["فِى","(berada) dalam"],["ٱلْأَرْضِ","bumi"],["جَمِيعًۭا ۗ","semua"],["وَلِلَّهِ","Dan untuk Allah"],["مُلْكُ","(ialah) kekuasaan"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ","dan bumi"],["وَمَا","dan apa"],["بَيْنَهُمَا ۚ","(adalah) antara keduanya"],["يَخْلُقُ","Dia mencipta"],["مَا","apa"],["يَشَآءُ ۚ","Dia kehendaki"],["وَٱللَّهُ","dan Allah"],["عَلَىٰ","(berada) di atas"],["كُلِّ","setiap"],["شَىْءٍۢ","perkara"],["قَدِيرٌۭ","Maha Berkuasa"]]],"687":["(Kata orang-orang Yahudi dan Nasrani) artinya kata masing-masing golongan itu (\"Kami ini anak-anak Allah) maksudnya seperti anak-anak-Nya dalam keakraban dan kedudukan, sebaliknya Dia tak ubahnya dengan bapak kami dalam kecintaan dan kasih sayang (dan kekasih-kekasih-Nya.\" Katakanlah) kepada mereka hai Muhammad (\"Kalau begitu kenapa Allah menyiksamu karena dosa-dosamu?\") Maksudnya ucapanmu itu bohong, karena biasanya bapak tak mau menyiksa anaknya begitu pula seorang kekasih terhadap orang yang disayanginya (bahkan kamu hanyalah manusia biasa termasuk) golongan makhluk (yang diciptakan-Nya) di antara manusia, sama-sama menerima pahala dan memikul dosa bersama mereka (diampuni-Nya siapa yang dikehendaki-Nya) bagi-Nyalah ampunan (dan disiksa-Nya siapa yang dikehendaki-Nya) untuk disiksa tanpa suatu pun yang akan menghalangi-Nya. (Dan milik Allahlah kerajaan langit dan bumi dan segala apa yang terdapat di antara keduanya dan kepada-Nya tempat kembali).",[["وَقَالَتِ","Dan berkata"],["ٱلْيَهُودُ","orang Yahudi"],["وَٱلنَّصَـٰرَىٰ","dan orang Kristian"],["نَحْنُ","Kami (adalah)"],["أَبْنَـٰٓؤُا۟","(anak-anak)."],["ٱللَّهِ","(milik) Allah"],["وَأَحِبَّـٰٓؤُهُۥ ۚ","dan kekasihNya"],["قُلْ","Katakanlah"],["فَلِمَ","Lalu kenapa"],["يُعَذِّبُكُم","(adakah Dia) menghukum kamu"],["بِذُنُوبِكُم ۖ","untuk dosa kamu"],["بَلْ","Bahkan"],["أَنتُم","kamu (adalah)"],["بَشَرٌۭ","manusia"],["مِّمَّنْ","dari kalangan (mereka)"],["خَلَقَ ۚ","Dia cipta"],["يَغْفِرُ","Dia memaafkan"],["لِمَن","[untuk] siapa"],["يَشَآءُ","Dia kehendaki"],["وَيُعَذِّبُ","dan menghukum"],["مَن","yang"],["يَشَآءُ ۚ","Dia kehendaki"],["وَلِلَّهِ","Dan untuk Allah"],["مُلْكُ","(ialah) kekuasaan"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ","dan bumi"],["وَمَا","dan apa sahaja"],["بَيْنَهُمَا ۖ","(adalah) di antara mereka"],["وَإِلَيْهِ","dan kepada-Nya"],["ٱلْمَصِيرُ","(ialah) pulangan terakhir"]]],"688":["(Hai Ahli Kitab! Sesungguhnya telah datang kepadamu rasul Kami) yakni Muhammad (menjelaskan kepada kamu) syariat-syariat agama (ketika terputusnya pengiriman rasul-rasul) karena antara dia dengan Isa tak seorang pun rasul yang diutus Allah sedangkan jarak masanya ialah 569 tahun (agar) tidak (kamu katakan) jika kamu disiksa nanti (\"Tidak ada datang kepada kami) min sebagai tambahan (pembawa berita gembira dan tidak pula pembawa peringatan karena sesungguhnya telah datang kepadamu pembawa berita gembira maupun pembawa peringatan itu\") sehingga tak ada kemaafan bagimu lagi! (Dan Allah Maha Kuasa atas segala sesuatu) di antaranya menyiksamu jika kamu tidak taat dan patuh kepada-Nya.",[["يَـٰٓأَهْلَ","Wahai Rakyat"],["ٱلْكِتَـٰبِ","Kitab"],["قَدْ","pastinya"],["جَآءَكُمْ","telah datang kepada kamu"],["رَسُولُنَا","Rasul kami"],["يُبَيِّنُ","dia membuat jelas"],["لَكُمْ","kepada kamu"],["عَلَىٰ","[pada]"],["فَتْرَةٍۢ","(selepas) selang waktu (berhenti)"],["مِّنَ","daripada"],["ٱلرُّسُلِ","para Rasul"],["أَن","jangan-jangan"],["تَقُولُوا۟","kamu cakap"],["مَا","Tidak"],["جَآءَنَا","(telah) datang kepada kami"],["مِنۢ","sebarang"],["بَشِيرٍۢ","pembawa berita gembira"],["وَلَا","dan bukan"],["نَذِيرٍۢ ۖ","seorang pemberi amaran"],["فَقَدْ","Tetapi pastinya"],["جَآءَكُم","telah datang kepada kamu"],["بَشِيرٌۭ","pembawa berita gembira"],["وَنَذِيرٌۭ ۗ","dan pemberi amaran"],["وَٱللَّهُ","Dan Allah"],["عَلَىٰ","(berada) di atas"],["كُلِّ","setiap"],["شَىْءٍۢ","perkara"],["قَدِيرٌۭ","Maha Berkuasa"]]],"689":["(Dan) ingatlah (ketika Musa berkata kepada kaumnya, \"Hai kaumku! Ingatlah nikmat Allah kepadamu ketika diangkat-Nya padamu) maksudnya dari golonganmu (para nabi dan dijadikan-Nya kamu sebagai raja-raja) yang mempunyai anak buah dan pelayan (serta diberi-Nya kamu apa yang belum pernah diberikan-Nya kepada seorang pun di antara umat manusia) seperti hidangan dari langit, manna dan salwa, terbelahnya lautan dan lain-lain.",[["وَإِذْ","Dan apabila"],["قَالَ","berkata"],["مُوسَىٰ","Musa"],["لِقَوْمِهِۦ","kepada umatnya"],["يَـٰقَوْمِ","Wahai kaumku"],["ٱذْكُرُوا۟","ingat"],["نِعْمَةَ","(yang) nikmat"],["ٱللَّهِ","(milik) Allah"],["عَلَيْكُمْ","ke atas kamu"],["إِذْ","apabila"],["جَعَلَ","Dia meletakkan"],["فِيكُمْ","antara kamu"],["أَنۢبِيَآءَ","Nabi-nabi"],["وَجَعَلَكُم","dan menjadikan kamu"],["مُّلُوكًۭا","raja-raja"],["وَءَاتَىٰكُم","dan Dia memberi kamu"],["مَّا","apa"],["لَمْ","tidak"],["يُؤْتِ","Dia (telah) memberi"],["أَحَدًۭا","(kepada) sesiapa sahaja"],["مِّنَ","daripada"],["ٱلْعَـٰلَمِينَ","dunia"]]],"690":["(Hai kaumku! Masuklah kamu ke tanah suci) yang disucikan (yang telah ditetapkan Allah bagi kamu) telah dititahkan-Nya untuk memasukinya yaitu tanah Syam (dan janganlah kamu lari ke belakang) berbalik surut karena takut kepada musuh (nanti kamu menjadi orang-orang yang merugi.\") dalam usahamu.",[["يَـٰقَوْمِ","Wahai kaumku"],["ٱدْخُلُوا۟","Masuk"],["ٱلْأَرْضَ","bumi"],["ٱلْمُقَدَّسَةَ","yang Suci"],["ٱلَّتِى","yang"],["كَتَبَ","(telah) ditahbiskan"],["ٱللَّهُ","(oleh) Allah"],["لَكُمْ","bagi kamu"],["وَلَا","dan jangan"],["تَرْتَدُّوا۟","pusing"],["عَلَىٰٓ","pada"],["أَدْبَارِكُمْ","belakang kamu"],["فَتَنقَلِبُوا۟","maka kamu akan berpatah balik"],["خَـٰسِرِينَ","(sebagai) orang yang rugi"]]],"691":["(Jawab mereka, \"Hai Musa! Sesungguhnya di dalamnya ada orang-orang yang aniaya) sisa-sisa bangsa Ad yang bertubuh tinggi dan bertenaga besar (Dan sesungguhnya kami tidak akan memasukinya hingga mereka keluar daripadanya. Jika mereka telah keluar daripadanya barulah kami memasuki.\")nya.",[["قَالُوا۟","Mereka berkata"],["يَـٰمُوسَىٰٓ","Wahai Musa"],["إِنَّ","Sesungguhnya"],["فِيهَا","di dalamnya"],["قَوْمًۭا","(adalah) orang"],["جَبَّارِينَ","(dari) kekuatan zalim"],["وَإِنَّا","dan sesungguhnya, kita"],["لَن","tidak pernah"],["نَّدْخُلَهَا","akan memasukinya"],["حَتَّىٰ","sehingga"],["يَخْرُجُوا۟","mereka pergi"],["مِنْهَا","daripadanya"],["فَإِن","dan jika"],["يَخْرُجُوا۟","mereka pergi"],["مِنْهَا","[dari] itu"],["فَإِنَّا","maka sesungguhnya kami (akan)"],["دَٰخِلُونَ","masukkan (ia)"]]],"692":["(Berkatalah) kepada mereka (dua orang laki-laki di antara orang-orang yang takut) menyalahi perintah-perintah Allah bernama Yusya dan Kalib, yakni dua orang di antara para pemimpin yang dikirim Musa untuk menyelidiki orang-orang aniaya itu (dan Allah telah memberi kedua mereka itu nikmat) berupa tindakan bijaksana hingga mereka tak hendak menyingkapkan keadaan sebenarnya dari orang-orang aniaya itu selain kepada Musa berbeda halnya dengan anggota-anggota lainnya yang menyiarkan berita itu hingga kaum Musa pun menjadi takut karenanya. (\"Serbulah mereka dengan melalui pintu gerbang) maksudnya pintu gerbang kota dan janganlah takut kepada mereka karena mereka itu tinggal tubuh tanpa hati atau keberanian. (Apabila kamu memasukinya niscaya kamu akan beroleh kemenangan) hal itu mereka ucapkan karena yakin akan beroleh pertolongan Allah dan bahwa Allah pasti menepati janji-Nya. (Dan kepada Allahlah hendaknya kamu bertawakal jika kamu betul-betul orang-orang yang beriman.\")",[["قَالَ","Berkata"],["رَجُلَانِ","dua orang lelaki"],["مِنَ","daripada"],["ٱلَّذِينَ","orang yang"],["يَخَافُونَ","ditakuti (Allah)"],["أَنْعَمَ","(telah) disukai"],["ٱللَّهُ","Allah"],["عَلَيْهِمَا","[pada] kedua-duanya"],["ٱدْخُلُوا۟","Masuk"],["عَلَيْهِمُ","ke atas mereka"],["ٱلْبَابَ","(melalui) pintu gerbang"],["فَإِذَا","kemudian apabila"],["دَخَلْتُمُوهُ","kamu telah memasukkannya"],["فَإِنَّكُمْ","maka sesungguhnya kamu (akan)"],["غَـٰلِبُونَ ۚ","menang"],["وَعَلَى","Dan selepas"],["ٱللَّهِ","Allah"],["فَتَوَكَّلُوٓا۟","maka letaklah amanah"],["إِن","jika"],["كُنتُم","kamu"],["مُّؤْمِنِينَ","orang yang beriman"]]],"693":["(Kata mereka, \"Hai Musa! Kami sekali-kali tidak akan memasukinya untuk selama-lamanya selagi mereka masih berada di dalamnya. Maka pergilah kamu bersama Tuhanmu dan perangilah) mereka (biarlah kami di sini duduk menanti saja.\") tak ikut berperang.",[["قَالُوا۟","Mereka berkata"],["يَـٰمُوسَىٰٓ","Wahai Musa"],["إِنَّا","Sesungguhnya kami"],["لَن","tidak pernah"],["نَّدْخُلَهَآ","akan memasukinya"],["أَبَدًۭا","pernah"],["مَّا","bagi"],["دَامُوا۟","selagi mereka ada"],["فِيهَا ۖ","di dalamnya"],["فَٱذْهَبْ","Jadi pergilah"],["أَنتَ","kamu"],["وَرَبُّكَ","dan Tuhanmu"],["فَقَـٰتِلَآ","dan kamu berdua bergaduh"],["إِنَّا","Sesungguhnya kami"],["هَـٰهُنَا","berada [sini]"],["قَـٰعِدُونَ","duduk"]]],"694":["(Kata Musa) ketika itu (\"Wahai Tuhanku! Aku tidak menguasai kecuali diriku dan) kecuali (saudaraku) adapun yang lainnya tidak, oleh sebab itu paksalah mereka supaya tunduk (maka pisahkanlah) atau ceraikan (di antara kami dengan orang-orang yang fasik itu.\")",[["قَالَ","Dia berkata"],["رَبِّ","Wahai Tuhanku"],["إِنِّى","Sesungguhnya aku"],["لَآ","jangan"],["أَمْلِكُ","(mempunyai) kuasa"],["إِلَّا","kecuali"],["نَفْسِى","(atas) diri aku sendiri"],["وَأَخِى ۖ","dan abang aku"],["فَٱفْرُقْ","jadi (buat a) pemisahan"],["بَيْنَنَا","antara kita"],["وَبَيْنَ","dan antara"],["ٱلْقَوْمِ","manusia"],["ٱلْفَـٰسِقِينَ","(yang) durhaka"]]],"695":["(Firman Allah) Taala kepadanya (\"Maka kalau begitu negeri itu) yakni tanah suci tadi (diharamkan atas mereka) memasukinya (selama 40 tahun mereka akan bertualang tak tahu jalan) kebingungan (di negeri itu) menurut Ibnu Abbas luasnya sembilan farsakh persegi. (Maka janganlah kamu bersedih) berduka-cita (terhadap kaum yang fasik itu) menurut riwayat mereka memulai perjalanan di waktu malam dengan penuh kesungguhan ke arah yang dituju tetapi di waktu pagi mereka telah berada kembali di tempat semula. Demikian pula halnya perjalanan di waktu siang hingga akhirnya mereka binasa (mati\") kecuali orang-orang yang di waktu itu usianya belum lagi mencapai 20 tahun. Ada yang mengatakan bahwa jumlah mereka enam ratus ribu orang dan di padang itulah, yakni yang disebut padang Tih, wafat Harun dan Musa. Hal itu menjadi rahmat bagi mereka berdua sebaliknya menjadi azab dan siksa bagi umat mereka. Setelah dekat kematiannya, Musa memohon kepada Allah agar didekatkan kepada tanah suci itu kira-kira dalam jarak sepelemparan batu, maka permohonan itu dikabulkannya sebagaimana tersebut dalam hadis. Setelah masa empat puluh tahun itu Allah mengangkat Yusya menjadi nabi dan memerintahkannya untuk memerangi orang-orang aniaya tadi. Maka berangkatlah ia dengan sisa-sisa Israel dan memerangi musuh yang ketika itu ialah hari Jumat. Menurut berita, matahari terhenti selama sesaat menunggu selesai mereka berperang. Diriwayatkan oleh Ahmad dalam musnadnya sebuah hadis bahwa matahari itu tidak pernah tertahan jalannya untuk kepentingan manusia kecuali bagi Yusya, yaitu di malam-malam perjalanannya menuju Baitulmakdis.",[["قَالَ","(Allah) berfirman"],["فَإِنَّهَا","Maka sesungguhnya ia"],["مُحَرَّمَةٌ","(akan) diharamkan"],["عَلَيْهِمْ ۛ","kepada mereka"],["أَرْبَعِينَ","(untuk) empat puluh"],["سَنَةًۭ ۛ","tahun"],["يَتِيهُونَ","mereka akan merayau"],["فِى","dalam"],["ٱلْأَرْضِ ۚ","bumi"],["فَلَا","Jadi (jangan)"],["تَأْسَ","bersedih"],["عَلَى","atas"],["ٱلْقَوْمِ","manusia"],["ٱلْفَـٰسِقِينَ","yang durhaka"]]],"696":["(Dan bacakanlah) hai Muhammad (kepada mereka) yakni kepada kaummu (kabar) berita (dua orang anak Adam) yaitu Habil dan Qabil (dengan sebenarnya) berhubungan dengan utlu (ketika keduanya mempersembahkan kurban) kepada Allah berupa domba dari Habil dan hasil tanaman dari Qabil. (Maka diterima dari salah seorang mereka) yakni dari Habil dengan alamat turunnya api dari langit yang melahap kurbannya (dan tidak diterima dari yang lain) yakni dari Qabil yang menjadi murka dan memendam kedengkian dalam dirinya menunggu naik hajinya Adam. (Katanya) yakni Qabil kepada Habil (\"Sungguh, akan kubunuh kamu!\") Kenapa kurbanmu diterima sedangkan kurban saya tidak! (Jawabnya, yakni Habil, \"Sesungguhnya Allah hanya menerima kurban dari orang-orang yang bertakwa\").",[["۞ وَٱتْلُ","Dan mengaji"],["عَلَيْهِمْ","kepada mereka"],["نَبَأَ","cerita itu"],["ٱبْنَىْ","(dari) dua orang anak lelaki"],["ءَادَمَ","(dari) Adam"],["بِٱلْحَقِّ","dalam kebenaran"],["إِذْ","apabila"],["قَرَّبَا","kedua-duanya ditawarkan"],["قُرْبَانًۭا","pengorbanan"],["فَتُقُبِّلَ","dan ia diterima"],["مِنْ","daripada"],["أَحَدِهِمَا","salah seorang daripada mereka"],["وَلَمْ","dan bukan"],["يُتَقَبَّلْ","telah diterima"],["مِنَ","daripada"],["ٱلْـَٔاخَرِ","yang lain"],["قَالَ","Berkata (yang terakhir)"],["لَأَقْتُلَنَّكَ ۖ","Pasti aku akan membunuh kamu"],["قَالَ","Berkata (bekas)"],["إِنَّمَا","Hanya"],["يَتَقَبَّلُ","menerima"],["ٱللَّهُ","(ada) Allah"],["مِنَ","daripada"],["ٱلْمُتَّقِينَ","yang takut kepada Tuhan"]]],"697":["(\"Sungguh, jika) lam menunjukkan sumpah (kamu mengulurkan) atau menggerakkan (tanganmu kepadaku untuk membunuhku, tidaklah aku akan mengulurkan tanganku kepadamu untuk membunuhmu. Sesungguhnya aku takut akan Allah, Tuhan seru sekalian alam.\") jika membunuhmu.",[["لَئِنۢ","Jika"],["بَسَطتَ","kamu menghulurkan"],["إِلَىَّ","ke arah aku"],["يَدَكَ","tangan kamu"],["لِتَقْتُلَنِى","untuk membunuh aku"],["مَآ","tidak"],["أَنَا۠","adakah aku"],["بِبَاسِطٍۢ","regangan"],["يَدِىَ","tangan aku"],["إِلَيْكَ","terhadap kamu"],["لِأَقْتُلَكَ ۖ","untuk membunuh kamu"],["إِنِّىٓ","sesungguhnya aku"],["أَخَافُ","bertakwa"],["ٱللَّهَ","Allah"],["رَبَّ","(yang) Tuhan"],["ٱلْعَـٰلَمِينَ","sekalian alam"]]],"698":["(Sesungguhnya aku ingin agar kamu kembali membawa dosaku) maksudnya kembali menghadap kepada Allah dengan membawa dosa membunuhku (dan dosamu sendiri) yakni yang kamu perbuat sebelumnya (hingga kamu akan menjadi penghuni neraka) sedangkan aku tak ingin memikul dosamu jika membunuhnya sehingga aku menjadi penghuni neraka pula. Firman Allah swt.: (\"Dan demikianlah balasan bagi orang-orang yang aniaya.\")",[["إِنِّىٓ","Sesungguhnya aku"],["أُرِيدُ","keinginan"],["أَن","bahawa"],["تَبُوٓأَ","kamu sarat"],["بِإِثْمِى","dengan dosa aku"],["وَإِثْمِكَ","dan dosamu"],["فَتَكُونَ","jadi kamu akan menjadi"],["مِنْ","antara"],["أَصْحَـٰبِ","(para) sahabat"],["ٱلنَّارِ ۚ","(dari) api"],["وَذَٰلِكَ","dan bahawa"],["جَزَٰٓؤُا۟","(ialah) balasan"],["ٱلظَّـٰلِمِينَ","(dari) orang-orang yang zalim"]]],"699":["(Tetapi nafsunya menggodanya untuk membunuh saudaranya lalu dibunuhnyalah, maka jadilah dia termasuk di antara orang-orang yang merugi) disebabkan pembunuhan itu. Mulanya ia tidak tahu apa yang akan diperbuatnya terhadap mayat saudaranya itu karena ia adalah mayat yang pertama dari anak cucu Adam di muka bumi, maka dipikulnyalah di atas punggungnya.",[["فَطَوَّعَتْ","Kemudian digesa"],["لَهُۥ","kepadanya"],["نَفْسُهُۥ","jiwanya"],["قَتْلَ","(untuk) membunuh"],["أَخِيهِ","abangnya"],["فَقَتَلَهُۥ","jadi dia membunuhnya"],["فَأَصْبَحَ","dan menjadi"],["مِنَ","daripada"],["ٱلْخَـٰسِرِينَ","yang rugi"]]],"700":["(Lalu Allah mengirimkan seekor burung gagak menggali bumi) maksudnya mengorek tanah dengan paruh dan kedua kakinya lalu menimbunkannya di atas bangkai saudaranya seakan-akan menguburkannya (untuk memperlihatkan kepadanya bagaimana seharusnya dia menutupi) atau menguburkan (mayat saudaranya. Katanya, \"Wahai celakanya daku! Mengapa aku tidak mampu) buat (bertindak seperti burung gagak ini hingga dapat menguburkan mayat saudaraku. Maka jadilah dia di antara orang-orang yang menyesal.\") karena telah memikulnya tadi. Kemudian digalinya liang lalu dikuburkannya mayat saudaranya Habil itu.",[["فَبَعَثَ","Kemudian (telah) dihantar"],["ٱللَّهُ","(oleh) Allah"],["غُرَابًۭا","seekor burung gagak"],["يَبْحَثُ","ia (ada) menggaru"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["لِيُرِيَهُۥ","untuk menunjukkan kepadanya"],["كَيْفَ","bagaimana"],["يُوَٰرِى","untuk bersembunyi"],["سَوْءَةَ","(the) mayat"],["أَخِيهِ ۚ","(dari) saudaranya"],["قَالَ","Dia berkata"],["يَـٰوَيْلَتَىٰٓ","Celaka aku"],["أَعَجَزْتُ","Adakah aku tidak mampu"],["أَنْ","bahawa"],["أَكُونَ","aku boleh jadi"],["مِثْلَ","suka"],["هَـٰذَا","ini"],["ٱلْغُرَابِ","[the] gagak"],["فَأُوَٰرِىَ","dan bersembunyi"],["سَوْءَةَ","(the) mayat"],["أَخِى ۖ","(dari) saudara aku"],["فَأَصْبَحَ","Kemudian dia menjadi"],["مِنَ","daripada"],["ٱلنَّـٰدِمِينَ","yang menyesal"]]],"701":["(Oleh sebab itu) artinya karena perbuatan Qabil itu tadi (Kami tetapkan bagi Bani Israel bahwa sesungguhnya) innahuu disebut dhamir sya`n (siapa yang membunuh seorang manusia bukan karena manusia lainnya) yang dibunuhnya (atau) bukan karena (kerusakan) yang diperbuatnya (di muka bumi) berupa kekafiran, perzinaan atau perampokan dan sebagainya (maka seolah-olah dia telah membunuh manusia kesemuanya. Sebaliknya siapa yang memelihara kehidupannya) artinya tidak hendak membunuhnya (maka seolah-olah ia telah memelihara kehidupan manusia seluruhnya.) Kata Ibnu Abbas, \"Ini dilihat dari segi melanggar kesuciannya dan dari segi memelihara serta menjaganya.\" (dan sesungguhnya telah datang kepada mereka itu) yakni kepada orang-orang Israel (rasul-rasul Kami membawa keterangan-keterangan yang jelas) maksudnya mukjizat-mukjizat (kemudian banyak di antara mereka sesudah itu melampaui batas dalam berbuat kerusakan di muka bumi) dengan kekafiran, melakukan pembunuhan dan lain-lain.",[["مِنْ","daripada"],["أَجْلِ","masa"],["ذَٰلِكَ","bahawa"],["كَتَبْنَا","Kami tetapkan"],["عَلَىٰ","pada"],["بَنِىٓ","(the) Kanak-kanak"],["إِسْرَٰٓءِيلَ","(dari) Israel"],["أَنَّهُۥ","bahawa dia"],["مَن","yang"],["قَتَلَ","membunuh"],["نَفْسًۢا","sebuah jiwa"],["بِغَيْرِ","selain daripada"],["نَفْسٍ","(untuk) jiwa"],["أَوْ","atau"],["فَسَادٍۢ","(untuk) menyebarkan rasuah"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["فَكَأَنَّمَا","maka (ia) seolah-olah"],["قَتَلَ","dia telah membunuh"],["ٱلنَّاسَ","manusia"],["جَمِيعًۭا","semua"],["وَمَنْ","dan sesiapa"],["أَحْيَاهَا","menyimpannya"],["فَكَأَنَّمَآ","maka (ia) seolah-olah"],["أَحْيَا","dia telah menyelamatkan"],["ٱلنَّاسَ","manusia"],["جَمِيعًۭا ۚ","semua"],["وَلَقَدْ","Dan pastinya"],["جَآءَتْهُمْ","datang kepada mereka"],["رُسُلُنَا","Rasul-rasul Kami"],["بِٱلْبَيِّنَـٰتِ","dengan Tanda-tanda yang jelas"],["ثُمَّ","belum lagi"],["إِنَّ","sesungguhnya"],["كَثِيرًۭا","ramai"],["مِّنْهُم","daripada mereka"],["بَعْدَ","selepas"],["ذَٰلِكَ","bahawa"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["لَمُسْرِفُونَ","(ialah) sesungguhnya orang-orang yang berlebih-lebihan"]]],"702":["(Bahwasanya pembalasan terhadap orang-orang yang memerangi Allah dan rasul-Nya) artinya dengan memerangi kaum muslimin (dan membuat kerusakan di muka bumi) dengan menyamun dan merampok (ialah dengan membunuh atau menyalib mereka atau tangan dan kaki mereka dipotong secara timbal balik) maksudnya tangan kanan dengan kaki kiri mereka (atau dibuang dari kampung halamannya). Atau secara bertingkat, maka hukum bunuh itu ialah bagi yang membunuh saja, hukum salib bagi yang membunuh dan merampas harta, hukum potong bagi yang merampas harta tetapi tanpa membunuh sedangkan hukum buang bagi yang mengacau saja. Hal ini dikemukakan oleh Ibnu Abbas dan dianut oleh Syafii. Menurut yang terkuat di antara dua buah pendapat dilaksanakannya hukum salib itu ialah tiga hari setelah dihukum bunuh. Tetapi ada pula yang mengatakan tidak lama sebelum dibunuh. Termasuk dalam hukum buang hukuman lain yang sama pengaruhnya dalam memberikan pelajaran seperti tahanan penjara dan lain-lain. (Demikian itu) maksudnya pembalasan atau hukuman tersebut (merupakan kehinaan bagi mereka) kenistaan (di dunia sedangkan di akhirat mereka beroleh siksa yang besar) yaitu siksa neraka.",[["إِنَّمَا","Hanya"],["جَزَٰٓؤُا۟","(the) balasan"],["ٱلَّذِينَ","(bagi) mereka yang"],["يُحَارِبُونَ","berperang"],["ٱللَّهَ","(terhadap) Allah"],["وَرَسُولَهُۥ","dan Rasul-Nya"],["وَيَسْعَوْنَ","dan berusaha"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["فَسَادًا","menyebarkan rasuah"],["أَن","(ialah) itu"],["يُقَتَّلُوٓا۟","mereka dibunuh"],["أَوْ","atau"],["يُصَلَّبُوٓا۟","mereka disalibkan"],["أَوْ","atau"],["تُقَطَّعَ","terputus"],["أَيْدِيهِمْ","tangan mereka"],["وَأَرْجُلُهُم","dan kaki mereka"],["مِّنْ","daripada"],["خِلَـٰفٍ","sisi bertentangan"],["أَوْ","atau"],["يُنفَوْا۟","mereka dibuang negeri"],["مِنَ","daripada"],["ٱلْأَرْضِ ۚ","bumi"],["ذَٰلِكَ","Itu"],["لَهُمْ","(adalah) untuk mereka"],["خِزْىٌۭ","aib"],["فِى","dalam"],["ٱلدُّنْيَا ۖ","dunia"],["وَلَهُمْ","dan untuk mereka"],["فِى","dalam"],["ٱلْـَٔاخِرَةِ","akhirat"],["عَذَابٌ","(ialah) azab"],["عَظِيمٌ","yang besar"]]],"703":["(Kecuali orang-orang yang tobat) di antara orang-orang yang menyalakan api dan peperangan perampokan tadi (sebelum kamu dapat menguasai mereka, maka ketahuilah bahwa Allah Maha Pengampun) terhadap mereka atas perbuatan mereka itu (lagi Maha Penyayang) kepada mereka. Dalam ayat ini tidak disebutkan \"janganlah mereka kamu jatuhi hukuman\" untuk menunjukkan bahwa dengan bertobat itu yang gugur hanyalah hak Allah dan tidak hak manusia. Demikian yang dapat ditangkap dengan jelas dan saya lihat tidak seorang pun yang menentangnya, wallahu a`lam. Maka jika seseorang membunuh dan merampas harta, maka ia dihukum bunuh dan dipotong tetapi tidak disalib. Ini merupakan yang terkuat di antara kedua pendapat Syafii. Mengenai bertobat setelah ia dapat ditangkap, maka tak ada pengaruh dan manfaat apa-apa. Ini juga merupakan yang terkuat di antara kedua pendapat Imam Syafii.",[["إِلَّا","Kecuali"],["ٱلَّذِينَ","orang yang"],["تَابُوا۟","bertaubat"],["مِن","daripada"],["قَبْلِ","sebelum"],["أَن","bahawa"],["تَقْدِرُوا۟","kamu kuasai"],["عَلَيْهِمْ ۖ","[atas] mereka"],["فَٱعْلَمُوٓا۟","maka ketahuilah"],["أَنَّ","bahawa"],["ٱللَّهَ","Allah"],["غَفُورٌۭ","Maha Pengampun"],["رَّحِيمٌۭ","Maha Mengasihani"]]],"704":["(Hai orang-orang yang beriman, bertakwalah kamu kepada Allah) artinya takutlah akan siksa-Nya dengan jalan menaati-Nya (dan carilah jalan kepada-Nya) yaitu jalan yang akan mendekatkan dirimu kepada-Nya dengan jalan taat dan ibadah (dan berjihadlah pada jalan-Nya) maksudnya untuk meninggikan agama-Nya (semoga kamu beruntung atau beroleh keberhasilan).",[["يَـٰٓأَيُّهَا","Wahai"],["ٱلَّذِينَ","yang"],["ءَامَنُوا۟","beriman"],["ٱتَّقُوا۟","Takut"],["ٱللَّهَ","Allah"],["وَٱبْتَغُوٓا۟","dan cari"],["إِلَيْهِ","terhadapNya"],["ٱلْوَسِيلَةَ","cara"],["وَجَـٰهِدُوا۟","dan berusaha bersungguh-sungguh"],["فِى","dalam"],["سَبِيلِهِۦ","cara dia"],["لَعَلَّكُمْ","supaya kamu"],["تُفْلِحُونَ","berjaya"]]],"705":["(Sesungguhnya orang-orang kafir, sekiranya) terjadilah (bahwa mereka memiliki seluruh yang terdapat di bumi dan sebanyak itu lagi sebagai tambahannya untuk menebus diri mereka dari siksa hari kiamat tidaklah akan diterima dari mereka dan bagi mereka azab yang pedih).",[["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["لَوْ","jika"],["أَنَّ","bahawa"],["لَهُم","bagi mereka"],["مَّا","(ialah) apa"],["فِى","(berada) dalam"],["ٱلْأَرْضِ","bumi"],["جَمِيعًۭا","semua"],["وَمِثْلَهُۥ","dan seumpamanya"],["مَعَهُۥ","dengannya"],["لِيَفْتَدُوا۟","untuk menebus diri mereka sendiri"],["بِهِۦ","dengannya"],["مِنْ","daripada"],["عَذَابِ","azab"],["يَوْمِ","hari"],["ٱلْقِيَـٰمَةِ","Kiamat"],["مَا","tidak"],["تُقُبِّلَ","akan diterima"],["مِنْهُمْ ۖ","daripada mereka"],["وَلَهُمْ","dan untuk mereka"],["عَذَابٌ","(ialah) azab"],["أَلِيمٌۭ","yang pedih"]]],"706":["(Mereka ingin) mengangankan (hendak keluar dari neraka, tetapi tidak mungkin keluar daripadanya dan bagi mereka siksa yang kekal) untuk selama-lamanya.",[["يُرِيدُونَ","Mereka akan berhajat"],["أَن","bahawa"],["يَخْرُجُوا۟","mereka keluar"],["مِنَ","daripada"],["ٱلنَّارِ","neraka"],["وَمَا","tetapi tidak"],["هُم","mereka"],["بِخَـٰرِجِينَ","akan keluar"],["مِنْهَا ۖ","daripadanya"],["وَلَهُمْ","Dan untuk mereka"],["عَذَابٌۭ","(ialah) azab"],["مُّقِيمٌۭ","berkekalan"]]],"707":["(Laki-laki yang mencuri dan wanita yang mencuri) al yang terdapat pada keduanya menunjukkannya sebagai isim maushul dan berfungsi sebagai mubtada, mengingat al mirip dengan syarat maka khabarnya diawali dengan fa, yaitu (maka potonglah tangan mereka) tangan kanan masing-masing mulai dari pergelangan. Dinyatakan oleh sunah bahwa hukum potong itu dilaksanakan jika yang dicuri itu bernilai seperempat dinar atau lebih; jika perbuatannya itu diulanginya lagi maka yang dipotong kakinya yang kiri dari pergelangan kaki, kemudian tangan kiri lalu kaki kanan dan setelah itu dilakukan hukum takzir (sebagai balasan) manshub sebagai mashdar (atas apa yang mereka kerjakan dan sebagai siksaan) artinya hukuman bagi mereka (dari Allah dan Allah Maha Perkasa) artinya menguasai segala urusan (lagi Maha Bijaksana) terhadap makhluk-Nya.",[["وَٱلسَّارِقُ","Dan (untuk) pencuri lelaki"],["وَٱلسَّارِقَةُ","dan pencuri perempuan"],["فَٱقْطَعُوٓا۟","[kemudian] potong"],["أَيْدِيَهُمَا","tangan mereka"],["جَزَآءًۢ","(sebagai) balasan"],["بِمَا","bagi apa"],["كَسَبَا","mereka perolehi"],["نَكَـٰلًۭا","(sebagai) teladan (hukuman)"],["مِّنَ","daripada"],["ٱللَّهِ ۗ","Allah"],["وَٱللَّهُ","Dan Allah"],["عَزِيزٌ","(adalah) Maha Perkasa"],["حَكِيمٌۭ","Maha Bijaksana"]]],"708":["(Siapa yang tobat setelah keaniayaannya) artinya tidak mencuri lagi (dan memperbaiki diri) atau amalnya (maka sesungguhnya Allah menerima tobatnya. Sesungguhnya Allah itu Maha Pengampun lagi Maha Penyayang) untuk menguraikan ini telah kita kemukakan keterangan yang lalu. Maka dengan tobatnya itu tidaklah gugur hak manusia berupa hukum potong dan pengembalian harta. Kemudian sunah menyatakan bahwa jika yang punya hak memberi maaf sebelum diadukan kepada imam, gugurlah hukum potong itu terhadapnya. Dan inilah yang menjadi pendapat Syafii.",[["فَمَن","Tetapi siapa pun"],["تَابَ","bertaubat"],["مِنۢ","daripada"],["بَعْدِ","selepas"],["ظُلْمِهِۦ","kesalahannya"],["وَأَصْلَحَ","dan pembaharuan"],["فَإِنَّ","maka sesungguhnya"],["ٱللَّهَ","Allah"],["يَتُوبُ","akan berpaling dalam pengampunan"],["عَلَيْهِ ۗ","kepadanya"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["غَفُورٌۭ","Maha Pengampun"],["رَّحِيمٌ","Maha Mengasihani"]]],"709":["(Tidaklah kamu ketahui) pertanyaan ini sebagai pengukuhan (bahwa sesungguhnya Allah memiliki kerajaan langit dan bumi, disiksa-Nya siapa yang dikehendaki-Nya) untuk disiksa (dan diampuni-Nya siapa yang dikehendaki-Nya) untuk diampuni. (Dan Allah Maha Kuasa atas segala sesuatu) di antaranya menurunkan siksa atau memberi ampun.",[["أَلَمْ","Jangan"],["تَعْلَمْ","kamu tahu"],["أَنَّ","bahawa"],["ٱللَّهَ","Allah"],["لَهُۥ","kepada-Nya (milik)"],["مُلْكُ","(kekuasaan)."],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ","dan bumi"],["يُعَذِّبُ","Dia menghukum"],["مَن","yang"],["يَشَآءُ","Dia kehendaki"],["وَيَغْفِرُ","dan Dia mengampuni"],["لِمَن","[kepada] siapa"],["يَشَآءُ ۗ","Dia kehendaki"],["وَٱللَّهُ","Dan Allah"],["عَلَىٰ","(berada) di atas"],["كُلِّ","setiap"],["شَىْءٍۢ","perkara"],["قَدِيرٌۭ","Maha Berkuasa"]]],"710":["(Hai Rasul, janganlah kamu menjadi bersedih hati oleh) disebabkan perbuatan (orang-orang yang berlomba-lomba dalam kekafiran) hingga tanpa menunggu lama mereka akan terjatuh di dalamnya; artinya bila ada kesempatan mereka akan menyatakan kekafiran itu (di antara) min merupakan penjelasan (orang-orang yang mengatakan dengan mulut mereka, \"Kami telah beriman.\") maksudnya dengan lidah mereka nyatakan hal tersebut (padahal hati mereka tidak beriman) mereka ini ialah orang-orang munafik (dan juga di antara orang-orang Yahudi) yakni suatu kaum (yang amat gemar mendengar berita-berita bohong) yang dibuat-buat oleh pendeta-pendeta mereka lalu mereka terima dengan baik (dan amat suka pula mendengar berita-berita) daripadamu (untuk suatu kaum) artinya demi kepentingan kaum (yang lain) dari golongan Yahudi (yang belum pernah datang kepadamu) yakni warga Khaibar. Terdapat di sana sepasang laki-laki dan perempuan yang telah berumah tangga melakukan perzinaan, tetapi mereka berkeberatan untuk menjalankan hukuman rajam kepada kedua pesakitan. Lalu mereka mengirimkan orang-orang warga Quraizhah untuk menanyakan hukuman mereka itu kepada Nabi Muhammad saw. (Mereka mengubah-ubah perkataan) yang tercantum dalam Taurat seperti ayat tentang rajam (dari tempat-tempatnya) yang ditaruh Allah padanya; artinya mereka menggantikannya dengan yang lain. (Kata mereka) yakni kepada orang-orang yang mereka utus tadi (\"Jika yang diberikan kepadamu itu ialah ini) maksudnya hukum yang telah dirubah dan difatwakan oleh Muhammad yaitu hukum pukulan (maka ambillah) terimalah (tetapi jika bukan itu yang diberikan kepadamu) dan fatwa yang diberikannya bertentangan dengannya (maka berhati-hatilah.\") untuk menerimanya. (Siapa yang dikehendaki Allah kesesatannya, maka kamu sekali-kali tidak akan dapat menguasai sesuatu yang datang dari Allah) untuk menolaknya (mereka itu ialah orang-orang yang tidak dikehendaki Allah menyucikan hati mereka) dari kekafiran, dan sekiranya dikehendaki-Nya tentulah hal itu akan tercapai. (Bagi mereka di dunia ini kehinaan) kenistaan dengan terbukanya rahasia dan pembayaran upeti (sedangkan di akhirat siksa yang besar.)",[["۞ يَـٰٓأَيُّهَا","Wahai"],["ٱلرَّسُولُ","Utusan"],["لَا","Janganlah"],["يَحْزُنكَ","menyedihkan kamu"],["ٱلَّذِينَ","orang yang"],["يُسَـٰرِعُونَ","cepatkan"],["فِى","dalam (ke)"],["ٱلْكُفْرِ","[yang] tidak beriman"],["مِنَ","daripada"],["ٱلَّذِينَ","orang yang"],["قَالُوٓا۟","berkata"],["ءَامَنَّا","Kami beriman"],["بِأَفْوَٰهِهِمْ","dengan mulut mereka"],["وَلَمْ","dan bukan"],["تُؤْمِن","beriman"],["قُلُوبُهُمْ ۛ","hati mereka"],["وَمِنَ","dan daripada"],["ٱلَّذِينَ","orang yang"],["هَادُوا۟ ۛ","(adalah) Yahudi"],["سَمَّـٰعُونَ","Mereka (adalah) pendengar"],["لِلْكَذِبِ","kepada kebatilan"],["سَمَّـٰعُونَ","(dan) pendengar"],["لِقَوْمٍ","untuk orang"],["ءَاخَرِينَ","lain"],["لَمْ","(yang mempunyai) tidak"],["يَأْتُوكَ ۖ","datang kepada kamu"],["يُحَرِّفُونَ","Mereka memutarbelitkan"],["ٱلْكَلِمَ","kata-kata"],["مِنۢ","daripada"],["بَعْدِ","selepas"],["مَوَاضِعِهِۦ ۖ","konteks mereka"],["يَقُولُونَ","berkata"],["إِنْ","Jika"],["أُوتِيتُمْ","kamu diberi"],["هَـٰذَا","ini"],["فَخُذُوهُ","[jadi] ambillah"],["وَإِن","tetapi jika"],["لَّمْ","tidak"],["تُؤْتَوْهُ","kamu diberinya"],["فَٱحْذَرُوا۟ ۚ","maka berhati-hatilah"],["وَمَن","Dan (untuk) siapa"],["يُرِدِ","berniat"],["ٱللَّهُ","Allah"],["فِتْنَتَهُۥ","perbicaraannya"],["فَلَن","maka tidak pernah"],["تَمْلِكَ","adakah kamu akan mempunyai kuasa"],["لَهُۥ","baginya"],["مِنَ","terhadap"],["ٱللَّهِ","Allah"],["شَيْـًٔا ۚ","sesuatu"],["أُو۟لَـٰٓئِكَ","Mereka itu"],["ٱلَّذِينَ","(adalah) mereka"],["لَمْ","tidak pernah"],["يُرِدِ","akan berniat"],["ٱللَّهُ","Allah"],["أَن","bahawa"],["يُطَهِّرَ","Dia menyucikan"],["قُلُوبَهُمْ ۚ","hati mereka"],["لَهُمْ","Untuk mereka"],["فِى","dalam"],["ٱلدُّنْيَا","dunia"],["خِزْىٌۭ ۖ","(adalah) aib"],["وَلَهُمْ","dan untuk mereka"],["فِى","dalam"],["ٱلْـَٔاخِرَةِ","akhirat"],["عَذَابٌ","(ialah) azab"],["عَظِيمٌۭ","yang besar"]]],"711":["(Mereka orang-orang yang gemar mendengar berita-berita bohong dan banyak memakan yang haram) dibaca suht atau suhut; artinya barang haram seperti uang suap (maka jika mereka datang kepadamu) untuk meminta sesuatu keputusan (maka putuskanlah di antara mereka atau berpalinglah dari mereka) pilihan di antara alternatif ini dihapus/dinasakh dengan firman-Nya, \"..... maka putuskanlah di antara mereka.\" Oleh sebab itu jika mereka mengadukan hal itu kepada kita wajiblah kita memberikan keputusannya di antara mereka. Dan ini merupakan yang terkuat di antara kedua pendapat Syafii. Dan sekiranya mereka mengadukan perkara itu bersama orang Islam, maka hukum memutuskan itu wajib secara ijmak. (Jika mereka berpaling daripadamu, maka sekali-kali tidak akan memberi mudarat kepadamu sedikit pun juga. Dan jika kamu memutuskan) perkara di antara mereka (maka putuskanlah di antara mereka dengan adil) tidak berat sebelah. (Sesungguhnya Allah menyukai orang-orang yang adil) dalam memberikan keputusan dan akan memberi mereka pahala.",[["سَمَّـٰعُونَ","Pendengar"],["لِلْكَذِبِ","kepada kebatilan"],["أَكَّـٰلُونَ","pemakan"],["لِلسُّحْتِ ۚ","daripada yang dilarang"],["فَإِن","Jadi jika"],["جَآءُوكَ","mereka datang kepada kamu"],["فَٱحْكُم","kemudian menilai"],["بَيْنَهُمْ","antara mereka"],["أَوْ","atau"],["أَعْرِضْ","berpaling"],["عَنْهُمْ ۖ","daripada mereka"],["وَإِن","Dan jika"],["تُعْرِضْ","kamu berpaling"],["عَنْهُمْ","daripada mereka"],["فَلَن","maka tidak pernah"],["يَضُرُّوكَ","adakah mereka akan membahayakan kamu"],["شَيْـًۭٔا ۖ","(dalam) apa-apa"],["وَإِنْ","Dan jika"],["حَكَمْتَ","kamu menilai"],["فَٱحْكُم","kemudian menilai"],["بَيْنَهُم","antara mereka"],["بِٱلْقِسْطِ ۚ","dengan keadilan"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["يُحِبُّ","suka"],["ٱلْمُقْسِطِينَ","mereka yang adil"]]],"712":["(Dan betapa caranya mereka mengangkatmu menjadi hakim mereka padahal di sisi mereka ada Taurat yang memuat hukum Allah) yaitu dengan rajam. Pertanyaan ini menunjukkan keheranan; artinya maksud mereka yang sebenarnya bukanlah untuk mengetahui kebenaran tetapi untuk mencari mana yang lebih ringan (Kemudian mereka berpaling) dari hukum rajammu yang sebenarnya sesuai dengan kitab mereka (setelah demikian itu) setelah diberi keputusan itu (dan tidaklah mereka orang-orang yang sungguh-sungguh beriman.)",[["وَكَيْفَ","Tetapi bagaimana boleh"],["يُحَكِّمُونَكَ","mereka melantik kamu sebagai hakim"],["وَعِندَهُمُ","sedang mereka (berada) bersama mereka"],["ٱلتَّوْرَىٰةُ","Taurat"],["فِيهَا","di dalamnya"],["حُكْمُ","(ialah) Perintah"],["ٱللَّهِ","(milik) Allah"],["ثُمَّ","Kemudian"],["يَتَوَلَّوْنَ","mereka berpaling"],["مِنۢ","daripada"],["بَعْدِ","selepas"],["ذَٰلِكَ ۚ","bahawa"],["وَمَآ","dan bukan"],["أُو۟لَـٰٓئِكَ","mereka"],["بِٱلْمُؤْمِنِينَ","(ialah) orang-orang yang beriman"]]],"713":["(Sesungguhnya Kami telah menurunkan Taurat berisi petunjuk) dari kesesatan (dan cahaya) untuk menjelaskan hukum-hukum (yang diambil untuk memutuskan hukum oleh nabi-nabi) dari Bani Israel (yang tunduk) menyerahkan diri kepada Allah (bagi orang-orang Yahudi dan oleh orang-orang alim dan para pendeta) yakni ahli-ahli hukum dari kalangan mereka (dengan apa) disebabkan karena (mereka diminta untuk menyimpan) artinya diberi amanat untuk menjaga oleh Allah (Kitabullah) jangan sampai diubah-ubah (dan mereka menjadi saksi terhadapnya) bahwa ia benar adanya. (Maka janganlah kamu takut akan manusia) hai orang-orang Yahudi dalam menyingkapkan sifat-sifat dan ciri-ciri Muhammad saw. yang kamu ketahui, tentang ayat rajam dan sebagainya (hanya takutlah kepada-Ku) dalam menyembunyikannya (dan janganlah kamu beli, maksudnya, jangan kamu tukar ayat-ayat-Ku dengan harga yang sedikit) berupa harta benda dunia yang kamu dapatkan sebagai imbalan menyembunyikannya. (Siapa yang tidak memutuskan menurut apa yang diturunkan Allah, maka merekalah orang-orang yang kafir) terhadap-Nya.",[["إِنَّآ","Sesungguhnya"],["أَنزَلْنَا","Kami mendedahkan"],["ٱلتَّوْرَىٰةَ","Taurat"],["فِيهَا","di dalamnya"],["هُدًۭى","(adalah) Bimbingan"],["وَنُورٌۭ ۚ","dan cahaya"],["يَحْكُمُ","dihakimi"],["بِهَا","olehnya"],["ٱلنَّبِيُّونَ","para Nabi"],["ٱلَّذِينَ","orang yang"],["أَسْلَمُوا۟","telah berserah diri (kepada Allah)"],["لِلَّذِينَ","bagi mereka yang"],["هَادُوا۟","adalah orang Yahudi"],["وَٱلرَّبَّـٰنِيُّونَ","dan para Rabbi"],["وَٱلْأَحْبَارُ","dan para ulama"],["بِمَا","dengan apa"],["ٱسْتُحْفِظُوا۟","mereka telah diamanahkan"],["مِن","daripada"],["كِتَـٰبِ","(the) Buku"],["ٱللَّهِ","(milik) Allah"],["وَكَانُوا۟","dan mereka"],["عَلَيْهِ","kepadanya"],["شُهَدَآءَ ۚ","saksi"],["فَلَا","Jadi (jangan)"],["تَخْشَوُا۟","bertakwa"],["ٱلنَّاسَ","manusia"],["وَٱخْشَوْنِ","tetapi takutlah kepada-Ku"],["وَلَا","dan jangan"],["تَشْتَرُوا۟","jual"],["بِـَٔايَـٰتِى","Ayat-ayat Aku"],["ثَمَنًۭا","(untuk) harga"],["قَلِيلًۭا ۚ","sedikit"],["وَمَن","Dan sesiapa"],["لَّمْ","tidak"],["يَحْكُم","hakim"],["بِمَآ","oleh apa"],["أَنزَلَ","telah mendedahkan"],["ٱللَّهُ","Allah"],["فَأُو۟لَـٰٓئِكَ","kemudian mereka"],["هُمُ","[mereka]"],["ٱلْكَـٰفِرُونَ","(ialah) orang-orang yang kafir"]]],"714":["(Dan telah Kami tetapkan terhadap mereka d dalamnya) maksudnya di dalam Taurat (bahwa jiwa) dibunuh (karena jiwa) yang dibunuhnya (mata) dicongkel (karena mata, hidung) dipancung (karena hidung, telinga) dipotong (karena telinga, gigi) dicabut (karena gigi) menurut satu qiraat dengan marfu'nya keempat anggota tubuh tersebut (dan luka-luka pun) manshub atau marfu' (berlaku kisas) artinya dilaksanakan padanya hukum balas jika mungkin; seperti tangan, kaki, kemaluan dan sebagainya. Hukuman ini walaupun diwajibkan atas mereka tetapi ditaqrirkan atau diakui tetap berlaku dalam syariat kita. (Siapa menyedekahkannya) maksudnya menguasai dirinya dengan melepas hak kisas itu (maka itu menjadi penebus dosanya) atas kesalahannya (dan siapa yang tidak memutuskan dengan apa yang diturunkan Allah) seperti kisas dan lain-lain (merekalah orang-orang yang aniaya).",[["وَكَتَبْنَا","Dan Kami tetapkan"],["عَلَيْهِمْ","bagi mereka"],["فِيهَآ","di dalamnya"],["أَنَّ","itu"],["ٱلنَّفْسَ","kehidupan"],["بِٱلنَّفْسِ","untuk kehidupan"],["وَٱلْعَيْنَ","dan mata"],["بِٱلْعَيْنِ","untuk mata"],["وَٱلْأَنفَ","dan hidung"],["بِٱلْأَنفِ","untuk hidung"],["وَٱلْأُذُنَ","dan telinga"],["بِٱلْأُذُنِ","untuk telinga"],["وَٱلسِّنَّ","dan gigi"],["بِٱلسِّنِّ","untuk gigi"],["وَٱلْجُرُوحَ","dan (untuk) luka"],["قِصَاصٌۭ ۚ","(adalah) pembalasan"],["فَمَن","Tetapi siapa pun"],["تَصَدَّقَ","memberi sedekah"],["بِهِۦ","dengannya"],["فَهُوَ","maka ia adalah"],["كَفَّارَةٌۭ","kafarat"],["لَّهُۥ ۚ","baginya"],["وَمَن","Dan sesiapa"],["لَّمْ","tidak"],["يَحْكُم","hakim"],["بِمَآ","oleh apa"],["أَنزَلَ","telah mendedahkan"],["ٱللَّهُ","Allah"],["فَأُو۟لَـٰٓئِكَ","kemudian mereka"],["هُمُ","[mereka]"],["ٱلظَّـٰلِمُونَ","(adalah) orang-orang yang zalim"]]],"715":["(Dan Kami iringi jejak-jejak mereka) maksudnya jejak para nabi itu (dengan Isa putra Maryam, membenarkan apa yang berada di depannya) maksudnya yang sebelumnya (berupa Taurat dan Kami berikan kepadanya Injil yang berisi petunjuk) dari kesesatan (dan cahaya) artinya penjelasan bagi hukum-hukum (serta membenarkan) menjadi hal (bagi kitab Taurat yang berada sebelumnya) membenarkan hukum-hukum Taurat (serta menjadi petunjuk dan pengajaran bagi orang-orang yang takwa).",[["وَقَفَّيْنَا","Dan Kami telah mengutus"],["عَلَىٰٓ","pada"],["ءَاثَـٰرِهِم","jejak kaki mereka"],["بِعِيسَى","Isa"],["ٱبْنِ","nak"],["مَرْيَمَ","(dari) Maryam"],["مُصَدِّقًۭا","mengesahkan"],["لِّمَا","apa"],["بَيْنَ","(adalah) antara"],["يَدَيْهِ","tangannya"],["مِنَ","daripada"],["ٱلتَّوْرَىٰةِ ۖ","Taurat"],["وَءَاتَيْنَـٰهُ","dan Kami berikan kepadanya"],["ٱلْإِنجِيلَ","Injeel"],["فِيهِ","di dalamnya"],["هُدًۭى","(adalah) Bimbingan"],["وَنُورٌۭ","dan cahaya"],["وَمُصَدِّقًۭا","dan mengesahkan"],["لِّمَا","apa"],["بَيْنَ","(adalah) antara"],["يَدَيْهِ","tangannya"],["مِنَ","daripada"],["ٱلتَّوْرَىٰةِ","Taurat"],["وَهُدًۭى","dan Petunjuk"],["وَمَوْعِظَةًۭ","dan teguran"],["لِّلْمُتَّقِينَ","untuk Tuhan yang sedar"]]],"716":["(Dan pengikut-pengikut Injil hendaklah memutuskan perkara dengan apa yang diturunkan Allah di dalamnya) berupa hukum-hukum dan menurut satu qiraat walyahkum itu dibaca waliyahkum karena diathafkan pada ma`mul aatainaahu (Dan siapa yang tidak memutuskan perkara dengan apa yang diturunkan Allah, maka mereka itu orang-orang yang fasik.)",[["وَلْيَحْكُمْ","Dan biarkan menilai"],["أَهْلُ","(the) Rakyat"],["ٱلْإِنجِيلِ","(dari) Injeel"],["بِمَآ","oleh apa"],["أَنزَلَ","telah mendedahkan"],["ٱللَّهُ","Allah"],["فِيهِ ۚ","di dalamnya"],["وَمَن","Dan sesiapa"],["لَّمْ","tidak"],["يَحْكُم","hakim"],["بِمَآ","oleh apa"],["أَنزَلَ","telah mendedahkan"],["ٱللَّهُ","Allah"],["فَأُو۟لَـٰٓئِكَ","kemudian mereka"],["هُمُ","[mereka] (adalah)"],["ٱلْفَـٰسِقُونَ","yang durhaka"]]],"717":["(Dan telah Kami turunkan kepadamu) hai Muhammad (kitab) yakni Alquran (dengan kebenaran) berkaitan dengan anzalnaa (membenarkan apa yang terdapat di hadapannya) maksudnya yang sebelumnya (di antara kitab dan menjadi saksi) atau batu ujian (terhadapnya) kitab di sini maksudnya ialah kitab-kitab terdahulu. (Sebab itu putuskanlah perkara mereka) maksudnya antara ahli kitab jika mereka mengadu kepadamu (dengan apa yang diturunkan Allah) kepadamu (dan janganlah kamu mengikuti hawa nafsu mereka) dengan menyimpang (dari kebenaran yang telah datang kepadamu. Bagi tiap-tiap umat di antara kamu Kami beri) hai manusia (aturan dan jalan) maksudnya jalan yang nyata dan agama dan yang akan mereka tempuh. (Sekiranya dikehendaki Allah tentulah kamu dijadikan-Nya satu umat) dengan hanya satu syariat (tetapi) dibagi-bagi-Nya kamu kepada beberapa golongan (untuk mengujimu) mencoba (mengenai apa yang telah diberikan-Nya kepadamu) berupa syariat yang bermacam-macam untuk melihat siapakah di antara kamu yang taat dan siapa pula yang durhaka (maka berlomba-lombalah berbuat kebaikan) berpaculah mengerjakannya. (Hanya kepada Allahlah kembali kamu semua) dengan kebangkitan (maka diberitahukan-Nya kepadamu apa yang kamu perbantahkan itu) yakni mengenai soal agama dan dibalas-Nya setiap kamu menurut amal masing-masing.",[["وَأَنزَلْنَآ","Dan Kami wahyukan"],["إِلَيْكَ","kepada kamu"],["ٱلْكِتَـٰبَ","Kitab"],["بِٱلْحَقِّ","dalam kebenaran"],["مُصَدِّقًۭا","mengesahkan"],["لِّمَا","apa"],["بَيْنَ","(adalah) sebelum ini"],["يَدَيْهِ","tangannya"],["مِنَ","daripada"],["ٱلْكِتَـٰبِ","Kitab"],["وَمُهَيْمِنًا","dan seorang penjaga"],["عَلَيْهِ ۖ","atasnya"],["فَٱحْكُم","Jadi hakim"],["بَيْنَهُم","antara mereka"],["بِمَآ","oleh apa"],["أَنزَلَ","telah mendedahkan"],["ٱللَّهُ ۖ","Allah"],["وَلَا","dan jangan"],["تَتَّبِعْ","ikut"],["أَهْوَآءَهُمْ","keinginan mereka yang sia-sia"],["عَمَّا","apabila"],["جَآءَكَ","telah datang kepada kamu"],["مِنَ","daripada"],["ٱلْحَقِّ ۚ","kebenaran"],["لِكُلٍّۢ","Untuk setiap"],["جَعَلْنَا","Kami telah membuat"],["مِنكُمْ","bagi kamu"],["شِرْعَةًۭ","sebuah undang-undang"],["وَمِنْهَاجًۭا ۚ","dan jalan yang jelas"],["وَلَوْ","Dan jika"],["شَآءَ","(telah) berkehendak"],["ٱللَّهُ","Allah"],["لَجَعَلَكُمْ","Dia (akan) menjadikan kamu"],["أُمَّةًۭ","sesebuah komuniti"],["وَٰحِدَةًۭ","satu"],["وَلَـٰكِن","[dan] tetapi"],["لِّيَبْلُوَكُمْ","untuk menguji kamu"],["فِى","dalam"],["مَآ","apa"],["ءَاتَىٰكُمْ ۖ","Dia (telah) memberikan kamu"],["فَٱسْتَبِقُوا۟","jadi bangsa"],["ٱلْخَيْرَٰتِ ۚ","(kepada) kebaikan"],["إِلَى","Kepada"],["ٱللَّهِ","Allah"],["مَرْجِعُكُمْ","kamu akan kembali"],["جَمِيعًۭا","semua"],["فَيُنَبِّئُكُم","kemudian Dia akan memberitahu kamu"],["بِمَا","tentang apa"],["كُنتُمْ","kamu dahulu"],["فِيهِ","berkenaan dengannya"],["تَخْتَلِفُونَ","berbeza"]]],"718":["(Dan hendaklah kamu putuskan perkara di antara mereka dengan apa yang diturunkan Allah dan janganlah kamu ikuti hawa nafsu mereka dan berhati-hatilah terhadap mereka) agar (supaya mereka) tidak (memfitnahmu) artinya menyesatkanmu (dari sebagian yang telah diturunkan Allah kepadamu. Jika mereka berpaling) dari hukum yang diturunkan dan bermaksud mengubahnya (maka ketahuilah bahwasanya Allah menghendaki akan menimpakan kepada mereka musibah) hukuman di dunia (disebabkan sebagian dosa-dosa mereka) yang mereka perbuat di antaranya berpaling itu. Dan akan membalas semua dosa itu di akhirat kelak. (Dan sesungguhnya banyak di antara manusia itu orang-orang yang fasik.)",[["وَأَنِ","Dan bahawa"],["ٱحْكُم","kamu menilai"],["بَيْنَهُم","antara mereka"],["بِمَآ","oleh apa"],["أَنزَلَ","(telah) mendedahkan"],["ٱللَّهُ","Allah"],["وَلَا","dan jangan"],["تَتَّبِعْ","ikut"],["أَهْوَآءَهُمْ","keinginan mereka yang sia-sia"],["وَٱحْذَرْهُمْ","dan berhati-hatilah terhadap mereka"],["أَن","jangan-jangan"],["يَفْتِنُوكَ","mereka menggoda kamu"],["عَنۢ","daripada"],["بَعْضِ","beberapa"],["مَآ","apa"],["أَنزَلَ","telah mendedahkan"],["ٱللَّهُ","Allah"],["إِلَيْكَ ۖ","kepada kamu"],["فَإِن","Dan jika"],["تَوَلَّوْا۟","mereka berpaling"],["فَٱعْلَمْ","maka ketahuilah itu"],["أَنَّمَا","sahaja"],["يُرِيدُ","berniat"],["ٱللَّهُ","Allah"],["أَن","kepada"],["يُصِيبَهُم","menyeksa mereka"],["بِبَعْضِ","bagi sesetengah orang"],["ذُنُوبِهِمْ ۗ","(dari) dosa-dosa mereka"],["وَإِنَّ","Dan sesungguhnya"],["كَثِيرًۭا","ramai"],["مِّنَ","daripada"],["ٱلنَّاسِ","manusia"],["لَفَـٰسِقُونَ","(adalah) durhaka"]]],"719":["(Apakah hukum jahiliah yang mereka kehendaki) dengan memakai ya dan ta; artinya dengan berpaling itu mereka hanyalah hendak bermanis mulut dan mengambil muka sedangkan pertanyaan di sini berarti sanggahan (dan siapakah) artinya tak seorang pun (yang lebih baik hukumannya daripada Allah bagi kaum) artinya di sisi orang-orang (yang yakin) kepada-Nya. Diistimewakan menyebutkan mereka karena hanya merekalah yang bersedia merenungkan hal ini.",[["أَفَحُكْمَ","Adakah kemudian penghakiman"],["ٱلْجَـٰهِلِيَّةِ","(pada masa) kejahilan"],["يَبْغُونَ ۚ","mereka mencari"],["وَمَنْ","Dan siapakah"],["أَحْسَنُ","lebih baik"],["مِنَ","daripada"],["ٱللَّهِ","Allah"],["حُكْمًۭا","(dalam) penghakiman"],["لِّقَوْمٍۢ","bagi kaum"],["يُوقِنُونَ","(yang) sungguh-sungguh beriman"]]],"720":["(Hai orang-orang yang beriman, janganlah kamu ambil orang-orang Yahudi dan Nasrani menjadi pemimpin) menjadi ikutanmu dan kamu cintai. (Sebagian mereka menjadi pemimpin bagi sebagian lainnya) karena kesatuan mereka dalam kekafiran. (Siapa di antara kamu mengambil mereka sebagai pemimpin, maka dia termasuk di antara mereka) artinya termasuk golongan mereka. (Sesungguhnya Allah tidak menunjuki orang-orang yang aniaya) karena mengambil orang-orang kafir sebagai pemimpin mereka.",[["۞ يَـٰٓأَيُّهَا","Wahai"],["ٱلَّذِينَ","yang"],["ءَامَنُوا۟","beriman"],["لَا","Jangan"],["تَتَّخِذُوا۟","ambil"],["ٱلْيَهُودَ","orang Yahudi"],["وَٱلنَّصَـٰرَىٰٓ","dan orang Kristian"],["أَوْلِيَآءَ ۘ","(sebagai) sekutu"],["بَعْضُهُمْ","Sebahagian daripada mereka"],["أَوْلِيَآءُ","(adalah) sekutu"],["بَعْضٍۢ ۚ","(kepada) orang lain"],["وَمَن","Dan sesiapa"],["يَتَوَلَّهُم","mengambil mereka sebagai sekutu"],["مِّنكُمْ","antara kamu"],["فَإِنَّهُۥ","maka sesungguhnya, dia"],["مِنْهُمْ ۗ","(adalah) daripada mereka"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["لَا","tidak"],["يَهْدِى","panduan"],["ٱلْقَوْمَ","manusia"],["ٱلظَّـٰلِمِينَ","kesalahan itu"]]],"721":["(Maka kamu lihat orang-orang yang di dalam hati mereka ada penyakit) yakni lemah akidahnya seperti Abdullah bin Ubai gembong munafik itu (bersegera kepada mereka) untuk mengambil mereka sebagai pemimpin (seraya katanya) mengemukakan alasan dari sikap mereka itu (\"Kami takut akan mendapat giliran bencana.\") misalnya giliran musim kemarau, kekalahan sedangkan urusan Muhammad tidak berketentuan sehingga tidak dapat membela kami. Berfirman Allah swt.: (Semoga Allah mendatangkan kemenangan) kepada rasul-Nya dengan mengembangkan agama-Nya (atau sesuatu keputusan dari sisi-Nya) misalnya dengan membuka kedok orang-orang munafik dan menyingkapkan rahasia mereka (sehingga mereka atas apa yang mereka rahasiakan dalam diri mereka) berupa keragu-raguan dan mengambil orang-orang kafir itu sebagai pemimpin (menjadi menyesal.)",[["فَتَرَى","Dan kamu lihat"],["ٱلَّذِينَ","mereka"],["فِى","dalam"],["قُلُوبِهِم","hati mereka"],["مَّرَضٌۭ","(adalah) penyakit"],["يُسَـٰرِعُونَ","mereka bersegera"],["فِيهِمْ","kepada mereka"],["يَقُولُونَ","berkata"],["نَخْشَىٰٓ","Kami takut"],["أَن","bahawa"],["تُصِيبَنَا","(boleh) menyerang kita"],["دَآئِرَ ةٌۭ ۚ","satu musibah"],["فَعَسَى","Tetapi mungkin"],["ٱللَّهُ","Allah"],["أَن","[bahawa]"],["يَأْتِىَ","akan membawa"],["بِٱلْفَتْحِ","kemenangan itu"],["أَوْ","atau"],["أَمْرٍۢ","sesuatu keputusan"],["مِّنْ","daripada"],["عِندِهِۦ","(dari) Dia"],["فَيُصْبِحُوا۟","Kemudian mereka akan menjadi"],["عَلَىٰ","bagi"],["مَآ","apa"],["أَسَرُّوا۟","mereka telah bersembunyi"],["فِىٓ","dalam"],["أَنفُسِهِمْ","diri mereka"],["نَـٰدِمِينَ","menyesal"]]],"722":["(Dan berkatalah) dibaca yaquulu marfu` sebagai awal kata dengan memakai wawu atau tidak. Ada pula yang membaca yaquula manshub karena diathafkan kepada ya`tiya (orang-orang yang beriman) kepada kawan-kawan mereka keheranan; yakni jika topeng kedustaan mereka telah disingkapkan (\"Inikah orang-orang yang telah bersumpah dengan nama Allah secara bersungguh-sungguh) artinya sebenar-benarnya bersumpah (bahwa sesungguhnya mereka beserta kamu.\") dalam soal keagamaan. Firman Allah swt.: (\"Gugurlah) rusaklah/binasalah (amal perbuatan mereka yang baik) (maka jadilah mereka orang-orang yang merugi.\") baik di dunia dengan terbukanya rahasia mereka maupun di akhirat dengan datangnya azab dan siksa.",[["وَيَقُولُ","Dan akan berkata"],["ٱلَّذِينَ","orang yang"],["ءَامَنُوٓا۟","beriman"],["أَهَـٰٓؤُلَآءِ","Adakah ini"],["ٱلَّذِينَ","orang yang"],["أَقْسَمُوا۟","bersumpah"],["بِٱللَّهِ","oleh Allah"],["جَهْدَ","terkuat"],["أَيْمَـٰنِهِمْ ۙ","(dari) sumpah mereka"],["إِنَّهُمْ","sesungguhnya, mereka"],["لَمَعَكُمْ ۚ","(ada) bersama kamu"],["حَبِطَتْ","Menjadi tidak bernilai"],["أَعْمَـٰلُهُمْ","perbuatan mereka"],["فَأَصْبَحُوا۟","dan mereka menjadi"],["خَـٰسِرِينَ","(golongan) yang rugi"]]],"723":["(Hai orang-orang yang beriman! Siapa yang murtad) yartadda pakai idgam atau tidak; artinya murtad atau berbalik (di antara kamu dari agamanya) artinya berbalik kafir; ini merupakan pemberitahuan dari Allah swt. tentang berita gaib yang akan terjadi yang telah terlebih dahulu diketahui-Nya. Buktinya setelah Nabi Muhammad saw. wafat segolongan umat keluar dari agama Islam (maka Allah akan mendatangkan) sebagai ganti mereka (suatu kaum yang dicintai oleh Allah dan mereka pun mencintai-Nya) sabda Nabi saw., \"Mereka itu ialah kaum orang ini,\" sambil menunjuk kepada Abu Musa Al-Asyari; riwayat Hakim dalam sahihnya (bersikap lemah lembut terhadap orang-orang mukmin dan bersikap keras) atau tegas (terhadap orang-orang kafir. Mereka berjihad di jalan Allah dan tidak takut akan celaan orang yang suka mencela) dalam hal itu sebagaimana takutnya orang-orang munafik akan celaan orang-orang kafir. (Demikian itu) yakni sifat-sifat yang disebutkan tadi (adalah karunia Allah yang diberikan-Nya kepada siapa yang dikehendaki-Nya dan Allah Maha Luas) karunia-Nya (lagi Maha Mengetahui) akan yang patut menerimanya. Ayat ini turun ketika Ibnu Salam mengadu kepada Rasulullah, \"Wahai Rasulullah! Kaum kami telah mengucilkan kami!\"",[["يَـٰٓأَيُّهَا","Wahai"],["ٱلَّذِينَ","yang"],["ءَامَنُوا۟","beriman"],["مَن","Siapa pun"],["يَرْتَدَّ","berpatah balik"],["مِنكُمْ","antara kamu"],["عَن","daripada"],["دِينِهِۦ","agamanya"],["فَسَوْفَ","kemudian tidak lama lagi"],["يَأْتِى","(akan) dibawa"],["ٱللَّهُ","(oleh) Allah"],["بِقَوْمٍۢ","suatu kaum"],["يُحِبُّهُمْ","yang dikasihiNya"],["وَيُحِبُّونَهُۥٓ","dan mereka mengasihi Dia"],["أَذِلَّةٍ","merendah diri"],["عَلَى","ke arah"],["ٱلْمُؤْمِنِينَ","orang yang beriman"],["أَعِزَّةٍ","(dan) tegas"],["عَلَى","ke arah"],["ٱلْكَـٰفِرِينَ","orang kafir"],["يُجَـٰهِدُونَ","berusaha"],["فِى","dalam"],["سَبِيلِ","jalan"],["ٱللَّهِ","(milik) Allah"],["وَلَا","dan bukan"],["يَخَافُونَ","takut"],["لَوْمَةَ","kesalahan itu"],["لَآئِمٍۢ ۚ","(dari) seorang pengkritik"],["ذَٰلِكَ","Itu"],["فَضْلُ","(ialah) Rahmat"],["ٱللَّهِ","(milik) Allah"],["يُؤْتِيهِ","Dia memberi"],["مَن","yang"],["يَشَآءُ ۚ","Dia kehendaki"],["وَٱللَّهُ","Dan Allah"],["وَٰسِعٌ","(adalah) Merangkumi"],["عَلِيمٌ","Maha Mengetahui"]]],"724":["(Sesungguhnya yang menjadi penolongmu ialah Allah dan rasul-Nya serta orang-orang yang beriman yang mendirikan salat dan menunaikan zakat serta mereka rukuk) maksudnya khusyuk atau melakukan salat sunah.",[["إِنَّمَا","Hanya"],["وَلِيُّكُمُ","sekutu kamu"],["ٱللَّهُ","(ialah) Allah"],["وَرَسُولُهُۥ","dan Rasul-Nya"],["وَٱلَّذِينَ","dan orang yang"],["ءَامَنُوا۟","beriman"],["ٱلَّذِينَ","dan orang yang"],["يُقِيمُونَ","menubuhkan"],["ٱلصَّلَوٰةَ","solat"],["وَيُؤْتُونَ","dan memberi"],["ٱلزَّكَوٰةَ","zakat"],["وَهُمْ","dan mereka"],["رَٰكِعُونَ","(iaitu) orang-orang yang rukuk"]]],"725":["(Siapa yang mengambil Allah dan rasul-Nya serta orang-orang yang beriman sebagai penolongnya) lalu mereka dibela dan ditolongnya pula (maka sesungguhnya golongan agama Allah itulah yang akan menang) yang terjamin dengan pertolongan Allah swt. sedangkan pembelaan seseorang kepada agama Allah itu menjadi bukti bahwa ia dari golongan dan pengikut agama itu.",[["وَمَن","Dan sesiapa"],["يَتَوَلَّ","mengambil sebagai sekutu"],["ٱللَّهَ","Allah"],["وَرَسُولَهُۥ","dan Rasul-Nya"],["وَٱلَّذِينَ","dan orang yang"],["ءَامَنُوا۟","beriman"],["فَإِنَّ","maka sesungguhnya"],["حِزْبَ","(the) parti"],["ٱللَّهِ","(dari) Allah"],["هُمُ","mereka"],["ٱلْغَـٰلِبُونَ","(adalah) orang-orang yang menang"]]],"726":["(Hai orang-orang yang beriman! Janganlah kamu ambil orang-orang yang menjadikan agamamu sebagai olok-olok) ejekan (dan barang permainan di antara) min untuk penjelasan (orang-orang yang diberi Alkitab sebelumnya dan orang-orang kafir) atau orang-orang musyrik; dengan jar dan nashab (sebagai pemimpin dan bertakwalah kepada Allah) dengan tidak mengambil mereka sebagai pemimpin (jika kamu beriman) artinya sungguh-sungguh dalam keimanan kamu itu.",[["يَـٰٓأَيُّهَا","Wahai"],["ٱلَّذِينَ","yang"],["ءَامَنُوا۟","beriman"],["لَا","Jangan"],["تَتَّخِذُوا۟","ambil"],["ٱلَّذِينَ","orang yang"],["ٱتَّخَذُوا۟","ambil"],["دِينَكُمْ","agama kamu"],["هُزُوًۭا","(dalam) ejekan"],["وَلَعِبًۭا","dan menyeronokkan"],["مِّنَ","daripada"],["ٱلَّذِينَ","orang yang"],["أُوتُوا۟","diberi"],["ٱلْكِتَـٰبَ","Kitab"],["مِن","daripada"],["قَبْلِكُمْ","sebelum kamu"],["وَٱلْكُفَّارَ","dan orang-orang kafir"],["أَوْلِيَآءَ ۚ","(sebagai) sekutu"],["وَٱتَّقُوا۟","Dan ketakutan"],["ٱللَّهَ","Allah"],["إِن","jika"],["كُنتُم","kamu"],["مُّؤْمِنِينَ","orang yang beriman"]]],"727":["(Dan) orang-orang yang (apabila kamu menyeru) atau memanggil mereka (untuk salat) yaitu dengan azan (mereka menjadikannya) salat itu (sebagai bahan olok-olok dan permainan) yakni dengan mempermainkan dan menertawakannya. (Demikian itu) maksudnya sikap mereka itu (adalah karena mereka) disebabkan oleh karena mereka (kaum yang tak mau berpikir). Ayat berikut ini diturunkan ketika orang-orang Yahudi menanyakan kepada Nabi saw., \"Kepada rasul-rasul yang manakah kamu beriman?\" Jawabnya, \"Kepada Allah dan kepada apa-apa yang diturunkan kepada kami... sampai akhir ayat.\" Ketika Nabi saw. menyebut nama Isa, mereka berkata, \"Sepengetahuan kami tak ada agama yang lebih buruk dari agamamu!\"",[["وَإِذَا","Dan apabila"],["نَادَيْتُمْ","kamu membuat panggilan"],["إِلَى","bagi"],["ٱلصَّلَوٰةِ","solat"],["ٱتَّخَذُوهَا","mereka mengambilnya"],["هُزُوًۭا","(dalam) ejekan"],["وَلَعِبًۭا ۚ","dan menyeronokkan"],["ذَٰلِكَ","Itu"],["بِأَنَّهُمْ","(adalah) kerana mereka"],["قَوْمٌۭ","(adalah) suatu kaum"],["لَّا","(yang melakukannya) tidak"],["يَعْقِلُونَ","faham"]]],"728":["(Katakanlah, \"Hai ahli kitab! Apakah kamu menyalahkan) menolak (kami hanya karena kami beriman kepada Allah, kepada apa yang diturunkan kepada kami dan apa yang diturunkan sebelumnya) yakni kepada nabi-nabi yang terdahulu (dan bahwa kebanyakan di antara kamu orang-orang yang fasik?\") diathafkan kepada an aamannaa sedangkan maksudnya ialah: tak ada yang kamu salahkan kecuali hanyalah keimanan kami yang rupanya tidak kamu setujui. Sikap tersebut membuat kalian pantas disebut orang-orang yang fasik. Padahal hal ini merupakan hal yang sudah tidak boleh diingkari.",[["قُلْ","Katakanlah"],["يَـٰٓأَهْلَ","Wahai Rakyat"],["ٱلْكِتَـٰبِ","Kitab"],["هَلْ","buat"],["تَنقِمُونَ","kamu berdendam"],["مِنَّآ","[dari] kita"],["إِلَّآ","kecuali"],["أَنْ","bahawa"],["ءَامَنَّا","kami beriman"],["بِٱللَّهِ","kepada Allah"],["وَمَآ","dan apa"],["أُنزِلَ","telah didedahkan"],["إِلَيْنَا","kepada kami"],["وَمَآ","dan apa"],["أُنزِلَ","telah didedahkan"],["مِن","daripada"],["قَبْلُ","sebelum"],["وَأَنَّ","dan bahawa"],["أَكْثَرَكُمْ","kebanyakan kamu"],["فَـٰسِقُونَ","(adalah) durhaka"]]],"729":["(Katakanlah, \"Apakah akan kukabarkan kepadamu) kuberitakan (orang-orang yang lebih buruk) lagi daripada warga (demikian) yang kamu salahkan itu (mengenai pembalasannya) asal artinya ialah pahalanya (di sisi Allah) yaitu (orang yang dikutuk oleh Allah) artinya dijauhkan dari rahmat-Nya (dan dimurkai-Nya serta di antara mereka ada yang dijadikan-Nya kera dan babi) dengan merubah bentuknya (dan) orang (yang menyembah tagut) yakni setan dengan jalan menaatinya. Pada minhum ditekankan arti man pada lafal sebelumnya yang dimaksud ialah orang-orang Yahudi. Menurut satu qiraat dibaca `abuda dengan diidhafatkan kepada yang sesudahnya sebagai isim jamak dari `abd dan dinashabkan karena ma`thuf kepada qiradah. (Mereka itu lebih buruk tempatnya) karena mereka menempati neraka berfungsi sebagai tamyiz (dan lebih tersesat lagi dari jalan yang lurus) dari jalan yang benar. Sawaa` arti asalnya ialah pertengahan. Disebutkan buruk dan lebih tersesat untuk mengimbangi ucapan mereka, 'Sepengetahuan kami tak ada agama yang lebih buruk dari agamamu.'\"",[["قُلْ","Katakanlah"],["هَلْ","hendaklah"],["أُنَبِّئُكُم","aku maklumkan"],["بِشَرٍّۢ","(dari) lebih teruk"],["مِّن","daripada"],["ذَٰلِكَ","bahawa"],["مَثُوبَةً","(sebagai) balasan"],["عِندَ","daripada"],["ٱللَّهِ ۚ","Allah"],["مَن","siapa"],["لَّعَنَهُ","telah (dikutuk)."],["ٱللَّهُ","(oleh) Allah"],["وَغَضِبَ","dan Dia menjadi marah"],["عَلَيْهِ","dengan dia"],["وَجَعَلَ","dan dibuat"],["مِنْهُمُ","daripada mereka"],["ٱلْقِرَدَةَ","[the] beruk"],["وَٱلْخَنَازِيرَ","dan [the] babi"],["وَعَبَدَ","dan (yang) menyembah"],["ٱلطَّـٰغُوتَ ۚ","dewa-dewa palsu"],["أُو۟لَـٰٓئِكَ","Mereka itu"],["شَرٌّۭ","(adalah) lebih teruk"],["مَّكَانًۭا","(dalam) kedudukan"],["وَأَضَلُّ","dan sesat paling jauh"],["عَن","daripada"],["سَوَآءِ","(yang) malah"],["ٱلسَّبِيلِ","cara"]]],"730":["(Dan jika mereka datang kepadamu) yaitu orang-orang Yahudi munafik (mereka berkata, \"Kami beriman,\" padahal mereka masuk) kepadamu dengan membawa (kekafiran dan mereka keluar) daripadamu (dengan membawa kekafiran pula) mereka tidak beriman (dan Allah lebih mengetahui apa yang mereka sembunyikan) itu berupa kemunafikan.",[["وَإِذَا","Dan apabila"],["جَآءُوكُمْ","mereka datang kepada kamu"],["قَالُوٓا۟","mereka berkata"],["ءَامَنَّا","Kami beriman"],["وَقَد","Tetapi yang pasti"],["دَّخَلُوا۟","mereka masuk"],["بِٱلْكُفْرِ","dengan rasa tidak beriman"],["وَهُمْ","dan mereka"],["قَدْ","sudah tentu"],["خَرَجُوا۟","keluar"],["بِهِۦ ۚ","dengannya"],["وَٱللَّهُ","Dan Allah"],["أَعْلَمُ","lebih tahu"],["بِمَا","[dari] apa"],["كَانُوا۟","mereka adalah"],["يَكْتُمُونَ","bersembunyi"]]],"731":["(Dan akan kamu lihat banyak di antara mereka) maksudnya orang-orang Yahudi (bersegera) artinya cepat terlibat dalam (berbuat dosa) kedustaan (dan permusuhan) keaniayaan (serta memakan barang yang haram) seperti uang suap dan lain-lain (sungguh, amat buruklah apa yang mereka kerjakan) itu; yakni perbuatan-perbuatan yang mereka lakukan tadi.",[["وَتَرَىٰ","Dan kamu lihat"],["كَثِيرًۭا","ramai"],["مِّنْهُمْ","daripada mereka"],["يُسَـٰرِعُونَ","menyegerakan"],["فِى","ke dalam"],["ٱلْإِثْمِ","dosa itu"],["وَٱلْعُدْوَٰنِ","dan pelanggaran"],["وَأَكْلِهِمُ","dan makan"],["ٱلسُّحْتَ ۚ","yang terlarang"],["لَبِئْسَ","Pasti jahat"],["مَا","(ialah) apa"],["كَانُوا۟","mereka adalah"],["يَعْمَلُونَ","melakukan"]]],"732":["(Kenapa orang-orang alim dan para pendeta mereka tak melarang mereka mengucapkan dosa) artinya kata-kata dusta (dan memakan barang yang haram? Sungguh, amat buruklah apa yang mereka perbuat itu) yaitu tidak melarang mereka berbuat kejahatan.",[["لَوْلَا","Mengapa (tidak) tidak"],["يَنْهَىٰهُمُ","melarang mereka"],["ٱلرَّبَّـٰنِيُّونَ","para Rabbi"],["وَٱلْأَحْبَارُ","dan para alim ulama"],["عَن","daripada"],["قَوْلِهِمُ","kata-kata mereka"],["ٱلْإِثْمَ","yang berdosa"],["وَأَكْلِهِمُ","dan makan mereka"],["ٱلسُّحْتَ ۚ","(dari) yang haram"],["لَبِئْسَ","Pasti, jahat"],["مَا","(ialah) apa"],["كَانُوا۟","mereka dahulu"],["يَصْنَعُونَ","lakukan"]]],"733":["(Orang-orang Yahudi berkata) setelah mereka ditimpa kesusahan disebabkan mendustakan Nabi saw. padahal selama ini mereka adalah orang-orang yang paling mampu dan paling banyak harta. (\"Tangan Allah terbelenggu.\") artinya dikatup hingga terhalang untuk menyebarkan rezeki kepada kita. Ucapan itu merupakan sindiran terhadap kikirnya Allah swt. buat melimpahkan rezeki. Firman Allah swt.: (\"Tangan merekalah yang dibelenggu.\") dari berbuat kebaikan hingga tak mau melakukannya. Ini sebagai doa terhadap mereka (dan mereka dikutuk disebabkan apa yang telah mereka katakan itu. Bahkan kedua tangan-Nya terbuka lebar) merupakan simbol tentang kiasan tentang sifat Allah Yang Maha Pemurah. Pujian kepada tangan ini untuk menunjukkan banyak dan melimpah-ruah karena segala sesuatu yang diberikan oleh seorang dermawan berupa harta melalui tangannya. (Dia memberi nafkah sebagaimana dikehendaki-Nya) apakah akan diperlapang ataukah akan dipersempit-Nya, tidak satu pun dapat menghalangi-Nya. (Dan apa yang diturunkan kepadamu dari Tuhanmu, berarti akan menambah banyak kedurhakaan dan kekafiran mereka) karena kekafiran mereka kepadanya. (Dan Kami timbulkan di antara mereka permusuhan dan kebencian sampai hari kiamat) hingga setiap golongan menentang dan memusuhi lainnya. (Setiap mereka menyalakan api peperangan) maksudnya untuk memerangi Nabi Muhammad saw. (dipadamkannya oleh Allah) artinya setiap mereka bermaksud, maka ditolak oleh Allah (dan mereka berbuat kerusakan di muka bumi) maksudnya menghancurkannya dengan berbuat maksiat (dan Allah tidak menyukai orang-orang yang berbuat kerusakan).",[["وَقَالَتِ","Dan berkata"],["ٱلْيَهُودُ","orang Yahudi"],["يَدُ","Tangan"],["ٱللَّهِ","(milik) Allah"],["مَغْلُولَةٌ ۚ","(adalah) dirantai"],["غُلَّتْ","Dirantai"],["أَيْدِيهِمْ","tangan mereka"],["وَلُعِنُوا۟","dan mereka telah dilaknat"],["بِمَا","bagi apa"],["قَالُوا۟ ۘ","mereka berkata"],["بَلْ","Bahkan"],["يَدَاهُ","Tangannya"],["مَبْسُوطَتَانِ","(sedang) terbentang"],["يُنفِقُ","Dia berbelanja"],["كَيْفَ","bagaimana"],["يَشَآءُ ۚ","Dia kehendaki"],["وَلَيَزِيدَنَّ","Dan pasti bertambah"],["كَثِيرًۭا","ramai"],["مِّنْهُم","daripada mereka"],["مَّآ","apa"],["أُنزِلَ","telah didedahkan"],["إِلَيْكَ","kepada kamu"],["مِن","daripada"],["رَّبِّكَ","Tuhanmu"],["طُغْيَـٰنًۭا","(dalam) pemberontakan"],["وَكُفْرًۭا ۚ","dan kekufuran"],["وَأَلْقَيْنَا","Dan Kami telah melemparkan"],["بَيْنَهُمُ","antara mereka"],["ٱلْعَدَٰوَةَ","[the] permusuhan"],["وَٱلْبَغْضَآءَ","dan kebencian"],["إِلَىٰ","sehingga"],["يَوْمِ","(the) Hari"],["ٱلْقِيَـٰمَةِ ۚ","Kiamat"],["كُلَّمَآ","setiap masa"],["أَوْقَدُوا۟","mereka menyala"],["نَارًۭا","(the) api"],["لِّلْحَرْبِ","daripada [perang] itu"],["أَطْفَأَهَا","ia (telah) dipadamkan"],["ٱللَّهُ ۚ","(oleh) Allah"],["وَيَسْعَوْنَ","Dan mereka berusaha"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["فَسَادًۭا ۚ","menyebarkan rasuah"],["وَٱللَّهُ","Dan Allah"],["لَا","tidak"],["يُحِبُّ","cinta"],["ٱلْمُفْسِدِينَ","para perasuah"]]],"734":["(Dan sekiranya Ahli Kitab itu beriman) kepada Nabi Muhammad saw. (dan bertakwa) artinya menjaga diri dari kekafiran (pastilah Kami hapus dari mereka kesalahan mereka dan Kami masukkan mereka ke dalam surga-surga kenikmatan).",[["وَلَوْ","Dan jika"],["أَنَّ","bahawa"],["أَهْلَ","(the) Rakyat"],["ٱلْكِتَـٰبِ","Kitab"],["ءَامَنُوا۟","(telah) beriman"],["وَٱتَّقَوْا۟","dan takut (kepada Allah)"],["لَكَفَّرْنَا","sesungguhnya Kami (akan) hapuskan"],["عَنْهُمْ","daripada mereka"],["سَيِّـَٔاتِهِمْ","kejahatan (perbuatan) mereka"],["وَلَأَدْخَلْنَـٰهُمْ","dan sesungguhnya Kami (akan) memasukkan mereka"],["جَنَّـٰتِ","(ke) Taman"],["ٱلنَّعِيمِ","(dari) Kebahagiaan"]]],"735":["(Dan sekiranya mereka menegakkan Taurat dan Injil) mengamalkan ajarannya, di antaranya beriman kepada Nabi saw. (dan apa yang diturunkan kepada mereka) maksudnya kitab-kitab (dari Tuhan mereka, tentulah mereka akan beroleh makanan dari atas mereka dan dari bawah kaki mereka) maksudnya dilapangkan-Nya rezeki dan dilimpahkan-Nya atas mereka dari segenap penjuru. (Di antara mereka ada umat) maksudnya golongan (yang adil) yakni mengamalkannya dan mereka itulah yang beriman kepada Nabi saw., seperti Abdullah bin Salam dan kawan-kawannya (tetapi banyak di antara mereka amat jelek atau amat buruk apa yang mereka kerjakan.)",[["وَلَوْ","Dan jika"],["أَنَّهُمْ","bahawa mereka"],["أَقَامُوا۟","telah berdiri teguh"],["ٱلتَّوْرَىٰةَ","(oleh) Taurat"],["وَٱلْإِنجِيلَ","dan Injeel"],["وَمَآ","dan apa"],["أُنزِلَ","telah didedahkan"],["إِلَيْهِم","kepada mereka"],["مِّن","daripada"],["رَّبِّهِمْ","Tuhan mereka"],["لَأَكَلُوا۟","nescaya mereka (akan) makan"],["مِن","daripada"],["فَوْقِهِمْ","di atas mereka"],["وَمِن","dan daripada"],["تَحْتِ","di bawah"],["أَرْجُلِهِم ۚ","kaki mereka"],["مِّنْهُمْ","Antaranya"],["أُمَّةٌۭ","(adalah) sebuah komuniti"],["مُّقْتَصِدَةٌۭ ۖ","sederhana"],["وَكَثِيرٌۭ","tapi ramai"],["مِّنْهُمْ","daripada mereka"],["سَآءَ","jahat"],["مَا","(ialah) apa"],["يَعْمَلُونَ","mereka lakukan"]]],"736":["(Hai rasul, sampaikanlah) semua (yang diturunkan kepadamu dari Tuhanmu) dan janganlah kamu sembunyikan sesuatu pun daripadanya karena takut akan mendapatkan hal-hal yang tidak diinginkan (dan jika tidak kamu lakukan) tidak kamu sampaikan semua yang diturunkan padamu itu (berarti kamu tidak menyampaikan risalah-Nya) risalah dengan tunggal atau jamak karena menyembunyikan sebagian berarti menyembunyikan semuanya. (Dan Allah memelihara kamu dari manusia) agar tidak sampai membunuhmu. Pada mulanya Rasulullah saw. itu dikawal sampai turun ayat ini, lalu sabdanya, \"Pergilah karena sesungguhnya Allah memeliharaku!\" Riwayat Hakim. (Sesungguhnya Allah tidak memberikan bimbingan kepada kaum yang kafir.)",[["۞ يَـٰٓأَيُّهَا","Wahai"],["ٱلرَّسُولُ","Utusan"],["بَلِّغْ","sampaikan"],["مَآ","apa"],["أُنزِلَ","telah didedahkan"],["إِلَيْكَ","kepada kamu"],["مِن","daripada"],["رَّبِّكَ ۖ","Tuhanmu"],["وَإِن","dan jika"],["لَّمْ","tidak"],["تَفْعَلْ","kamu lakukan"],["فَمَا","maka tidak"],["بَلَّغْتَ","kamu (telah) sampaikan"],["رِسَالَتَهُۥ ۚ","Mesej beliau"],["وَٱللَّهُ","Dan Allah"],["يَعْصِمُكَ","akan melindungi kamu"],["مِنَ","daripada"],["ٱلنَّاسِ ۗ","manusia"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["لَا","tidak"],["يَهْدِى","panduan"],["ٱلْقَوْمَ","manusia"],["ٱلْكَـٰفِرِينَ","yang kafir"]]],"737":["(Katakanlah \"Hai Ahli Kitab! Kamu tidaklah berada dalam sesuatu agama) tidak dianggap beragama (hingga kamu menjalankan Taurat dan Injil dan apa yang diturunkan kepadamu dari Tuhanmu) yakni dengan mengamalkan apa yang terdapat di dalamnya, di antaranya beriman kepadaku. (Sesungguhnya apa yang diturunkan kepadamu dari Tuhanmu hanyalah akan menambah kedurhakaan dan kekafiran kepada kebanyakan mereka) maksudnya bahwa disebabkan kekafiran mereka tadi, maka Alquran yang diturunkan padamu itu hanyalah menambah kekafiran dan kedurhakaan mereka, jadi bukan petunjuk dan keimanan. (Maka janganlah kamu berduka-cita) atau bersedih hati (terhadap orang-orang yang kafir.\") jika mereka tak mau beriman, tidak usah mereka itu dihiraukan.",[["قُلْ","Katakanlah"],["يَـٰٓأَهْلَ","Wahai Rakyat"],["ٱلْكِتَـٰبِ","Kitab"],["لَسْتُمْ","kamu bukan"],["عَلَىٰ","pada"],["شَىْءٍ","sesuatu"],["حَتَّىٰ","sehingga"],["تُقِيمُوا۟","kamu berdiri teguh"],["ٱلتَّوْرَىٰةَ","(oleh) Taurat"],["وَٱلْإِنجِيلَ","dan Injeel"],["وَمَآ","dan apa"],["أُنزِلَ","telah didedahkan"],["إِلَيْكُم","kepada kamu"],["مِّن","daripada"],["رَّبِّكُمْ ۗ","Tuhanmu"],["وَلَيَزِيدَنَّ","Dan pasti bertambah"],["كَثِيرًۭا","ramai"],["مِّنْهُم","daripada mereka"],["مَّآ","apa"],["أُنزِلَ","telah didedahkan"],["إِلَيْكَ","kepada kamu"],["مِن","daripada"],["رَّبِّكَ","Tuhanmu"],["طُغْيَـٰنًۭا","(dalam) pemberontakan"],["وَكُفْرًۭا ۖ","dan kekufuran"],["فَلَا","Jadi (jangan)"],["تَأْسَ","bersedih"],["عَلَى","atas"],["ٱلْقَوْمِ","manusia"],["ٱلْكَـٰفِرِينَ","yang kafir"]]],"738":["(Sesungguhnya orang-orang mukmin orang-orang Yahudi) menjadi mubtada (kaum Shabiin) satu sekte dari Yahudi (dan orang-orang Nasrani) yang menjadi badal dari mubtada ialah (siapa saja yang benar-benar beriman) dari kalangan mereka (kepada Allah, hari kemudian dan beramal saleh, maka tidak ada kekhawatiran terhadap mereka dan tidak pula mereka bersedih hati) dalam menghadapi hari kemudian sebagai khabar dari mubtada dan yang menunjukkan kepada khabarnya inna.",[["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","orang yang"],["ءَامَنُوا۟","beriman"],["وَٱلَّذِينَ","dan orang yang"],["هَادُوا۟","menjadi Yahudi"],["وَٱلصَّـٰبِـُٔونَ","dan golongan Sabian"],["وَٱلنَّصَـٰرَىٰ","dan orang Kristian"],["مَنْ","sesiapa sahaja"],["ءَامَنَ","beriman"],["بِٱللَّهِ","kepada Allah"],["وَٱلْيَوْمِ","dan Hari"],["ٱلْـَٔاخِرِ","yang Terakhir"],["وَعَمِلَ","dan lakukan"],["صَـٰلِحًۭا","perbuatan baik"],["فَلَا","maka tidak"],["خَوْفٌ","bertakwa"],["عَلَيْهِمْ","ke atas mereka"],["وَلَا","dan bukan"],["هُمْ","mereka"],["يَحْزَنُونَ","akan bersedih"]]],"739":["(Sesungguhnya Kami telah mengambil perjanjian dari Bani Israel) untuk beriman kepada Allah dan Rasul-Nya (dan telah Kami utus kepada mereka rasul-rasul tetapi setiap datang kepada mereka seorang rasul) dari kalangan mereka sendiri (dengan membawa apa yang tidak diingini oleh hawa nafsu mereka) yaitu berupa perkara yang hak/benar maka mereka tidak mempercayainya (sebagian) dari rasul-rasul itu (mereka dustakan dan sebagian yang lain) dari rasul-rasul itu (mereka bunuh) seperti Nabi Zakaria dan Nabi Yahya. Pengungkapan dengan lafal yaqtuluuna/fi`il mudhari` bukannya dengan lafal qataluu/fi`il madhi menggambarkan tentang keadaan yang sedang berlangsung di masa lalu karena adanya fashilah/pemisah.",[["لَقَدْ","Sungguh"],["أَخَذْنَا","Kami ambil"],["مِيثَـٰقَ","sebuah Perjanjian"],["بَنِىٓ","(daripada) Kanak-kanak"],["إِسْرَٰٓءِيلَ","(dari) Israel"],["وَأَرْسَلْنَآ","dan Kami utuskan"],["إِلَيْهِمْ","kepada mereka"],["رُسُلًۭا ۖ","Utusan"],["كُلَّمَا","apabila-apabila masa"],["جَآءَهُمْ","datang kepada mereka"],["رَسُولٌۢ","mana-mana Rasul"],["بِمَا","dengan apa"],["لَا","tidak"],["تَهْوَىٰٓ","dikehendaki"],["أَنفُسُهُمْ","jiwa mereka"],["فَرِيقًۭا","satu kumpulan"],["كَذَّبُوا۟","mereka menafikan"],["وَفَرِيقًۭا","dan kumpulan"],["يَقْتُلُونَ","mereka membunuh"]]],"740":["(Dan mereka mengira) mereka menduga (bahwa tidak akan terjadi) dengan dibaca rafa` maka an menjadi mukhaffafah/tidak beramal dan dibaca nashab maka an dapat menashabkan/beramal; artinya tidak bakalan terjadi (fitnah) siksaan yang menimpa diri mereka sebagai balasan dari perbuatan mendustakan para rasul dan berani membunuh mereka (sebagai akibatnya mereka menjadi buta) dari perkara yang hak hingga mereka tidak bisa melihatnya (dan mereka menjadi tuli) tidak bisa mendengar perkara yang hak (kemudian Allah menerima tobat mereka) tatkala mereka mau bertobat (kemudian mereka kembali menjadi buta dan tuli) untuk kedua kalinya (demikianlah kebanyakan dari kalangan mereka) lafal katsiirun sebagai dhamir/kata ganti (dan Allah Maha Melihat terhadap apa yang mereka kerjakan) untuk itu Ia membalas mereka sesuai dengan apa-apa yang telah mereka kerjakan.",[["وَحَسِبُوٓا۟","Dan mereka berfikir"],["أَلَّا","itu tidak"],["تَكُونَ","akan menjadi (untuk mereka)"],["فِتْنَةٌۭ","perbicaraan"],["فَعَمُوا۟","jadi mereka menjadi buta"],["وَصَمُّوا۟","dan mereka menjadi pekak"],["ثُمَّ","Kemudian"],["تَابَ","berpaling"],["ٱللَّهُ","Allah"],["عَلَيْهِمْ","kepada mereka"],["ثُمَّ","kemudian (sekali lagi)"],["عَمُوا۟","mereka menjadi buta"],["وَصَمُّوا۟","dan mereka menjadi pekak"],["كَثِيرٌۭ","ramai"],["مِّنْهُمْ ۚ","daripada mereka"],["وَٱللَّهُ","Dan Allah"],["بَصِيرٌۢ","(ialah) Maha Melihat"],["بِمَا","tentang apa"],["يَعْمَلُونَ","mereka lakukan"]]],"741":["(Sesungguhnya telah kafirlah orang-orang yang mengatakan, \"Sesungguhnya Allah ialah Almasih putra Maryam.\") di masa sebelumnya telah terjadi hal yang serupa (padahal telah berkata) kepada mereka (Almasih, \"Hai Bani Israel, sembahlah Allah Tuhanku dan Tuhanmu) sesungguhnya aku ini hanyalah seorang hamba Allah dan bukan Tuhan (sesungguhnya orang-orang yang mempersekutukan sesuatu dengan Allah) menyembah kepada selain Allah (maka pasti Allah mengharamkan kepadanya surga) Allah melarangnya untuk memasuki surga (dan tempatnya ialah neraka dan tidak ada bagi orang-orang lalim itu seorang) lafal min adalah tambahan (penolong.\") yang dapat mencegah siksaan Allah terhadap diri mereka.",[["لَقَدْ","Sungguh"],["كَفَرَ","kufur"],["ٱلَّذِينَ","orang yang"],["قَالُوٓا۟","berkata"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["هُوَ","Dia"],["ٱلْمَسِيحُ","(ialah) Mesias"],["ٱبْنُ","nak"],["مَرْيَمَ ۖ","(dari) Maryam"],["وَقَالَ","Sambil berkata"],["ٱلْمَسِيحُ","Mesias"],["يَـٰبَنِىٓ","Wahai Kanak-kanak"],["إِسْرَٰٓءِيلَ","(dari) Israel"],["ٱعْبُدُوا۟","Ibadah"],["ٱللَّهَ","Allah"],["رَبِّى","Tuhanku"],["وَرَبَّكُمْ ۖ","dan Tuhanmu"],["إِنَّهُۥ","Sesungguhnya dia"],["مَن","yang"],["يُشْرِكْ","rakan kongsi bersekutu"],["بِٱللَّهِ","dengan Allah"],["فَقَدْ","maka pasti"],["حَرَّمَ","(telah) melarang"],["ٱللَّهُ","Allah"],["عَلَيْهِ","baginya"],["ٱلْجَنَّةَ","Syurga"],["وَمَأْوَىٰهُ","dan tempat tinggalnya"],["ٱلنَّارُ ۖ","(akan menjadi) Neraka"],["وَمَا","Dan tidak"],["لِلظَّـٰلِمِينَ","bagi orang-orang yang zalim"],["مِنْ","sebarang"],["أَنصَارٍۢ","pembantu"]]],"742":["(Sesungguhnya telah kafirlah orang-orang yang mengatakan, \"Bahwasanya Allah salah seorang) dari tuhan (yang tiga) artinya salah seorang dari tuhan-tuhan yang jumlahnya tiga dan dua orang lainnya yang dianggap tuhan ialah Nabi Isa beserta ibunya. Mereka yang berpendapat demikian adalah golongan dari orang-orang Nasrani (padahal sekali-kali tidak ada Tuhan selain dari Tuhan Yang Esa. Dan jika mereka tidak berhenti dari apa yang mereka katakan itu) berhenti dari menigakan Allah, kemudian kembali mengesakan-Nya (pasti akan menimpa kepada orang-orang yang kafir) artinya mereka yang menetapi kekafirannya (di antara mereka siksaan yang pedih\") siksaan yang sungguh amat memedihkan, yaitu siksaan neraka.",[["لَّقَدْ","Sungguh"],["كَفَرَ","kufur"],["ٱلَّذِينَ","orang yang"],["قَالُوٓا۟","berkata"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["ثَالِثُ","(ialah) ketiga"],["ثَلَـٰثَةٍۢ ۘ","(daripada) tiga"],["وَمَا","Dan (ada) tidak"],["مِنْ","[daripada]"],["إِلَـٰهٍ","tuhan"],["إِلَّآ","kecuali"],["إِلَـٰهٌۭ","(yang) Tuhan"],["وَٰحِدٌۭ ۚ","(yang) Satu"],["وَإِن","Dan jika"],["لَّمْ","tidak"],["يَنتَهُوا۟","mereka berhenti"],["عَمَّا","daripada apa"],["يَقُولُونَ","mereka berkata"],["لَيَمَسَّنَّ","pasti akan menyusahkan"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["مِنْهُمْ","antara mereka"],["عَذَابٌ","azab"],["أَلِيمٌ","yang pedih"]]],"743":["(Maka mengapa mereka tidak bertobat kepada Allah dan memohon ampun kepada-Nya) atas apa yang telah mereka katakan; pertanyaan di sini menunjukkan kepada makna celaan. (Dan Allah Maha Pengampun) terhadap orang yang mau bertobat (lagi Maha Penyayang) kepadanya.",[["أَفَلَا","Jadi tidak akan"],["يَتُوبُونَ","mereka bertaubat"],["إِلَى","kepada"],["ٱللَّهِ","Allah"],["وَيَسْتَغْفِرُونَهُۥ ۚ","dan memohon ampun kepada-Nya"],["وَٱللَّهُ","Dan Allah"],["غَفُورٌۭ","Maha Pengampun"],["رَّحِيمٌۭ","Maha Mengasihani"]]],"744":["(Almasih putra Maryam itu hanyalah seorang rasul yang sesungguhnya telah berlalu) telah lewat (sebelumnya beberapa rasul) maka dia pun akan berlalu/mati seperti mereka; dia bukanlah Tuhan seperti apa yang telah mereka sangkakan, jika memang demikian maka niscaya ia pun tidak akan berlalu/mati (dan ibunya seorang yang amat benar) seorang wanita yang teramat benar (keduanya biasa memakan makanan) sama seperti makhluk-makhluk hidup lainnya, maka siapa pun yang keadaannya demikian berarti dia bukanlah Tuhan karena ia masih membutuhkan makanan, lemah dan masih mengeluarkan kencing dan kotoran sebagai akibat dari makanan itu. (Perhatikanlah) dengan penuh rasa ketakjuban (bagaimana Kami menjelaskan kepada mereka, ahli kitab, tanda-tanda kekuasaan Kami) yang menunjukkan keesaan Kami (kemudian perhatikanlah bagaimana) lafal annaa adalah kata tanya (mendustakannya) mereka berpaling dari perkara hak yang disertai dengan bukti yang jelas.",[["مَّا","Tidak"],["ٱلْمَسِيحُ","(ialah) Mesias"],["ٱبْنُ","nak"],["مَرْيَمَ","(dari) Maryam"],["إِلَّا","tetapi"],["رَسُولٌۭ","seorang Rasul"],["قَدْ","sudah tentu"],["خَلَتْ","telah berlalu"],["مِن","daripada"],["قَبْلِهِ","sebelum dia"],["ٱلرُّسُلُ","para Rasul"],["وَأُمُّهُۥ","Dan ibunya"],["صِدِّيقَةٌۭ ۖ","(adalah) benar"],["كَانَا","Mereka berdua dulu"],["يَأْكُلَانِ","makan"],["ٱلطَّعَامَ ۗ","[the] makanan"],["ٱنظُرْ","Lihat"],["كَيْفَ","bagaimana"],["نُبَيِّنُ","Kami jelaskan"],["لَهُمُ","kepada mereka"],["ٱلْـَٔايَـٰتِ","Tanda-tanda"],["ثُمَّ","kemudian"],["ٱنظُرْ","lihat"],["أَنَّىٰ","bagaimana"],["يُؤْفَكُونَ","mereka tertipu"]]],"745":["(Katakanlah, \"Mengapa kamu menyembah selain daripada Allah) selain-Nya (sesuatu yang tidak dapat memberi mara bahaya kepadamu dan tidak pula memberi manfaat?\" Dan Allahlah Yang Maha Mendengar) terhadap perkataan-perkataanmu (lagi Maha Mengetahui) tentang tindak-tandukmu; kata istifham/kata tanya di sini menunjukkan keingkaran.",[["قُلْ","Katakanlah"],["أَتَعْبُدُونَ","Adakah kamu menyembah"],["مِن","daripada"],["دُونِ","selain"],["ٱللَّهِ","Allah"],["مَا","apa"],["لَا","tidak"],["يَمْلِكُ","mempunyai kuasa"],["لَكُمْ","untuk (menyebabkan) kamu"],["ضَرًّۭا","sebarang kemudaratan"],["وَلَا","dan bukan"],["نَفْعًۭا ۚ","sebarang faedah"],["وَٱللَّهُ","sedangkan Allah"],["هُوَ","Dia"],["ٱلسَّمِيعُ","(ialah) Yang Maha Mendengar"],["ٱلْعَلِيمُ","yang Maha Mengetahui"]]],"746":["(Katakanlah, \"Hai Ahli Kitab!) para pemeluk agama Yahudi dan agama Nasrani (Janganlah kamu berlebih-lebihan) janganlah kamu melampaui batas (dalam agamamu) secara berlebih-lebihan (dengan cara tidak benar) yaitu dengan cara merendahkan Nabi Isa atau kamu mengangkatnya secara berlebihan dari apa yang seharusnya (dan janganlah kamu mengikuti hawa nafsu orang-orang yang telah sesat dahulunya sebelum kedatangan Nabi Muhammad) mengikuti cara berlebih-lebihan yang pernah dilakukan oleh para pendahulu mereka (dan mereka telah menyesatkan kebanyakan) manusia (dan mereka tersesat dari jalan yang lurus.\") jalan yang hak; lafal as-sawaa` asalnya bermakna pertengahan.",[["قُلْ","Katakanlah"],["يَـٰٓأَهْلَ","Wahai Rakyat"],["ٱلْكِتَـٰبِ","Kitab"],["لَا","Jangan"],["تَغْلُوا۟","melebihi"],["فِى","dalam"],["دِينِكُمْ","agama kamu"],["غَيْرَ","selain daripada"],["ٱلْحَقِّ","kebenaran"],["وَلَا","dan jangan"],["تَتَّبِعُوٓا۟","ikut"],["أَهْوَآءَ","keinginan (sia-sia)."],["قَوْمٍۢ","(dari) suatu kaum"],["قَدْ","sudah tentu"],["ضَلُّوا۟","yang sesat"],["مِن","daripada"],["قَبْلُ","sebelum"],["وَأَضَلُّوا۟","dan mereka menyesatkan"],["كَثِيرًۭا","ramai"],["وَضَلُّوا۟","dan mereka telah sesat"],["عَن","daripada"],["سَوَآءِ","(yang) betul"],["ٱلسَّبِيلِ","[cara]"]]],"747":["(Telah dilaknat orang-orang kafir dari Bani Israel melalui lisan Daud) yaitu Nabi Daud mendoakan/menyerapah mereka hingga mereka berubah ujud menjadi kera-kera; mereka adalah orang-orang dari kalangan Bani Israel yang menduduki tanah Ailah (dan Isa putra Maryam) yaitu Nabi Isa mendoakan/menyerapah mereka sehingga mereka berubah ujud menjadi babi-babi; mereka adalah orang-orang Bani Israel yang memiliki Al-Maidah/hidangan yang didatangkan dari langit (yang demikian itu) adalah laknat (disebabkan mereka durhaka dan melampaui batas).",[["لُعِنَ","Dikutuk"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["مِنۢ","daripada"],["بَنِىٓ","(the) Kanak-kanak"],["إِسْرَٰٓءِيلَ","(dari) Israel"],["عَلَىٰ","oleh"],["لِسَانِ","(the) lidah"],["دَاوُۥدَ","(daripada) Dawud"],["وَعِيسَى","dan Isa"],["ٱبْنِ","nak"],["مَرْيَمَ ۚ","(dari) Maryam"],["ذَٰلِكَ","itu (adalah)"],["بِمَا","kerana"],["عَصَوا۟","mereka ingkar"],["وَّكَانُوا۟","dan mereka"],["يَعْتَدُونَ","melanggar"]]],"748":["(Mereka satu sama lain tidak pernah melarang) artinya sebagian di antara mereka tidak pernah melarang sebagian lainnya (dari) kebiasaan (tindakan mungkar yang biasa mereka perbuat. Sesungguhnya amat buruklah apa yang selalu mereka perbuat) kebiasaan mereka dalam melakukan perbuatan mungkar itu.",[["كَانُوا۟","Mereka telah"],["لَا","tidak"],["يَتَنَاهَوْنَ","saling melarang"],["عَن","daripada"],["مُّنكَرٍۢ","salah laku"],["فَعَلُوهُ ۚ","mereka melakukannya"],["لَبِئْسَ","Pasti, jahat"],["مَا","(adalah) apa"],["كَانُوا۟","mereka adalah"],["يَفْعَلُونَ","melakukan"]]],"749":["(Kamu melihat) wahai Muhammad (kebanyakan dari mereka tolong-menolong dengan orang-orang yang kafir/musyrik) dari kalangan penduduk Mekah karena membencimu. (Sesungguhnya amat buruklah apa yang mereka sediakan untuk diri mereka) yaitu berupa amal perbuatan untuk bekal mereka di akhirat yang akibatnya (Allah murka terhadap mereka dan mereka akan kekal dalam siksaan.)",[["تَرَىٰ","Kamu nampak"],["كَثِيرًۭا","ramai"],["مِّنْهُمْ","daripada mereka"],["يَتَوَلَّوْنَ","mengambil sebagai sekutu"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟ ۚ","kufur"],["لَبِئْسَ","Pasti jahat"],["مَا","(ialah) apa"],["قَدَّمَتْ","dihantar"],["لَهُمْ","bagi mereka"],["أَنفُسُهُمْ","jiwa mereka"],["أَن","bahawa"],["سَخِطَ","menjadi marah"],["ٱللَّهُ","Allah"],["عَلَيْهِمْ","bersama mereka"],["وَفِى","dan dalam"],["ٱلْعَذَابِ","azab"],["هُمْ","mereka"],["خَـٰلِدُونَ","(akan) kekal selama-lamanya"]]],"750":["(Sekiranya mereka beriman kepada Allah, kepada Nabi) Muhammad (dan kepada apa yang diturunkan kepadanya niscaya mereka tidak akan mengambil orang-orang musyrik itu) orang-orang kafir (menjadi penolong-penolong tetapi kebanyakan dari mereka adalah orang-orang yang fasik/durhaka) mereka adalah orang-orang yang menyimpang dari keimanan.",[["وَلَوْ","Dan jika"],["كَانُوا۟","mereka telah"],["يُؤْمِنُونَ","beriman"],["بِٱللَّهِ","kepada Allah"],["وَٱلنَّبِىِّ","dan Nabi"],["وَمَآ","dan apa"],["أُنزِلَ","telah didedahkan"],["إِلَيْهِ","kepadanya"],["مَا","tidak"],["ٱتَّخَذُوهُمْ","mereka (akan) mengambilnya"],["أَوْلِيَآءَ","(sebagai) sekutu"],["وَلَـٰكِنَّ","[dan] tetapi"],["كَثِيرًۭا","ramai"],["مِّنْهُمْ","daripada mereka"],["فَـٰسِقُونَ","(adalah) durhaka"]]]});